[[nodiscard]] HWND FindVisibleDxUiContextMenuWindow() noexcept
{
    const HWND hwnd = FindWindowW(L"DxUi_ContextMenu", nullptr);
    return (hwnd && IsWindowVisible(hwnd) != FALSE) ? hwnd : nullptr;
}

[[nodiscard]] std::vector<HWND> FindVisibleOwnedDxUiContextMenuWindows(HWND ownerHwnd) noexcept
{
    std::vector<HWND> windows;
    const HWND rootOwner = ownerHwnd ? GetAncestor(ownerHwnd, GA_ROOT) : nullptr;
    for (HWND popup = FindWindowW(L"DxUi_ContextMenu", nullptr); popup != nullptr; popup = FindWindowExW(nullptr, popup, L"DxUi_ContextMenu", nullptr))
    {
        if (IsWindowVisible(popup) == FALSE)
        {
            continue;
        }

        if (ownerHwnd)
        {
            const HWND popupOwner     = GetWindow(popup, GW_OWNER);
            const HWND popupRootOwner = GetAncestor(popup, GA_ROOTOWNER);
            if (popupOwner != ownerHwnd && popupOwner != rootOwner && popupRootOwner != ownerHwnd && popupRootOwner != rootOwner &&
                (popupOwner == nullptr || IsChild(ownerHwnd, popupOwner) == FALSE))
            {
                continue;
            }
        }

        windows.push_back(popup);
    }

    return windows;
}

[[nodiscard]] HWND FindVisibleOwnedDxUiContextMenuWindow(HWND ownerHwnd) noexcept
{
    std::vector<HWND> windows = FindVisibleOwnedDxUiContextMenuWindows(ownerHwnd);
    return windows.empty() ? nullptr : windows.front();
}

[[nodiscard]] HWND WaitForReadableOwnedDxUiContextMenuWindow(HWND ownerHwnd,
                                                             DxUi::ContextMenuPopupDebugState& outState,
                                                             std::chrono::milliseconds timeout) noexcept
{
    using namespace std::chrono_literals;

    const auto deadline = std::chrono::steady_clock::now() + timeout;
    while (std::chrono::steady_clock::now() < deadline)
    {
        PumpPendingMessages();

        for (const HWND popup : FindVisibleOwnedDxUiContextMenuWindows(ownerHwnd))
        {
            DxUi::ContextMenuPopupDebugState popupState{};
            if (popup && IsWindow(popup) != FALSE && DxUi::DebugGetContextMenuPopupState(popup, popupState))
            {
                outState = std::move(popupState);
                return popup;
            }
        }

        std::this_thread::sleep_for(10ms);
    }

    outState = {};
    return nullptr;
}

void PostDxUiContextMenuDismiss(HWND popup, HWND ownerHwnd) noexcept
{
    if (popup && IsWindow(popup) != FALSE)
    {
        PostMessageW(popup, WM_KEYDOWN, VK_ESCAPE, 0);
        PostMessageW(popup, WM_KEYUP, VK_ESCAPE, 0);
        PostMessageW(popup, WM_CANCELMODE, 0, 0);

        const HWND popupOwner = GetWindow(popup, GW_OWNER);
        if (popupOwner && IsWindow(popupOwner) != FALSE)
        {
            PostMessageW(popupOwner, WM_CANCELMODE, 0, 0);
        }
    }

    if (ownerHwnd && IsWindow(ownerHwnd) != FALSE)
    {
        PostMessageW(ownerHwnd, WM_CANCELMODE, 0, 0);
    }
}

[[nodiscard]] bool DismissVisibleOwnedDxUiContextMenus(HWND ownerHwnd, std::chrono::milliseconds timeout) noexcept
{
    using namespace std::chrono_literals;

    const auto deadline = std::chrono::steady_clock::now() + timeout;
    while (std::chrono::steady_clock::now() < deadline)
    {
        const std::vector<HWND> popups = FindVisibleOwnedDxUiContextMenuWindows(ownerHwnd);
        if (popups.empty())
        {
            return true;
        }

        for (const HWND popup : popups)
        {
            PostDxUiContextMenuDismiss(popup, ownerHwnd);
        }

        PumpPendingMessages();
        std::this_thread::sleep_for(20ms);
    }

    return FindVisibleOwnedDxUiContextMenuWindows(ownerHwnd).empty();
}

void JoinPopupDriverWithUiPumping(std::jthread& popupDriver,
                                  const std::atomic<bool>& popupDriverDone,
                                  HWND ownerHwnd,
                                  std::chrono::milliseconds deadlineTimeout) noexcept
{
    using namespace std::chrono_literals;

    std::stop_source popupDriverStopSource = popupDriver.get_stop_source();
    std::jthread dismissalWatchdog([&, popupDriverStopSource](std::stop_token stopToken) mutable noexcept
    {
        const auto deadline = std::chrono::steady_clock::now() + deadlineTimeout;
        while (! stopToken.stop_requested() && ! popupDriverDone.load(std::memory_order_acquire) && std::chrono::steady_clock::now() < deadline)
        {
            std::this_thread::sleep_for(20ms);
        }

        if (stopToken.stop_requested() || popupDriverDone.load(std::memory_order_acquire))
        {
            return;
        }

        popupDriverStopSource.request_stop();
        const auto dismissDeadline = std::chrono::steady_clock::now() + SelfTest::Scale(5000ms);
        while (! stopToken.stop_requested() && ! popupDriverDone.load(std::memory_order_acquire) && std::chrono::steady_clock::now() < dismissDeadline)
        {
            static_cast<void>(DismissVisibleOwnedDxUiContextMenus(ownerHwnd, SelfTest::Scale(250ms)));
            std::this_thread::sleep_for(50ms);
        }
    });

    const auto deadline = std::chrono::steady_clock::now() + deadlineTimeout;
    while (! popupDriverDone.load(std::memory_order_acquire) && std::chrono::steady_clock::now() < deadline)
    {
        PumpPendingMessages();
        std::this_thread::sleep_for(10ms);
    }

    if (! popupDriverDone.load(std::memory_order_acquire))
    {
        popupDriver.request_stop();
        static_cast<void>(DismissVisibleOwnedDxUiContextMenus(ownerHwnd, SelfTest::Scale(2000ms)));
    }

    const auto cleanupDeadline = std::chrono::steady_clock::now() + SelfTest::Scale(5000ms);
    while (! popupDriverDone.load(std::memory_order_acquire) && std::chrono::steady_clock::now() < cleanupDeadline)
    {
        PumpPendingMessages();
        std::this_thread::sleep_for(10ms);
    }

    if (! popupDriverDone.load(std::memory_order_acquire))
    {
        popupDriver.request_stop();
        static_cast<void>(DismissVisibleOwnedDxUiContextMenus(ownerHwnd, SelfTest::Scale(2000ms)));
    }

    if (popupDriver.joinable())
    {
        popupDriver.join();
    }
}

[[nodiscard]] bool WaitForOwnedDxUiContextMenuWindowCount(HWND ownerHwnd,
                                                          size_t expectedCount,
                                                          std::chrono::milliseconds timeout,
                                                          std::vector<HWND>* outWindows = nullptr) noexcept
{
    using namespace std::chrono_literals;

    const auto deadline = std::chrono::steady_clock::now() + timeout;
    while (std::chrono::steady_clock::now() < deadline)
    {
        PumpPendingMessages();

        std::vector<HWND> windows = FindVisibleOwnedDxUiContextMenuWindows(ownerHwnd);
        if (windows.size() >= expectedCount)
        {
            if (outWindows)
            {
                *outWindows = std::move(windows);
            }
            return true;
        }

        std::this_thread::sleep_for(10ms);
    }

    std::vector<HWND> windows = FindVisibleOwnedDxUiContextMenuWindows(ownerHwnd);
    if (outWindows)
    {
        *outWindows = std::move(windows);
    }
    return outWindows ? outWindows->size() >= expectedCount : windows.size() >= expectedCount;
}

struct UiMenuRoundTripResult
{
    bool opened = false;
    bool closed = false;
};

[[nodiscard]] UiMenuRoundTripResult TriggerAndDismissKeyboardActivatedUiMenu(HWND targetHwnd,
                                                                             WPARAM virtualKey,
                                                                             DWORD uiThreadId,
                                                                             HWND ownerHwnd,
                                                                             std::chrono::milliseconds openTimeout,
                                                                             std::chrono::milliseconds closeTimeout) noexcept
{
    using namespace std::chrono_literals;

    std::atomic<bool> menuOpened{false};
    std::atomic<bool> menuClosed{false};

    {
        std::jthread closer([&](std::stop_token stopToken) noexcept
        {
            const auto openDeadline = std::chrono::steady_clock::now() + openTimeout;
            while (! stopToken.stop_requested() && std::chrono::steady_clock::now() < openDeadline)
            {
                GUITHREADINFO gti{};
                gti.cbSize            = sizeof(gti);
                const bool hasGuiInfo = GetGUIThreadInfo(uiThreadId, &gti) != FALSE;
                const bool inMenuMode = hasGuiInfo && (gti.flags & GUI_INMENUMODE) != 0;
                const HWND popup      = FindVisibleOwnedDxUiContextMenuWindow(ownerHwnd);
                if (inMenuMode || popup != nullptr)
                {
                    menuOpened.store(true, std::memory_order_release);
                    break;
                }

                std::this_thread::sleep_for(10ms);
            }

            if (! menuOpened.load(std::memory_order_acquire))
            {
                return;
            }

            const auto closeDeadline = std::chrono::steady_clock::now() + closeTimeout;
            while (! stopToken.stop_requested() && std::chrono::steady_clock::now() < closeDeadline)
            {
                GUITHREADINFO gti{};
                gti.cbSize            = sizeof(gti);
                const bool hasGuiInfo = GetGUIThreadInfo(uiThreadId, &gti) != FALSE;
                const bool inMenuMode = hasGuiInfo && (gti.flags & GUI_INMENUMODE) != 0;
                const HWND popup      = FindVisibleOwnedDxUiContextMenuWindow(ownerHwnd);
                if (! inMenuMode && popup == nullptr)
                {
                    menuClosed.store(true, std::memory_order_release);
                    return;
                }

                const HWND dismissTarget =
                    popup != nullptr ? popup
                                     : (hasGuiInfo && gti.hwndMenuOwner ? gti.hwndMenuOwner : (hasGuiInfo && gti.hwndActive ? gti.hwndActive : ownerHwnd));
                if (dismissTarget != nullptr)
                {
                    PostMessageW(dismissTarget, WM_KEYDOWN, VK_ESCAPE, 0);
                    PostMessageW(dismissTarget, WM_KEYUP, VK_ESCAPE, 0);
                }

                std::this_thread::sleep_for(30ms);
            }

            GUITHREADINFO gti{};
            gti.cbSize            = sizeof(gti);
            const bool hasGuiInfo = GetGUIThreadInfo(uiThreadId, &gti) != FALSE;
            const bool inMenuMode = hasGuiInfo && (gti.flags & GUI_INMENUMODE) != 0;
            const HWND popup      = FindVisibleOwnedDxUiContextMenuWindow(ownerHwnd);
            if (! inMenuMode && popup == nullptr)
            {
                menuClosed.store(true, std::memory_order_release);
            }
        });

        SendMessageW(targetHwnd, WM_KEYDOWN, virtualKey, 0);
        SendMessageW(targetHwnd, WM_KEYUP, virtualKey, 0);
        PumpPendingMessages();
    }

    return UiMenuRoundTripResult{
        .opened = menuOpened.load(std::memory_order_acquire),
        .closed = menuClosed.load(std::memory_order_acquire),
    };
}

[[nodiscard]] UiMenuRoundTripResult TriggerAndDismissCommandActivatedUiMenu(
    HWND targetHwnd, UINT commandId, DWORD uiThreadId, HWND ownerHwnd, std::chrono::milliseconds openTimeout, std::chrono::milliseconds closeTimeout) noexcept
{
    using namespace std::chrono_literals;

    std::atomic<bool> menuOpened{false};
    std::atomic<bool> menuClosed{false};

    {
        std::jthread closer([&](std::stop_token stopToken) noexcept
        {
            const auto openDeadline = std::chrono::steady_clock::now() + openTimeout;
            while (! stopToken.stop_requested() && std::chrono::steady_clock::now() < openDeadline)
            {
                GUITHREADINFO gti{};
                gti.cbSize            = sizeof(gti);
                const bool hasGuiInfo = GetGUIThreadInfo(uiThreadId, &gti) != FALSE;
                const bool inMenuMode = hasGuiInfo && (gti.flags & GUI_INMENUMODE) != 0;
                const HWND popup      = FindVisibleOwnedDxUiContextMenuWindow(ownerHwnd);
                if (inMenuMode || popup != nullptr)
                {
                    menuOpened.store(true, std::memory_order_release);
                    break;
                }

                std::this_thread::sleep_for(10ms);
            }

            if (! menuOpened.load(std::memory_order_acquire))
            {
                return;
            }

            const auto closeDeadline = std::chrono::steady_clock::now() + closeTimeout;
            while (! stopToken.stop_requested() && std::chrono::steady_clock::now() < closeDeadline)
            {
                GUITHREADINFO gti{};
                gti.cbSize            = sizeof(gti);
                const bool hasGuiInfo = GetGUIThreadInfo(uiThreadId, &gti) != FALSE;
                const bool inMenuMode = hasGuiInfo && (gti.flags & GUI_INMENUMODE) != 0;
                const HWND popup      = FindVisibleOwnedDxUiContextMenuWindow(ownerHwnd);
                if (! inMenuMode && popup == nullptr)
                {
                    menuClosed.store(true, std::memory_order_release);
                    return;
                }

                const HWND dismissTarget =
                    popup != nullptr ? popup
                                     : (hasGuiInfo && gti.hwndMenuOwner ? gti.hwndMenuOwner : (hasGuiInfo && gti.hwndActive ? gti.hwndActive : ownerHwnd));
                if (dismissTarget != nullptr)
                {
                    PostMessageW(dismissTarget, WM_KEYDOWN, VK_ESCAPE, 0);
                    PostMessageW(dismissTarget, WM_KEYUP, VK_ESCAPE, 0);
                }

                std::this_thread::sleep_for(30ms);
            }

            GUITHREADINFO gti{};
            gti.cbSize            = sizeof(gti);
            const bool hasGuiInfo = GetGUIThreadInfo(uiThreadId, &gti) != FALSE;
            const bool inMenuMode = hasGuiInfo && (gti.flags & GUI_INMENUMODE) != 0;
            const HWND popup      = FindVisibleOwnedDxUiContextMenuWindow(ownerHwnd);
            if (! inMenuMode && popup == nullptr)
            {
                menuClosed.store(true, std::memory_order_release);
            }
        });

        SendMessageW(targetHwnd, WM_COMMAND, MAKEWPARAM(commandId, 0), 0);
        PumpPendingMessages();
    }

    return UiMenuRoundTripResult{
        .opened = menuOpened.load(std::memory_order_acquire),
        .closed = menuClosed.load(std::memory_order_acquire),
    };
}

[[nodiscard]] bool WaitForContextMenuKeyboardIndex(HWND popupHwnd, size_t expectedIndex, std::chrono::milliseconds timeout) noexcept
{
    using namespace std::chrono_literals;

    const auto deadline = std::chrono::steady_clock::now() + timeout;
    while (std::chrono::steady_clock::now() < deadline)
    {
        PumpPendingMessages();

        DxUi::ContextMenuPopupDebugState popupState{};
        if (DxUi::DebugGetContextMenuPopupState(popupHwnd, popupState) && popupState.keyboardIndex.has_value() &&
            popupState.keyboardIndex.value() == expectedIndex)
        {
            return true;
        }

        std::this_thread::sleep_for(10ms);
    }

    DxUi::ContextMenuPopupDebugState popupState{};
    return DxUi::DebugGetContextMenuPopupState(popupHwnd, popupState) && popupState.keyboardIndex.has_value() &&
           popupState.keyboardIndex.value() == expectedIndex;
}

[[nodiscard]] bool WaitForContextMenuPopupState(HWND popupHwnd,
                                                DxUi::ContextMenuPopupDebugState& outState,
                                                auto&& predicate,
                                                std::chrono::milliseconds timeout) noexcept
{
    using namespace std::chrono_literals;

    const auto deadline = std::chrono::steady_clock::now() + timeout;
    while (std::chrono::steady_clock::now() < deadline)
    {
        PumpPendingMessages();

        DxUi::ContextMenuPopupDebugState popupState{};
        if (popupHwnd && IsWindow(popupHwnd) != FALSE && DxUi::DebugGetContextMenuPopupState(popupHwnd, popupState) && predicate(popupState))
        {
            outState = std::move(popupState);
            return true;
        }

        std::this_thread::sleep_for(10ms);
    }

    outState = {};
    if (popupHwnd && IsWindow(popupHwnd) != FALSE)
    {
        static_cast<void>(DxUi::DebugGetContextMenuPopupState(popupHwnd, outState));
    }
    return false;
}

[[nodiscard]] std::optional<wchar_t> FindFirstTopLevelMenuMnemonic(HMENU mainMenu) noexcept
{
    if (! mainMenu)
    {
        return std::nullopt;
    }

    const int itemCount = GetMenuItemCount(mainMenu);
    for (int itemIndex = 0; itemIndex < itemCount; ++itemIndex)
    {
        const std::wstring itemText = GetMenuItemTextByPosition(mainMenu, itemIndex);
        for (size_t textIndex = 0; textIndex + 1u < itemText.size(); ++textIndex)
        {
            if (itemText[textIndex] != L'&')
            {
                continue;
            }

            const wchar_t next = itemText[textIndex + 1u];
            if (next == L'&')
            {
                ++textIndex;
                continue;
            }

            return static_cast<wchar_t>(std::towupper(next));
        }
    }

    return std::nullopt;
}

[[nodiscard]] std::optional<wchar_t> FindTopLevelMenuMnemonic(HMENU mainMenu, size_t itemIndex) noexcept
{
    if (! mainMenu)
    {
        return std::nullopt;
    }

    const int itemCount = GetMenuItemCount(mainMenu);
    if (itemIndex >= static_cast<size_t>((std::max)(itemCount, 0)))
    {
        return std::nullopt;
    }

    const std::wstring itemText = GetMenuItemTextByPosition(mainMenu, static_cast<int>(itemIndex));
    for (size_t textIndex = 0; textIndex + 1u < itemText.size(); ++textIndex)
    {
        if (itemText[textIndex] != L'&')
        {
            continue;
        }

        const wchar_t next = itemText[textIndex + 1u];
        if (next == L'&')
        {
            ++textIndex;
            continue;
        }

        return static_cast<wchar_t>(std::towupper(next));
    }

    return std::nullopt;
}

[[nodiscard]] std::optional<std::pair<size_t, size_t>> FindFirstTwoEnabledTopLevelMenuIndices(HMENU mainMenu) noexcept
{
    if (! mainMenu)
    {
        return std::nullopt;
    }

    std::optional<size_t> firstIndex;
    const int itemCount = GetMenuItemCount(mainMenu);
    for (int itemIndex = 0; itemIndex < itemCount; ++itemIndex)
    {
        MENUITEMINFOW itemInfo{};
        itemInfo.cbSize = sizeof(itemInfo);
        itemInfo.fMask  = MIIM_FTYPE | MIIM_STATE | MIIM_SUBMENU;
        if (! GetMenuItemInfoW(mainMenu, static_cast<UINT>(itemIndex), TRUE, &itemInfo))
        {
            continue;
        }

        if ((itemInfo.fType & MFT_SEPARATOR) != 0 || itemInfo.hSubMenu == nullptr)
        {
            continue;
        }

        if ((itemInfo.fState & MFS_GRAYED) != 0)
        {
            continue;
        }

        if (! firstIndex.has_value())
        {
            firstIndex = static_cast<size_t>(itemIndex);
            continue;
        }

        return std::pair<size_t, size_t>{firstIndex.value(), static_cast<size_t>(itemIndex)};
    }

    return std::nullopt;
}

[[nodiscard]] POINT ResolveMenuBarHoverSuppressionPoint(HWND mainWindow, POINT activeScreenPoint, size_t activeIndex, size_t intendedHoverIndex) noexcept
{
    POINT cursor{};
    size_t cursorHit = 0u;
    if (GetCursorPos(&cursor) != FALSE && DebugHitTestMainMenuBarScreenPoint(mainWindow, cursor, cursorHit) && cursorHit != activeIndex &&
        cursorHit != intendedHoverIndex)
    {
        return cursor;
    }

    return activeScreenPoint;
}

