[[nodiscard]] bool CreateFolderViewScrollRenderFixture(CaseState& state, const std::filesystem::path& root) noexcept
{
    state.Require(SelfTest::EnsureDirectory(root), L"Failed to create scroll/render stress root.");
    if (! state.failure.empty())
    {
        return false;
    }

    constexpr size_t kItemCount = 1600u;
    for (size_t i = 0; i < kItemCount; ++i)
    {
        const bool longName     = (i % 11u) == 0u;
        const std::wstring name = std::format(L"scroll_{:04}_{}{}.txt",
                                              i,
                                              longName ? RepeatForFolderViewColumnName(L'w', 56u) : RepeatForFolderViewColumnName(L's', 8u + (i % 9u)),
                                              (i % 5u == 0u) ? L"_metadata_line" : L"");
        state.Require(SelfTest::WriteTextFile(root / name, "scroll render stress"), std::format(L"Failed to create {}.", name));
    }

    return state.failure.empty();
}

[[nodiscard]] bool CreateFolderViewOverlayPerfFixture(CaseState& state, const std::filesystem::path& root) noexcept
{
    state.Require(SelfTest::EnsureDirectory(root), L"Failed to create overlay invalidation stress root.");
    if (! state.failure.empty())
    {
        return false;
    }

    constexpr size_t kItemCount = 180u;
    for (size_t i = 0; i < kItemCount; ++i)
    {
        const bool directMatch  = (i % 3u) == 0u;
        const std::wstring name = std::format(
            L"{}_{:03}_{}.txt", directMatch ? L"overlay_probe" : L"baseline_probe", i, RepeatForFolderViewColumnName(directMatch ? L'o' : L'b', 8u + (i % 5u)));
        state.Require(SelfTest::WriteTextFile(root / name, "folder overlay invalidation stress"), std::format(L"Failed to create {}.", name));
    }

    return state.failure.empty();
}

[[nodiscard]] bool TestFolderViewPerfOverlayInvalidationStress(HWND mainWindow, CaseState& state) noexcept
{
    using namespace std::chrono_literals;

    if (! mainWindow || ! IsWindow(mainWindow))
    {
        state.Require(false, L"Main window handle invalid for overlay invalidation stress.");
        return false;
    }

    const std::filesystem::path suiteRoot = SelfTest::GetTempRoot(SelfTest::SelfTestSuite::Commands);
    state.Require(! suiteRoot.empty(), L"SelfTest temp root unavailable for overlay invalidation stress.");
    if (suiteRoot.empty())
    {
        return false;
    }

    const std::filesystem::path root = suiteRoot / L"work" / (L"folder_overlay_invalidation_stress_" + NewGuidText());
    std::error_code ec;
    std::filesystem::remove_all(root, ec);
    state.Require(CreateFolderViewOverlayPerfFixture(state, root), L"Failed to create overlay invalidation stress fixture.");
    if (! state.failure.empty())
    {
        return false;
    }

    const std::wstring leftPluginBefore                   = std::wstring(g_folderWindow.GetFileSystemPluginId(FolderWindow::Pane::Left));
    const std::optional<std::filesystem::path> leftBefore = g_folderWindow.GetCurrentPath(FolderWindow::Pane::Left);
    const FolderView::DisplayMode displayBefore           = g_folderWindow.GetDisplayMode(FolderWindow::Pane::Left);
    const FolderView::SortBy sortBefore                   = g_folderWindow.GetSortBy(FolderWindow::Pane::Left);
    const FolderView::SortDirection directionBefore       = g_folderWindow.GetSortDirection(FolderWindow::Pane::Left);
    const auto restoreState                               = wil::scope_exit([&]
    {
        // The busy overlay consumes Escape while it blocks input. Dismiss it first so
        // Escape can end quick search and release the shared overlay-animation pump.
        g_folderWindow.DebugHideOverlaySample(FolderWindow::Pane::Left);
        const HWND currentFolderView = g_folderWindow.GetFolderViewHwnd(FolderWindow::Pane::Left);
        if (currentFolderView && IsWindow(currentFolderView) != FALSE)
        {
            SendMessageW(currentFolderView, WM_KEYDOWN, VK_ESCAPE, 0);
            SendMessageW(currentFolderView, WM_KEYUP, VK_ESCAPE, 0);
        }
        PumpPendingMessages();
        static_cast<void>(g_folderWindow.SetFileSystemPluginForPane(FolderWindow::Pane::Left, leftPluginBefore));
        g_folderWindow.SetDisplayMode(FolderWindow::Pane::Left, displayBefore);
        g_folderWindow.SetSort(FolderWindow::Pane::Left, sortBefore, directionBefore);
        if (leftBefore.has_value())
        {
            g_folderWindow.SetFolderPath(FolderWindow::Pane::Left, leftBefore.value());
        }
    });

    state.Require(SUCCEEDED(g_folderWindow.SetFileSystemPluginForPane(FolderWindow::Pane::Left, L"builtin/file-system")),
                  L"Failed to switch left pane to local file system for overlay invalidation stress.");
    g_folderWindow.SetDisplayMode(FolderWindow::Pane::Left, FolderView::DisplayMode::Brief);
    g_folderWindow.SetSort(FolderWindow::Pane::Left, FolderView::SortBy::Name, FolderView::SortDirection::Ascending);
    g_folderWindow.DebugResetPaneVisibilityState(FolderWindow::Pane::Left);

    std::atomic<uint32_t> enumerationCount{0};
    g_folderWindow.SetPaneEnumerationCompletedCallback(FolderWindow::Pane::Left,
                                                       [&](const std::filesystem::path& folder) noexcept
    {
        if (OrdinalString::EqualsNoCasePath(folder, root))
        {
            enumerationCount.fetch_add(1u, std::memory_order_release);
        }
    });
    const auto clearEnumCallback = wil::scope_exit([&] { g_folderWindow.SetPaneEnumerationCompletedCallback(FolderWindow::Pane::Left, {}); });

    g_folderWindow.SetFolderPath(FolderWindow::Pane::Left, root);
    state.Require(WaitForPanePath(FolderWindow::Pane::Left, root, SelfTest::Scale(10000ms)), L"Overlay invalidation stress path did not load.");

    const auto enumerationDeadline = std::chrono::steady_clock::now() + SelfTest::Scale(10000ms);
    while (std::chrono::steady_clock::now() < enumerationDeadline)
    {
        PumpPendingMessages();
        if (enumerationCount.load(std::memory_order_acquire) > 0u && g_folderWindow.DebugGetItemCount(FolderWindow::Pane::Left) == 180u)
        {
            break;
        }
        std::this_thread::sleep_for(20ms);
    }

    const size_t itemCount = g_folderWindow.DebugGetItemCount(FolderWindow::Pane::Left);
    state.Require(enumerationCount.load(std::memory_order_acquire) > 0u,
                  L"Overlay invalidation stress enumeration did not complete before quick-search input.");
    state.Require(itemCount == 180u, std::format(L"Overlay invalidation stress item count mismatch; expected=180 actual={}.", itemCount));
    if (! state.failure.empty())
    {
        return false;
    }

    const HWND folderView = g_folderWindow.GetFolderViewHwnd(FolderWindow::Pane::Left);
    state.Require(folderView && IsWindow(folderView) != FALSE, L"Left FolderView handle unavailable for overlay invalidation stress.");
    if (! folderView || IsWindow(folderView) == FALSE)
    {
        return false;
    }

    FocusFolderViewPane(FolderWindow::Pane::Left);
    const auto focusDiagnostics = [&]()
    {
        return std::format(L"focus=0x{:X}, focusedFolderView=0x{:X}, focusedPane={}, expectedLeftFolderView=0x{:X}",
                           reinterpret_cast<uintptr_t>(GetFocus()),
                           reinterpret_cast<uintptr_t>(g_folderWindow.GetFocusedFolderViewHwnd()),
                           g_folderWindow.GetFocusedPane() == FolderWindow::Pane::Left ? L"Left" : L"Right",
                           reinterpret_cast<uintptr_t>(folderView));
    };
    state.Require(WaitForFolderViewPaneFocus(FolderWindow::Pane::Left, folderView, SelfTest::Scale(1000ms)),
                  std::format(L"Left folder view did not have stable focus before overlay invalidation quick search; {}.", focusDiagnostics()));
    if (! state.failure.empty())
    {
        return false;
    }

    g_folderWindow.CommandQuickSearch(FolderWindow::Pane::Left);

    FolderView::IncrementalSearchDebugSnapshot searchSnapshot{};
    state.Require(WaitForFolderViewQuickSearchSnapshot(FolderWindow::Pane::Left,
                                                       [](const FolderView::IncrementalSearchDebugSnapshot& value) noexcept
    { return value.active && value.query.empty(); },
                                                       SelfTest::Scale(1000ms),
                                                       &searchSnapshot),
                  std::format(L"Overlay invalidation stress quick search did not activate cleanly; active={} query='{}'; {}.",
                              searchSnapshot.active ? L"yes" : L"no",
                              searchSnapshot.query,
                              focusDiagnostics()));
    if (! state.failure.empty())
    {
        return false;
    }

    InvalidateRect(folderView, nullptr, FALSE);
    UpdateWindow(folderView);
    state.Require(g_folderWindow.DebugWarmPaneRendering(FolderWindow::Pane::Left), L"Overlay invalidation stress initial warm render failed.");
    if (! state.failure.empty())
    {
        return false;
    }

    constexpr std::wstring_view kQuickSearch = L"overlay";
    for (const wchar_t ch : kQuickSearch)
    {
        state.Require(SendFolderViewQuickSearchCharForPerf(folderView, ch), L"Overlay perf quick-search synthetic modifier reset failed.");
        if (! state.failure.empty())
        {
            return false;
        }
    }

    state.Require(WaitForFolderViewQuickSearchSnapshot(FolderWindow::Pane::Left,
                                                       [](const FolderView::IncrementalSearchDebugSnapshot& value) noexcept
    { return value.active && value.query == L"overlay"; },
                                                       SelfTest::Scale(1500ms),
                                                       &searchSnapshot),
                  std::format(L"Overlay invalidation stress quick search did not capture the expected query; active={} query='{}'.",
                              searchSnapshot.active ? L"yes" : L"no",
                              searchSnapshot.query));
    state.Require(! searchSnapshot.matches.empty(), L"Overlay invalidation stress quick search produced no visible matches.");
    if (! state.failure.empty())
    {
        return false;
    }

    g_folderWindow.DebugShowOverlaySampleBusyWithCancel(FolderWindow::Pane::Left);
    state.Require(g_folderWindow.DebugWarmPaneRendering(FolderWindow::Pane::Left), L"Overlay invalidation stress overlay warm render failed.");
    if (! state.failure.empty())
    {
        return false;
    }

    const auto settleDeadline = std::chrono::steady_clock::now() + SelfTest::Scale(320ms);
    while (std::chrono::steady_clock::now() < settleDeadline)
    {
        PumpLimitedPendingMessagesForPerf(8u);
        static_cast<void>(g_folderWindow.DebugWarmPaneRendering(FolderWindow::Pane::Left));
        std::this_thread::sleep_for(SelfTest::Scale(8ms));
    }
    PumpLimitedPendingMessagesForPerf(32u);
    static_cast<void>(g_folderWindow.DebugWarmPaneRendering(FolderWindow::Pane::Left));

    const std::uintmax_t overlayMetricScanOffset           = FolderViewPerfMetricScanOffset();
    constexpr uint64_t kMinimumOverlayAnimationFrames      = 8u;
    constexpr uint64_t kOverlayFrameCollectionTargetPasses = kFolderViewPerfMinimumSamplesForP95;
    uint64_t overlayFrameCollectionPassCount               = 0u;
    for (; overlayFrameCollectionPassCount < kOverlayFrameCollectionTargetPasses; ++overlayFrameCollectionPassCount)
    {
        PumpLimitedPendingMessagesForPerf(8u);
        static_cast<void>(g_folderWindow.DebugWarmPaneRendering(FolderWindow::Pane::Left));
        PumpLimitedPendingMessagesForPerf(4u);
    }

    auto makeMetricPresence = [&](std::wstring_view metric) noexcept
    {
        const uint64_t count = FolderViewPerfMetricCountInRun(metric, overlayMetricScanOffset);
        return FolderViewFrameMetricPresenceRecord{.metric = metric, .count = count, .present = count > 0};
    };
    std::vector<FolderViewFrameMetricPresenceRecord> overlayMetricPresence = {
        makeMetricPresence(L"folder.frame.total_us"),
        makeMetricPresence(L"folder.frame.present_us"),
        makeMetricPresence(L"folder.frame.overlay_animation_count"),
        makeMetricPresence(L"folder.frame.overlay_dirty_rect_area_px"),
        makeMetricPresence(L"render.incremental_search_effect_updates"),
    };
    const uint64_t overlayTotalFrameCount     = overlayMetricPresence[0].count;
    const uint64_t overlayPresentFrameCount   = overlayMetricPresence[1].count;
    const uint64_t overlayAnimationFrameCount = overlayMetricPresence[2].count;
    const bool overlaySamplesEnoughForP95 =
        overlayTotalFrameCount >= kFolderViewPerfMinimumSamplesForP95 && overlayPresentFrameCount >= kFolderViewPerfMinimumSamplesForP95;
    state.Require(overlayAnimationFrameCount >= kMinimumOverlayAnimationFrames,
                  std::format(L"Overlay invalidation stress captured too few natural animation frames; expected>={} actual={}.",
                              kMinimumOverlayAnimationFrames,
                              overlayAnimationFrameCount));

    std::wstring json;
    json.append(L"{\n");
    json.append(L"  \"case\": \"folderView_perf_overlay_invalidation_stress\",\n");
    json.append(L"  \"root\": ");
    AppendFolderViewColumnJsonString(json, root.native());
    json.append(L",\n");
    json.append(L"  \"itemCount\": 180,\n");
    json.append(L"  \"query\": ");
    AppendFolderViewColumnJsonString(json, searchSnapshot.query);
    json.append(L",\n");
    json.append(std::format(L"  \"overlayFrameCollectionPassCount\": {},\n", overlayFrameCollectionPassCount));
    json.append(std::format(L"  \"overlaySamplesEnoughForP95Advisory\": {},\n", overlaySamplesEnoughForP95 ? L"true" : L"false"));
    json.append(L"  \"metricQuality\": {\n");
    AppendFolderViewMetricQualityJson(json, overlayTotalFrameCount, overlayPresentFrameCount, L"fixed-sample-target-advisory", L"    ");
    json.append(L"\n");
    json.append(L"  },\n");
    json.append(L"  \"folderOverlayMetricPresence\": {\n");
    AppendFolderViewOverlayMetricPresenceJson(json, overlayMetricPresence, L"    ");
    json.append(L"\n");
    json.append(L"  }\n");
    json.append(L"}\n");

    const std::filesystem::path artifactPath = SelfTest::GetPerfArtifactPath(L"folderView_perf_overlay_invalidation_stress_metrics.json");
    const bool artifactWriteOk               = ! artifactPath.empty() && SelfTest::WriteTextFile(artifactPath, json);
    state.Require(artifactWriteOk && SelfTest::PathExists(artifactPath), L"Failed to write overlay invalidation stress perf artifact.");

    if (! state.failure.empty())
    {
        return false;
    }
    return CheckFolderViewPerfBudgets(L"folderView_perf_overlay_invalidation_stress", overlayMetricScanOffset, state);
}

[[nodiscard]] bool TestFolderViewPerfScrollRenderStress(HWND mainWindow, CaseState& state) noexcept
{
    using namespace std::chrono_literals;

    if (! mainWindow || ! IsWindow(mainWindow))
    {
        state.Require(false, L"Main window handle invalid for scroll/render stress.");
        return false;
    }

    const std::filesystem::path suiteRoot = SelfTest::GetTempRoot(SelfTest::SelfTestSuite::Commands);
    state.Require(! suiteRoot.empty(), L"SelfTest temp root unavailable for scroll/render stress.");
    if (suiteRoot.empty())
    {
        return false;
    }

    const std::uintmax_t frameMetricScanOffset = FolderViewPerfMetricScanOffset();
    const std::wstring rootId                  = NewGuidText().substr(0, 8);
    const std::filesystem::path root           = suiteRoot / L"w" / (L"scroll_" + rootId);
    std::error_code ec;
    std::filesystem::remove_all(root, ec);
    state.Require(CreateFolderViewScrollRenderFixture(state, root), L"Failed to create scroll/render stress fixture.");
    if (! state.failure.empty())
    {
        return false;
    }

    const std::wstring leftPluginBefore                   = std::wstring(g_folderWindow.GetFileSystemPluginId(FolderWindow::Pane::Left));
    const std::optional<std::filesystem::path> leftBefore = g_folderWindow.GetCurrentPath(FolderWindow::Pane::Left);
    const FolderView::DisplayMode displayBefore           = g_folderWindow.GetDisplayMode(FolderWindow::Pane::Left);
    const FolderView::SortBy sortBefore                   = g_folderWindow.GetSortBy(FolderWindow::Pane::Left);
    const FolderView::SortDirection directionBefore       = g_folderWindow.GetSortDirection(FolderWindow::Pane::Left);
    const auto restoreState                               = wil::scope_exit([&]
    {
        static_cast<void>(g_folderWindow.SetFileSystemPluginForPane(FolderWindow::Pane::Left, leftPluginBefore));
        g_folderWindow.SetDisplayMode(FolderWindow::Pane::Left, displayBefore);
        g_folderWindow.SetSort(FolderWindow::Pane::Left, sortBefore, directionBefore);
        if (leftBefore.has_value())
        {
            g_folderWindow.SetFolderPath(FolderWindow::Pane::Left, leftBefore.value());
        }
    });

    state.Require(SUCCEEDED(g_folderWindow.SetFileSystemPluginForPane(FolderWindow::Pane::Left, L"builtin/file-system")),
                  L"Failed to switch left pane to local file system for scroll/render stress.");
    g_folderWindow.SetSort(FolderWindow::Pane::Left, FolderView::SortBy::Name, FolderView::SortDirection::Ascending);
    g_folderWindow.DebugResetPaneVisibilityState(FolderWindow::Pane::Left);

    std::atomic<uint32_t> enumerationCount{0};
    g_folderWindow.SetPaneEnumerationCompletedCallback(FolderWindow::Pane::Left,
                                                       [&](const std::filesystem::path& folder) noexcept
    {
        if (OrdinalString::EqualsNoCasePath(folder, root))
        {
            enumerationCount.fetch_add(1u, std::memory_order_release);
        }
    });
    const auto clearEnumCallback = wil::scope_exit([&] { g_folderWindow.SetPaneEnumerationCompletedCallback(FolderWindow::Pane::Left, {}); });

    const HWND folderView = g_folderWindow.GetFolderViewHwnd(FolderWindow::Pane::Left);
    state.Require(folderView && IsWindow(folderView) != FALSE, L"Left FolderView handle unavailable for scroll/render stress.");
    if (! folderView || IsWindow(folderView) == FALSE)
    {
        return false;
    }

    constexpr std::array<FolderView::DisplayMode, 3> kModes = {{
        FolderView::DisplayMode::Brief,
        FolderView::DisplayMode::Detailed,
        FolderView::DisplayMode::ExtraDetailed,
    }};

    std::vector<FolderViewScrollStepPerfRecord> records;
    constexpr size_t kScrollStepsPerMode = 10u;
    constexpr size_t kMaxGesturePasses   = 4u;
    records.reserve(kModes.size() * kScrollStepsPerMode * kMaxGesturePasses);
    const auto wheelWParam = [](int delta, UINT keyState = 0u) noexcept -> WPARAM { return MAKEWPARAM(static_cast<WORD>(keyState), static_cast<WORD>(delta)); };

    size_t gesturePassCount = 0u;
    for (size_t passIndex = 0u; passIndex < kMaxGesturePasses; ++passIndex)
    {
        gesturePassCount = passIndex + 1u;
        for (const FolderView::DisplayMode mode : kModes)
        {
            const std::wstring modeName = FolderViewColumnDisplayModeName(mode);
            g_folderWindow.SetDisplayMode(FolderWindow::Pane::Left, mode);
            g_folderWindow.SetFolderPath(FolderWindow::Pane::Left, root);
            state.Require(WaitForPanePath(FolderWindow::Pane::Left, root, SelfTest::Scale(10000ms)),
                          std::format(L"Scroll/render stress path did not load for {} pass {}.", modeName, gesturePassCount));
            state.Require(WaitForFolderViewItemCount(FolderWindow::Pane::Left, 1600u, SelfTest::Scale(10000ms)),
                          std::format(L"Scroll/render stress item count mismatch for {} pass {}; expected=1600 actual={}.",
                                      modeName,
                                      gesturePassCount,
                                      g_folderWindow.DebugGetItemCount(FolderWindow::Pane::Left)));
            state.Require(g_folderWindow.DebugWarmPaneRendering(FolderWindow::Pane::Left),
                          std::format(L"Initial scroll/render warm render failed for {} pass {}.", modeName, gesturePassCount));
            if (! state.failure.empty())
            {
                return false;
            }

            state.Require(WaitForFolderViewWarmPerfQuiescence(FolderWindow::Pane::Left, SelfTest::Scale(100ms), SelfTest::Scale(5000ms)),
                          std::format(L"Scroll/render fixture did not become quiet before {} pass {}.", modeName, gesturePassCount));
            if (! state.failure.empty())
                return false;

            const auto driveStep = [&](UINT message, WPARAM request, std::wstring_view stepName) noexcept -> bool
            {
                const std::wstring stepDetail = std::format(L"pass{}:{}", gesturePassCount, stepName);
                ValidateRect(folderView, nullptr);
                const auto perfBefore                                 = g_folderWindow.DebugGetWarmPanePerfSnapshot(FolderWindow::Pane::Left);
                const FolderView::RenderingDebugSnapshot renderBefore = g_folderWindow.DebugGetPaneRenderingSnapshot(FolderWindow::Pane::Left);
                FolderView::DebugColumnLayoutSnapshot beforeSnapshot{};
                const bool beforeSnapshotOk = g_folderWindow.DebugGetPaneColumnLayoutSnapshot(FolderWindow::Pane::Left, beforeSnapshot);
                state.Require(beforeSnapshotOk, std::format(L"Scroll/render pre-snapshot failed for {} / {}.", modeName, stepDetail));
                if (! beforeSnapshotOk || ! state.failure.empty())
                {
                    return false;
                }

                const auto start = std::chrono::steady_clock::now();
                SendMessageW(folderView, message, request, 0);
                UpdateWindow(folderView);
                PumpPendingMessages();
                const auto perfAfterProductPaint                                 = g_folderWindow.DebugGetWarmPanePerfSnapshot(FolderWindow::Pane::Left);
                const FolderView::RenderingDebugSnapshot renderAfterProductPaint = g_folderWindow.DebugGetPaneRenderingSnapshot(FolderWindow::Pane::Left);
                const bool warmOk                                                = g_folderWindow.DebugWarmPaneRendering(FolderWindow::Pane::Left);
                PumpPendingMessages();
                const auto elapsedUs =
                    static_cast<uint64_t>(std::chrono::duration_cast<std::chrono::microseconds>(std::chrono::steady_clock::now() - start).count());
                const auto perfAfter = g_folderWindow.DebugGetWarmPanePerfSnapshot(FolderWindow::Pane::Left);

                FolderView::DebugColumnLayoutSnapshot snapshot{};
                const bool snapshotOk = g_folderWindow.DebugGetPaneColumnLayoutSnapshot(FolderWindow::Pane::Left, snapshot);
                state.Require(warmOk, std::format(L"Scroll/render warm render failed for {} / {}.", modeName, stepDetail));
                state.Require(snapshotOk, std::format(L"Scroll/render snapshot failed for {} / {}.", modeName, stepDetail));
                if (! warmOk || ! snapshotOk || ! state.failure.empty())
                {
                    return false;
                }

                const uint64_t frameCount                  = perfAfter.renderCalls - perfBefore.renderCalls;
                const uint64_t productPaintRenderCount     = perfAfterProductPaint.renderCalls - perfBefore.renderCalls;
                const uint64_t productPaintFullClientCount = renderAfterProductPaint.fullClientRenderCount - renderBefore.fullClientRenderCount;
                const RECT productPaintDirtyRect           = renderAfterProductPaint.lastRenderInvalidRectPx;
                const uint64_t productPaintDirtyAreaPx =
                    productPaintRenderCount == 0u ? 0u
                                                  : static_cast<uint64_t>(std::max<LONG>(0, productPaintDirtyRect.right - productPaintDirtyRect.left)) *
                                                        static_cast<uint64_t>(std::max<LONG>(0, productPaintDirtyRect.bottom - productPaintDirtyRect.top));
                const bool viewportChanged = std::abs(snapshot.horizontalOffsetDip - beforeSnapshot.horizontalOffsetDip) > 0.01f ||
                                             snapshot.firstVisibleIndex != beforeSnapshot.firstVisibleIndex ||
                                             snapshot.lastVisibleIndex != beforeSnapshot.lastVisibleIndex;
                if (! viewportChanged)
                {
                    state.Require(productPaintRenderCount == 0u,
                                  std::format(L"No-op scroll repainted {} frame(s) for {} / {}; fullClientDelta={} dirtyAreaPx={}.",
                                              productPaintRenderCount,
                                              modeName,
                                              stepDetail,
                                              productPaintFullClientCount,
                                              productPaintDirtyAreaPx));
                }
                if (! state.failure.empty())
                {
                    return false;
                }

                Debug::Perf::Emit(L"folder.scroll_input_to_paint_us",
                                  std::format(L"{}:{}", modeName, stepDetail),
                                  elapsedUs,
                                  static_cast<uint64_t>(snapshot.visibleItems.size()),
                                  frameCount,
                                  S_OK);
                Debug::Perf::Emit(L"folder.scroll_frame_count",
                                  std::format(L"{}:{}", modeName, stepDetail),
                                  0,
                                  frameCount,
                                  static_cast<uint64_t>(snapshot.visibleItems.size()),
                                  S_OK);
                Debug::Perf::Emit(L"folder.scroll_visible_item_count",
                                  std::format(L"{}:{}", modeName, stepDetail),
                                  0,
                                  static_cast<uint64_t>(snapshot.visibleItems.size()),
                                  static_cast<uint64_t>(g_folderWindow.DebugGetItemCount(FolderWindow::Pane::Left)),
                                  S_OK);
                Debug::Perf::Emit(L"folder.scroll.product_paint_render_count",
                                  std::format(L"{}:{}", modeName, stepDetail),
                                  0,
                                  productPaintRenderCount,
                                  viewportChanged ? 1u : 0u,
                                  S_OK);
                Debug::Perf::Emit(L"folder.scroll.product_paint_full_client_count",
                                  std::format(L"{}:{}", modeName, stepDetail),
                                  0,
                                  productPaintFullClientCount,
                                  productPaintRenderCount,
                                  S_OK);
                Debug::Perf::Emit(L"folder.scroll.product_paint_dirty_rect_area_px",
                                  std::format(L"{}:{}", modeName, stepDetail),
                                  0,
                                  productPaintDirtyAreaPx,
                                  productPaintRenderCount,
                                  S_OK);

                records.push_back(FolderViewScrollStepPerfRecord{
                    .mode                        = modeName,
                    .step                        = stepDetail,
                    .inputToPaintUs              = elapsedUs,
                    .frameCount                  = frameCount,
                    .productPaintRenderCount     = productPaintRenderCount,
                    .productPaintFullClientCount = productPaintFullClientCount,
                    .productPaintDirtyAreaPx     = productPaintDirtyAreaPx,
                    .viewportChanged             = viewportChanged,
                    .visibleItemCount            = snapshot.visibleItems.size(),
                    .firstVisibleIndex           = snapshot.firstVisibleIndex,
                    .lastVisibleIndex            = snapshot.lastVisibleIndex,
                    .horizontalOffsetDip         = snapshot.horizontalOffsetDip,
                    .maxHorizontalOffsetDip      = snapshot.maxHorizontalOffsetDip,
                });
                return true;
            };

            state.Require(driveStep(WM_HSCROLL, SB_LEFT, L"h-left"),
                          std::format(L"Scroll/render failed at h-left for {} pass {}.", modeName, gesturePassCount));
            state.Require(driveStep(WM_HSCROLL, SB_LEFT, L"h-left-noop"),
                          std::format(L"Scroll/render failed at h-left-noop for {} pass {}.", modeName, gesturePassCount));
            state.Require(driveStep(WM_HSCROLL, SB_LINERIGHT, L"h-line-right"),
                          std::format(L"Scroll/render failed at h-line-right for {} pass {}.", modeName, gesturePassCount));
            state.Require(driveStep(WM_HSCROLL, SB_PAGERIGHT, L"h-page-right"),
                          std::format(L"Scroll/render failed at h-page-right for {} pass {}.", modeName, gesturePassCount));
            state.Require(driveStep(WM_HSCROLL, SB_RIGHT, L"h-right"),
                          std::format(L"Scroll/render failed at h-right for {} pass {}.", modeName, gesturePassCount));
            state.Require(driveStep(WM_HSCROLL, SB_RIGHT, L"h-right-noop"),
                          std::format(L"Scroll/render failed at h-right-noop for {} pass {}.", modeName, gesturePassCount));
            state.Require(driveStep(WM_HSCROLL, SB_PAGELEFT, L"h-page-left"),
                          std::format(L"Scroll/render failed at h-page-left for {} pass {}.", modeName, gesturePassCount));
            state.Require(driveStep(WM_MOUSEWHEEL, wheelWParam(-WHEEL_DELTA), L"wheel-next"),
                          std::format(L"Scroll/render failed at wheel-next for {} pass {}.", modeName, gesturePassCount));
            state.Require(driveStep(WM_MOUSEHWHEEL, wheelWParam(WHEEL_DELTA), L"hwheel-next"),
                          std::format(L"Scroll/render failed at hwheel-next for {} pass {}.", modeName, gesturePassCount));
            state.Require(driveStep(WM_KEYDOWN, VK_NEXT, L"key-page-next"),
                          std::format(L"Scroll/render failed at key-page-next for {} pass {}.", modeName, gesturePassCount));
            if (! state.failure.empty())
            {
                return false;
            }
        }

        const uint64_t currentTotalFrameCount   = FolderViewPerfMetricCountInRun(L"folder.frame.total_us", frameMetricScanOffset);
        const uint64_t currentPresentFrameCount = FolderViewPerfMetricCountInRun(L"folder.frame.present_us", frameMetricScanOffset);
        if (currentTotalFrameCount >= kFolderViewPerfMinimumSamplesForP95 && currentPresentFrameCount >= kFolderViewPerfMinimumSamplesForP95)
        {
            break;
        }
    }

    state.Require(! records.empty(), L"Scroll/render stress did not record scroll steps.");
    if (! state.failure.empty())
    {
        return false;
    }

    auto makeMetricPresence = [&](std::wstring_view metric) noexcept
    {
        const uint64_t count = FolderViewPerfMetricCountInRun(metric, frameMetricScanOffset);
        return FolderViewFrameMetricPresenceRecord{.metric = metric, .count = count, .present = count > 0};
    };
    std::vector<FolderViewFrameMetricPresenceRecord> frameMetricPresence = {
        makeMetricPresence(L"folder.frame.total_us"),
        makeMetricPresence(L"folder.frame.present_us"),
        makeMetricPresence(L"folder.frame.visible_work_count"),
        makeMetricPresence(L"folder.frame.input_to_paint_us"),
        makeMetricPresence(L"folder.frame.dirty_rect_area_px"),
        makeMetricPresence(L"dwrite.text_layout.create_count"),
        makeMetricPresence(L"dwrite.text_layout.create_us"),
        makeMetricPresence(L"dwrite.text_layout.frame_create_count"),
        makeMetricPresence(L"dwrite.text_layout.frame_create_us"),
        makeMetricPresence(L"folder.layout.setup_us"),
        makeMetricPresence(L"folder.layout.estimate_metrics_us"),
        makeMetricPresence(L"folder.layout.column_resolve_us"),
        makeMetricPresence(L"folder.layout.bounds_us"),
        makeMetricPresence(L"folder.layout.update_text_layouts_us"),
    };
    const uint64_t totalFrameCount   = frameMetricPresence[0].count;
    const uint64_t presentFrameCount = frameMetricPresence[1].count;
    const bool samplesEnoughForP95   = totalFrameCount >= kFolderViewPerfMinimumSamplesForP95 && presentFrameCount >= kFolderViewPerfMinimumSamplesForP95;
    state.Require(samplesEnoughForP95,
                  std::format(L"Scroll/render stress captured too few frame samples for p95 after {} gesture passes; total={} present={} required={}.",
                              gesturePassCount,
                              totalFrameCount,
                              presentFrameCount,
                              kFolderViewPerfMinimumSamplesForP95));

    std::wstring json;
    json.append(L"{\n");
    json.append(L"  \"case\": \"folderView_perf_scroll_render_stress\",\n");
    json.append(L"  \"root\": ");
    AppendFolderViewColumnJsonString(json, root.native());
    json.append(L",\n");
    json.append(L"  \"itemCount\": 1600,\n");
    json.append(std::format(L"  \"gesturePassCount\": {},\n", gesturePassCount));
    json.append(std::format(L"  \"enumerationCount\": {},\n", enumerationCount.load(std::memory_order_acquire)));
    json.append(L"  \"scrollSteps\": [\n");
    for (size_t i = 0; i < records.size(); ++i)
    {
        AppendFolderViewScrollStepJson(json, records[i], L"    ");
        json.append(i + 1u < records.size() ? L",\n" : L"\n");
    }
    json.append(L"  ],\n");
    json.append(L"  \"metricQuality\": {\n");
    AppendFolderViewMetricQualityJson(json, totalFrameCount, presentFrameCount, L"gesture-bounded", L"    ");
    json.append(L"\n");
    json.append(L"  },\n");
    json.append(L"  \"folderFrameMetricPresence\": {\n");
    AppendFolderViewFrameMetricPresenceJson(json, frameMetricPresence, L"    ");
    json.append(L"\n");
    json.append(L"  }\n");
    json.append(L"}\n");

    const std::filesystem::path artifactPath = SelfTest::GetPerfArtifactPath(L"folderView_perf_scroll_render_stress_metrics.json");
    const bool artifactWriteOk               = ! artifactPath.empty() && SelfTest::WriteTextFile(artifactPath, json);
    state.Require(artifactWriteOk && SelfTest::PathExists(artifactPath), L"Failed to write scroll/render stress perf artifact.");

    if (! state.failure.empty())
    {
        return false;
    }
    return CheckFolderViewPerfBudgets(L"folderView_perf_scroll_render_stress", frameMetricScanOffset, state);
}

[[nodiscard]] bool TestFolderViewPerfHugeFolderScale(HWND mainWindow, CaseState& state) noexcept
{
    using namespace std::chrono_literals;

    if (! mainWindow || ! IsWindow(mainWindow))
    {
        state.Require(false, L"Main window handle invalid for huge FolderView scale perf.");
        return false;
    }

    if (! PrepareMainWindowForIsolatedUiCase(mainWindow, state, L"huge FolderView scale Quick Search perf"))
    {
        return false;
    }

    FolderViewDummyPluginHandles dummy{};
    state.Require(LoadFolderViewDummyPlugin(state, dummy), L"Failed to load dummy file system for huge FolderView scale perf.");
    if (! state.failure.empty())
    {
        return false;
    }

    std::string previousDummyConfig;
    state.Require(BackupPluginConfigurationForFolderViewPerf(dummy.informations.get(), previousDummyConfig),
                  L"Failed to snapshot dummy configuration for huge FolderView scale perf.");
    if (! state.failure.empty())
    {
        return false;
    }
    const auto restoreDummyConfig =
        wil::scope_exit([&]() noexcept { static_cast<void>(SetPluginConfigurationForFolderViewPerf(dummy.informations.get(), previousDummyConfig)); });

    constexpr std::string_view kDeterministicEmptyDummyConfig =
        R"json({"maxChildrenPerDirectory":0,"maxDepth":10,"seed":42,"latencyMs":0,"streamChunkLatencyMs":0,"virtualSpeedLimit":"0"})json";
    state.Require(SetPluginConfigurationForFolderViewPerf(dummy.informations.get(), kDeterministicEmptyDummyConfig),
                  L"Failed to apply deterministic empty dummy configuration for huge FolderView scale perf.");

    const bool optIn50k                   = IsFolderViewHugePerfOptInEnabled();
    const size_t itemCount                = optIn50k ? 50000u : 10000u;
    constexpr size_t kExtensionCount      = 160u;
    const std::filesystem::path dummyRoot = std::filesystem::path(L"/folderview-huge-scale") / SanitizeFolderViewDummyPathSegment(NewGuidText());
    std::wstring firstName;
    std::wstring middleName;
    std::wstring lastName;
    const auto fixtureStart = std::chrono::steady_clock::now();
    state.Require(MaterializeFolderViewDummyFiles(state, dummy, dummyRoot, itemCount, kExtensionCount, &firstName, &middleName, &lastName),
                  L"Failed to materialize huge FolderView dummy fixture.");
    const uint64_t fixtureMaterializeUs = Debug::Perf::ElapsedUs(fixtureStart);
    if (! state.failure.empty())
    {
        return false;
    }

    const std::wstring leftPluginBefore                   = std::wstring(g_folderWindow.GetFileSystemPluginId(FolderWindow::Pane::Left));
    const std::optional<std::filesystem::path> leftBefore = g_folderWindow.GetCurrentPath(FolderWindow::Pane::Left);
    const FolderView::DisplayMode displayBefore           = g_folderWindow.GetDisplayMode(FolderWindow::Pane::Left);
    const FolderView::SortBy sortBefore                   = g_folderWindow.GetSortBy(FolderWindow::Pane::Left);
    const FolderView::SortDirection directionBefore       = g_folderWindow.GetSortDirection(FolderWindow::Pane::Left);
    const FolderView::NameFilterState filterBefore        = g_folderWindow.DebugGetNameFilterState(FolderWindow::Pane::Left);
    const auto restorePaneState                           = wil::scope_exit([&]() noexcept
    {
        const HWND folderView = g_folderWindow.GetFolderViewHwnd(FolderWindow::Pane::Left);
        if (folderView && IsWindow(folderView) != FALSE)
        {
            SendMessageW(folderView, WM_KEYDOWN, VK_ESCAPE, 0);
            SendMessageW(folderView, WM_KEYUP, VK_ESCAPE, 0);
        }
        g_folderWindow.SetNameFilterState(FolderWindow::Pane::Left, filterBefore, false);
        static_cast<void>(g_folderWindow.SetFileSystemPluginForPane(FolderWindow::Pane::Left, leftPluginBefore));
        g_folderWindow.SetDisplayMode(FolderWindow::Pane::Left, displayBefore);
        g_folderWindow.SetSort(FolderWindow::Pane::Left, sortBefore, directionBefore);
        if (leftBefore.has_value())
        {
            g_folderWindow.SetFolderPath(FolderWindow::Pane::Left, leftBefore.value());
        }
    });

    // Perf cases share the modeless FolderView. Clear any active quick search left by
    // an earlier case before enabling the quiescence assertions below.
    g_folderWindow.DebugHideOverlaySample(FolderWindow::Pane::Left);
    ClearPaneIncrementalSearchForSelfTest(FolderWindow::Pane::Left);
    FolderView::IncrementalSearchDebugSnapshot initialSearchSnapshot{};
    state.Require(WaitForFolderViewQuickSearchSnapshot(FolderWindow::Pane::Left,
                                                       [](const FolderView::IncrementalSearchDebugSnapshot& value) noexcept { return ! value.active; },
                                                       SelfTest::Scale(1000ms),
                                                       &initialSearchSnapshot),
                  std::format(L"Huge FolderView scale inherited active quick search; query='{}'.", initialSearchSnapshot.query));
    if (! state.failure.empty())
    {
        return false;
    }

    state.Require(SUCCEEDED(g_folderWindow.SetFileSystemPluginForPane(FolderWindow::Pane::Left, kBuiltinDummyFileSystemIdForFolderViewPerf.data())),
                  L"Failed to switch left pane to dummy file system for huge FolderView scale perf.");
    g_folderWindow.SetDisplayMode(FolderWindow::Pane::Left, FolderView::DisplayMode::Detailed);
    g_folderWindow.SetSort(FolderWindow::Pane::Left, FolderView::SortBy::Name, FolderView::SortDirection::Ascending);
    g_folderWindow.DebugResetPaneVisibilityState(FolderWindow::Pane::Left);

    const std::uintmax_t frameMetricScanOffset                  = FolderViewPerfMetricScanOffset();
    const SelfTestProcessMemorySnapshot beforeEnumerationMemory = SampleSelfTestProcessMemory();
    EmitFolderViewMemoryMetrics(L"before-enumeration", beforeEnumerationMemory, static_cast<uint64_t>(itemCount));

    std::atomic<uint32_t> enumerationCount{0};
    g_folderWindow.SetPaneEnumerationCompletedCallback(FolderWindow::Pane::Left,
                                                       [&](const std::filesystem::path& folder) noexcept
    {
        if (OrdinalString::EqualsNoCase(folder.generic_wstring(), dummyRoot.generic_wstring()))
        {
            enumerationCount.fetch_add(1u, std::memory_order_release);
        }
    });
    const auto clearEnumCallback = wil::scope_exit([&] { g_folderWindow.SetPaneEnumerationCompletedCallback(FolderWindow::Pane::Left, {}); });

    const auto navigationStart = std::chrono::steady_clock::now();
    g_folderWindow.SetFolderPath(FolderWindow::Pane::Left, dummyRoot);
    state.Require(WaitForPanePluginPathForFolderViewPerf(FolderWindow::Pane::Left, dummyRoot, SelfTest::Scale(20000ms)),
                  L"Huge FolderView scale plugin path did not load.");
    state.Require(WaitForAtomicAtLeast(enumerationCount, 1u, SelfTest::Scale(20000ms)), L"Huge FolderView scale enumeration did not complete.");
    const uint64_t enumerationUs = Debug::Perf::ElapsedUs(navigationStart);
    Debug::Perf::Emit(L"folder.scale.enumeration_us", L"dummy-10k-exact", enumerationUs, static_cast<uint64_t>(itemCount), kExtensionCount, S_OK);
    state.Require(WaitForFolderViewItemCount(FolderWindow::Pane::Left, itemCount, SelfTest::Scale(20000ms)),
                  std::format(L"Huge FolderView scale item count mismatch; expected={} actual={}.",
                              itemCount,
                              g_folderWindow.DebugGetItemCount(FolderWindow::Pane::Left)));
    state.Require(g_folderWindow.DebugHasItemDisplayName(FolderWindow::Pane::Left, firstName) &&
                      g_folderWindow.DebugHasItemDisplayName(FolderWindow::Pane::Left, middleName) &&
                      g_folderWindow.DebugHasItemDisplayName(FolderWindow::Pane::Left, lastName),
                  L"Huge FolderView scale probe items did not load.");
    if (! state.failure.empty())
    {
        return false;
    }

    const HWND folderView = g_folderWindow.GetFolderViewHwnd(FolderWindow::Pane::Left);
    state.Require(folderView && IsWindow(folderView) != FALSE, L"Left FolderView handle unavailable for huge FolderView scale perf.");
    if (! folderView || IsWindow(folderView) == FALSE)
    {
        return false;
    }

    state.Require(g_folderWindow.DebugWarmPaneRendering(FolderWindow::Pane::Left), L"Huge FolderView scale first visible paint failed.");
    const uint64_t firstVisiblePaintUs = Debug::Perf::ElapsedUs(navigationStart);
    Debug::Perf::Emit(L"folder.scale.first_visible_paint_us", L"dummy-10k-exact", firstVisiblePaintUs, static_cast<uint64_t>(itemCount), 0u, S_OK);
    const SelfTestProcessMemorySnapshot afterFirstPaintMemory = SampleSelfTestProcessMemory();
    EmitFolderViewMemoryMetrics(L"after-first-paint", afterFirstPaintMemory, static_cast<uint64_t>(itemCount));

    FolderView::DebugColumnLayoutSnapshot firstPaintSnapshot{};
    state.Require(g_folderWindow.DebugGetPaneColumnLayoutSnapshot(FolderWindow::Pane::Left, firstPaintSnapshot),
                  L"Huge FolderView scale failed to capture first-paint layout snapshot.");
    if (! state.failure.empty())
    {
        return false;
    }

    const auto sortPerfBefore = g_folderWindow.DebugGetWarmPanePerfSnapshot(FolderWindow::Pane::Left);
    const auto sortStart      = std::chrono::steady_clock::now();
    g_folderWindow.SetSort(FolderWindow::Pane::Left, FolderView::SortBy::Extension, FolderView::SortDirection::Ascending);
    PumpPendingMessages();
    InvalidateRect(folderView, nullptr, FALSE);
    UpdateWindow(folderView);
    state.Require(g_folderWindow.DebugWarmPaneRendering(FolderWindow::Pane::Left), L"Huge FolderView scale extension sort render failed.");
    const uint64_t sortToggleUs = Debug::Perf::ElapsedUs(sortStart);
    const auto sortPerfAfter    = g_folderWindow.DebugGetWarmPanePerfSnapshot(FolderWindow::Pane::Left);
    Debug::Perf::Emit(L"folder.sort_toggle_us",
                      L"huge-folder-scale:extension",
                      sortToggleUs,
                      static_cast<uint64_t>(itemCount),
                      sortPerfAfter.renderCalls - sortPerfBefore.renderCalls,
                      S_OK);
    if (! state.failure.empty())
    {
        return false;
    }

    state.Require(WaitForFolderViewWarmPerfQuiescence(FolderWindow::Pane::Left, SelfTest::Scale(160ms), SelfTest::Scale(5000ms)),
                  L"Huge FolderView scale did not settle after extension sort before quick-search timing.");
    if (! state.failure.empty())
    {
        return false;
    }

    FocusFolderViewPane(FolderWindow::Pane::Left);
    state.Require(WaitForFolderViewPaneFocus(FolderWindow::Pane::Left, folderView, SelfTest::Scale(1000ms)),
                  L"Huge FolderView scale FolderView did not receive focus before quick-search timing.");
    if (! state.failure.empty())
    {
        return false;
    }

    state.Require(ClearSyntheticTextInputModifiersForFolderViewPerf(), L"Huge FolderView scale could not clear synthetic text-input modifiers.");
    if (! state.failure.empty())
    {
        return false;
    }
    g_folderWindow.CommandQuickSearch(FolderWindow::Pane::Left);
    FolderView::IncrementalSearchDebugSnapshot searchSnapshot{};
    state.Require(WaitForFolderViewQuickSearchSnapshot(FolderWindow::Pane::Left,
                                                       [](const FolderView::IncrementalSearchDebugSnapshot& value) noexcept
    { return value.active && value.query.empty(); },
                                                       SelfTest::Scale(1000ms),
                                                       &searchSnapshot),
                  std::format(L"Huge FolderView scale quick-search activation did not settle; active={} query='{}', folderView=0x{:X}, "
                              L"focusedFolderView=0x{:X}, win32Focus=0x{:X}, foreground=0x{:X}.",
                              searchSnapshot.active ? L"yes" : L"no",
                              searchSnapshot.query,
                              reinterpret_cast<uintptr_t>(folderView),
                              reinterpret_cast<uintptr_t>(g_folderWindow.GetFocusedFolderViewHwnd()),
                              reinterpret_cast<uintptr_t>(GetFocus()),
                              reinterpret_cast<uintptr_t>(GetForegroundWindow())));
    state.Require(g_folderWindow.DebugWarmPaneRendering(FolderWindow::Pane::Left), L"Huge FolderView scale quick-search activation warm render failed.");
    if (! state.failure.empty())
    {
        return false;
    }

    std::vector<uint64_t> filterKeystrokeUs;
    constexpr std::wstring_view kScaleQuickSearch = L"scaleprobe";
    std::wstring currentQuery;
    for (const wchar_t ch : kScaleQuickSearch)
    {
        currentQuery.push_back(ch);
        const auto keyStart = std::chrono::steady_clock::now();
        state.Require(SendFolderViewQuickSearchCharForPerf(folderView, ch),
                      std::format(L"Huge FolderView scale could not clear synthetic modifiers before '{}'.", currentQuery));
        if (! state.failure.empty())
        {
            return false;
        }
        InvalidateRect(folderView, nullptr, FALSE);
        UpdateWindow(folderView);
        state.Require(g_folderWindow.DebugWarmPaneRendering(FolderWindow::Pane::Left),
                      std::format(L"Huge FolderView scale quick-search paint failed after '{}'.", currentQuery));
        const uint64_t keyToPaintUs = Debug::Perf::ElapsedUs(keyStart);
        state.Require(WaitForFolderViewQuickSearchSnapshot(FolderWindow::Pane::Left,
                                                           [&](const FolderView::IncrementalSearchDebugSnapshot& value) noexcept
        { return value.active && value.query == currentQuery && ! value.matches.empty(); },
                                                           SelfTest::Scale(1500ms),
                                                           &searchSnapshot),
                      std::format(L"Huge FolderView scale quick-search mismatch; expected='{}' active={} actual='{}' matches={}.",
                                  currentQuery,
                                  searchSnapshot.active ? L"yes" : L"no",
                                  searchSnapshot.query,
                                  searchSnapshot.matches.size()));
        Debug::Perf::Emit(L"folder.filter.keystroke_to_paint_us",
                          currentQuery,
                          keyToPaintUs,
                          static_cast<uint64_t>(searchSnapshot.matches.size()),
                          static_cast<uint64_t>(itemCount),
                          S_OK);
        filterKeystrokeUs.push_back(keyToPaintUs);
        if (! state.failure.empty())
        {
            return false;
        }
    }
    SendMessageW(folderView, WM_KEYDOWN, VK_ESCAPE, 0);
    SendMessageW(folderView, WM_KEYUP, VK_ESCAPE, 0);
    PumpPendingMessages();

    g_folderWindow.SetPaneSelectionByDisplayNamePredicate(FolderWindow::Pane::Left, [](std::wstring_view) noexcept { return true; }, true);
    state.Require(g_folderWindow.DebugGetSelectedCount(FolderWindow::Pane::Left) == itemCount,
                  std::format(L"Huge FolderView scale Select All selected {} items instead of {}.",
                              g_folderWindow.DebugGetSelectedCount(FolderWindow::Pane::Left),
                              itemCount));
    g_folderWindow.DebugResetPaneDrawItemTransientBrushCreateCount(FolderWindow::Pane::Left);
    constexpr std::array<WPARAM, 8> kScrollRequests = {{
        SB_TOP,
        SB_BOTTOM,
        SB_TOP,
        SB_PAGEDOWN,
        SB_PAGEDOWN,
        SB_BOTTOM,
        SB_LINEUP,
        SB_LINEDOWN,
    }};
    for (const WPARAM request : kScrollRequests)
    {
        SendMessageW(folderView, WM_VSCROLL, request, 0);
        PumpPendingMessages();
        InvalidateRect(folderView, nullptr, FALSE);
        UpdateWindow(folderView);
        state.Require(g_folderWindow.DebugWarmPaneRendering(FolderWindow::Pane::Left), L"Huge FolderView scale selected-scroll warm render failed.");
        if (! state.failure.empty())
        {
            return false;
        }
    }

    const SelfTestProcessMemorySnapshot afterScrollMemory = SampleSelfTestProcessMemory();
    EmitFolderViewMemoryMetrics(L"after-selectall-scroll", afterScrollMemory, static_cast<uint64_t>(itemCount));
    FolderView::DebugColumnLayoutSnapshot afterScrollSnapshot{};
    state.Require(g_folderWindow.DebugGetPaneColumnLayoutSnapshot(FolderWindow::Pane::Left, afterScrollSnapshot),
                  L"Huge FolderView scale failed to capture after-scroll layout snapshot.");
    const FolderView::RenderingDebugSnapshot renderingSnapshot = g_folderWindow.DebugGetPaneRenderingSnapshot(FolderWindow::Pane::Left);
    state.Require(
        renderingSnapshot.drawItemTransientBrushCreateCount == 0u,
        std::format(L"Huge FolderView scale selected-scroll created {} transient D2D brush(es).", renderingSnapshot.drawItemTransientBrushCreateCount));
    if (! state.failure.empty())
    {
        return false;
    }

    const uint64_t totalFrameCount   = FolderViewPerfMetricCountInRun(L"folder.frame.total_us", frameMetricScanOffset);
    const uint64_t presentFrameCount = FolderViewPerfMetricCountInRun(L"folder.frame.present_us", frameMetricScanOffset);
    std::wstring json;
    json.append(L"{\n");
    json.append(L"  \"case\": \"folderView_perf_huge_folder_scale\",\n");
    json.append(L"  \"provider\": \"builtin/file-system-dummy\",\n");
    json.append(L"  \"root\": ");
    AppendFolderViewColumnJsonString(json, dummyRoot.generic_wstring());
    json.append(L",\n");
    json.append(std::format(L"  \"itemCount\": {},\n", itemCount));
    json.append(std::format(L"  \"extensionCount\": {},\n", kExtensionCount));
    json.append(std::format(L"  \"largeOptInEnabled\": {},\n", optIn50k ? L"true" : L"false"));
    json.append(L"  \"fixturePolicy\": \"synthetic dummy provider; no 250k real-file fixture is created\",\n");
    json.append(std::format(L"  \"fixtureMaterializeUs\": {},\n", fixtureMaterializeUs));
    json.append(std::format(L"  \"enumerationUs\": {},\n", enumerationUs));
    json.append(std::format(L"  \"firstVisiblePaintUs\": {},\n", firstVisiblePaintUs));
    json.append(std::format(L"  \"sortToggleUs\": {},\n", sortToggleUs));
    json.append(std::format(L"  \"visibleItemCount\": {},\n", firstPaintSnapshot.visibleItems.size()));
    json.append(std::format(L"  \"selectedItemCount\": {},\n", g_folderWindow.DebugGetSelectedCount(FolderWindow::Pane::Left)));
    json.append(std::format(L"  \"afterScrollFirstVisibleIndex\": {},\n", afterScrollSnapshot.firstVisibleIndex));
    json.append(std::format(L"  \"afterScrollLastVisibleIndex\": {},\n", afterScrollSnapshot.lastVisibleIndex));
    json.append(std::format(L"  \"drawItemTransientBrushCreateCount\": {},\n", renderingSnapshot.drawItemTransientBrushCreateCount));
    json.append(L"  \"memory\": {\n");
    json.append(std::format(L"    \"beforeEnumerationWorkingSetBytes\": {},\n", beforeEnumerationMemory.workingSetBytes));
    json.append(std::format(L"    \"beforeEnumerationPrivateBytes\": {},\n", beforeEnumerationMemory.privateBytes));
    json.append(std::format(L"    \"afterFirstPaintWorkingSetBytes\": {},\n", afterFirstPaintMemory.workingSetBytes));
    json.append(std::format(L"    \"afterFirstPaintPrivateBytes\": {},\n", afterFirstPaintMemory.privateBytes));
    json.append(std::format(L"    \"afterScrollWorkingSetBytes\": {},\n", afterScrollMemory.workingSetBytes));
    json.append(std::format(L"    \"afterScrollPrivateBytes\": {},\n", afterScrollMemory.privateBytes));
    json.append(std::format(L"    \"afterFirstPaintWorkingSetBytesPerItem\": {},\n", afterFirstPaintMemory.workingSetBytes / static_cast<uint64_t>(itemCount)));
    json.append(std::format(L"    \"afterFirstPaintPrivateBytesPerItem\": {}\n", afterFirstPaintMemory.privateBytes / static_cast<uint64_t>(itemCount)));
    json.append(L"  },\n");
    json.append(L"  \"filterKeystrokeToPaintUs\": [");
    for (size_t i = 0; i < filterKeystrokeUs.size(); ++i)
    {
        json.append(std::format(L"{}", filterKeystrokeUs[i]));
        json.append(i + 1u < filterKeystrokeUs.size() ? L", " : L"");
    }
    json.append(L"],\n");
    json.append(L"  \"metricQuality\": {\n");
    AppendFolderViewMetricQualityJson(json, totalFrameCount, presentFrameCount, L"scale-case-gesture-sampled", L"    ");
    json.append(L"\n");
    json.append(L"  },\n");
    AppendFolderViewEnvironmentMatrixJson(json, CaptureFolderViewEnvironmentMatrix(mainWindow), L"  ");
    json.append(L"\n");
    json.append(L"}\n");

    const std::filesystem::path artifactPath = SelfTest::GetPerfArtifactPath(L"folderView_perf_huge_folder_scale_metrics.json");
    const bool artifactWriteOk               = ! artifactPath.empty() && SelfTest::WriteTextFile(artifactPath, json);
    state.Require(artifactWriteOk && SelfTest::PathExists(artifactPath), L"Failed to write huge FolderView scale perf artifact.");

    if (! state.failure.empty())
    {
        return false;
    }
    return CheckFolderViewPerfBudgets(L"folderView_perf_huge_folder_scale", frameMetricScanOffset, state);
}

[[nodiscard]] bool TestFolderViewFocusInvariantGenericRebuild(HWND mainWindow, CaseState& state) noexcept
{
    using namespace std::chrono_literals;

    if (! mainWindow || IsWindow(mainWindow) == FALSE)
    {
        state.Require(false, L"Main window handle invalid for FolderView current-invariant rebuild test.");
        return false;
    }
    if (! PrepareMainWindowForIsolatedUiCase(mainWindow, state, L"FolderView current-invariant generic rebuild"))
    {
        return false;
    }

    FolderViewDummyPluginHandles dummy{};
    state.Require(LoadFolderViewDummyPlugin(state, dummy), L"Failed to load dummy file system for FolderView current-invariant test.");
    if (! state.failure.empty())
    {
        return false;
    }

    std::string previousDummyConfig;
    state.Require(BackupPluginConfigurationForFolderViewPerf(dummy.informations.get(), previousDummyConfig),
                  L"Failed to snapshot dummy configuration for FolderView current-invariant test.");
    const auto restoreDummyConfig =
        wil::scope_exit([&]() noexcept { static_cast<void>(SetPluginConfigurationForFolderViewPerf(dummy.informations.get(), previousDummyConfig)); });
    constexpr std::string_view kDeterministicEmptyDummyConfig =
        R"json({"maxChildrenPerDirectory":0,"maxDepth":10,"seed":42,"latencyMs":0,"streamChunkLatencyMs":0,"virtualSpeedLimit":"0"})json";
    state.Require(SetPluginConfigurationForFolderViewPerf(dummy.informations.get(), kDeterministicEmptyDummyConfig),
                  L"Failed to apply deterministic dummy configuration for FolderView current-invariant test.");
    if (! state.failure.empty())
    {
        return false;
    }

    const std::filesystem::path root = std::filesystem::path(L"/folderview-current-invariant") / SanitizeFolderViewDummyPathSegment(NewGuidText());
    state.Require(EnsureFolderViewDummyFolderExists(dummy.fileSystem.get(), root), L"Failed to create dummy current-invariant root.");
    const auto cleanupRoot = wil::scope_exit([&]() noexcept
    {
        const std::wstring rootText = root.generic_wstring();
        static_cast<void>(dummy.fileSystem->DeleteItem(rootText.c_str(), FILESYSTEM_FLAG_RECURSIVE, nullptr, nullptr, nullptr));
    });

    const auto createItem = [&](std::wstring_view name) noexcept
    { state.Require(WriteTextFileFsIoForFolderViewPerf(dummy.io, root / name, "x"), std::format(L"Failed to create '{}'.", name)); };
    for (const std::wstring_view name : {L"a.txt", L"b.txt", L"c.txt", L"d.txt", L"e.txt"})
    {
        createItem(name);
    }
    if (! state.failure.empty())
    {
        return false;
    }

    const std::wstring pluginBefore                       = std::wstring(g_folderWindow.GetFileSystemPluginId(FolderWindow::Pane::Left));
    const std::optional<std::filesystem::path> pathBefore = g_folderWindow.GetCurrentPath(FolderWindow::Pane::Left);
    const FolderView::DisplayMode displayBefore           = g_folderWindow.GetDisplayMode(FolderWindow::Pane::Left);
    const FolderView::SortBy sortBefore                   = g_folderWindow.GetSortBy(FolderWindow::Pane::Left);
    const FolderView::SortDirection directionBefore       = g_folderWindow.GetSortDirection(FolderWindow::Pane::Left);
    const FolderView::NameFilterState filterBefore        = g_folderWindow.DebugGetNameFilterState(FolderWindow::Pane::Left);
    const auto restorePane                                = wil::scope_exit([&]() noexcept
    {
        g_folderWindow.SetNameFilterState(FolderWindow::Pane::Left, filterBefore, false);
        static_cast<void>(g_folderWindow.SetFileSystemPluginForPane(FolderWindow::Pane::Left, pluginBefore));
        g_folderWindow.SetDisplayMode(FolderWindow::Pane::Left, displayBefore);
        g_folderWindow.SetSort(FolderWindow::Pane::Left, sortBefore, directionBefore);
        if (pathBefore.has_value())
        {
            g_folderWindow.SetFolderPath(FolderWindow::Pane::Left, pathBefore.value());
        }
    });

    state.Require(SUCCEEDED(g_folderWindow.SetFileSystemPluginForPane(FolderWindow::Pane::Left, kBuiltinDummyFileSystemIdForFolderViewPerf.data())),
                  L"Failed to switch to dummy file system for FolderView current-invariant test.");
    g_folderWindow.SetDisplayMode(FolderWindow::Pane::Left, FolderView::DisplayMode::Detailed);
    g_folderWindow.SetSort(FolderWindow::Pane::Left, FolderView::SortBy::Name, FolderView::SortDirection::Ascending);
    g_folderWindow.DebugResetPaneVisibilityState(FolderWindow::Pane::Left);

    // Observe the first completed Hide Selected transition on the UI thread.
    // A later cache refresh may legitimately replace the latest reason with
    // SurvivingIdentity before a message-pumping wait returns to this test.
    bool observeHiddenRepair                               = false;
    bool hiddenRepairObserved                              = false;
    FolderView::CurrentResolutionReason hiddenRepairReason = FolderView::CurrentResolutionReason::Unresolved;
    size_t hiddenRepairSelectionCount                      = 0u;
    std::atomic<uint32_t> enumerationCount{0u};
    g_folderWindow.SetPaneEnumerationCompletedCallback(FolderWindow::Pane::Left,
                                                       [&](const std::filesystem::path& folder) noexcept
    {
        if (OrdinalString::EqualsNoCase(folder.generic_wstring(), root.generic_wstring()))
        {
            if (observeHiddenRepair && ! hiddenRepairObserved)
            {
                const auto completed = g_folderWindow.DebugGetFocusSelectionStateSnapshot(FolderWindow::Pane::Left);
                if (completed.itemCount == 2u && completed.currentDisplayName == L"z.txt")
                {
                    hiddenRepairObserved       = true;
                    hiddenRepairReason         = completed.resolutionReason;
                    hiddenRepairSelectionCount = completed.selectedCount;
                }
            }
            enumerationCount.fetch_add(1u, std::memory_order_release);
        }
    });
    const auto clearEnumerationCallback = wil::scope_exit([&]() noexcept { g_folderWindow.SetPaneEnumerationCompletedCallback(FolderWindow::Pane::Left, {}); });

    g_folderWindow.SetFolderPath(FolderWindow::Pane::Left, root);
    state.Require(WaitForPanePluginPathForFolderViewPerf(FolderWindow::Pane::Left, root, SelfTest::Scale(10000ms)),
                  L"FolderView current-invariant root did not load.");
    state.Require(WaitForAtomicAtLeast(enumerationCount, 1u, SelfTest::Scale(10000ms)), L"FolderView current-invariant initial enumeration did not complete.");
    state.Require(WaitForFolderViewItemCount(FolderWindow::Pane::Left, 5u, SelfTest::Scale(10000ms)),
                  L"FolderView current-invariant initial model did not settle.");

    const HWND folderView = g_folderWindow.GetFolderViewHwnd(FolderWindow::Pane::Left);
    state.Require(folderView && IsWindow(folderView) != FALSE && g_folderWindow.DebugFocusItemByDisplayName(FolderWindow::Pane::Left, L"b.txt"),
                  L"Dummy-provider Cut enablement fixture is unavailable.");
    const std::optional<POINT> dummyItemPoint = g_folderWindow.DebugGetPaneItemCenterClientPointForSelfTest(FolderWindow::Pane::Left, L"b.txt");
    state.Require(dummyItemPoint.has_value(), L"Dummy-provider Cut enablement item point is unavailable.");
    if (! state.failure.empty())
    {
        return false;
    }
    std::atomic<bool> dummyMenuOpened{false};
    std::atomic<bool> dummyCutDisabled{false};
    std::jthread dummyMenuCloser([&](std::stop_token stopToken) noexcept
    {
        const auto deadline = std::chrono::steady_clock::now() + SelfTest::Scale(3000ms);
        while (! stopToken.stop_requested() && std::chrono::steady_clock::now() < deadline)
        {
            const HWND popup = FindVisibleOwnedDxUiContextMenuWindow(folderView);
            DxUi::ContextMenuPopupDebugState popupState{};
            if (popup && IsWindow(popup) != FALSE && DxUi::DebugGetContextMenuPopupState(popup, popupState))
            {
                dummyMenuOpened.store(true, std::memory_order_release);
                const auto cut = std::ranges::find(popupState.itemTexts, L"Cut");
                if (cut != popupState.itemTexts.end())
                {
                    const size_t cutIndex = static_cast<size_t>(std::distance(popupState.itemTexts.begin(), cut));
                    dummyCutDisabled.store(cutIndex < popupState.itemEnabled.size() && ! popupState.itemEnabled[cutIndex], std::memory_order_release);
                }
                PostMessageW(popup, WM_KEYDOWN, VK_ESCAPE, 0);
                PostMessageW(popup, WM_KEYUP, VK_ESCAPE, 0);
                return;
            }
            std::this_thread::sleep_for(10ms);
        }
    });
    POINT dummyItemScreenPoint = dummyItemPoint.value();
    ClientToScreen(folderView, &dummyItemScreenPoint);
    SendMessageW(folderView, WM_CONTEXTMENU, reinterpret_cast<WPARAM>(folderView), MAKELPARAM(dummyItemScreenPoint.x, dummyItemScreenPoint.y));
    dummyMenuCloser.join();
    state.Require(dummyMenuOpened.load(std::memory_order_acquire), L"Dummy-provider item context menu did not open.");
    state.Require(dummyCutDisabled.load(std::memory_order_acquire), L"FolderView Cut must be disabled for providers that cannot publish local CF_HDROP paths.");

    const auto requireInvariant = [&](std::wstring_view expectedCurrent, size_t expectedItemCount, std::wstring_view stage) noexcept
    {
        const FolderView::DebugFocusSelectionStateSnapshot snapshot = g_folderWindow.DebugGetFocusSelectionStateSnapshot(FolderWindow::Pane::Left);
        const bool empty                                            = expectedItemCount == 0u;
        state.Require(snapshot.itemCount == expectedItemCount,
                      std::format(L"{} item count mismatch: expected {}, got {}.", stage, expectedItemCount, snapshot.itemCount));
        state.Require(empty ? snapshot.currentIndex == static_cast<size_t>(-1) : snapshot.currentIndex < snapshot.itemCount,
                      std::format(L"{} current index violates the empty/nonempty invariant.", stage));
        state.Require(snapshot.focusedFlagCount == (empty ? 0u : 1u),
                      std::format(L"{} focused-flag count mismatch: expected {}, got {}.", stage, empty ? 0u : 1u, snapshot.focusedFlagCount));
        state.Require((empty && snapshot.anchorIndex == static_cast<size_t>(-1)) || (! empty && snapshot.anchorIndex < snapshot.itemCount),
                      std::format(L"{} anchor invariant failed.", stage));
        state.Require(snapshot.currentDisplayName == expectedCurrent,
                      std::format(L"{} current mismatch: expected '{}', got '{}'.", stage, expectedCurrent, snapshot.currentDisplayName));
        return snapshot;
    };
    const auto deleteItem = [&](std::wstring_view name) noexcept
    {
        const std::wstring pathText = (root / name).generic_wstring();
        const HRESULT hr            = dummy.fileSystem->DeleteItem(pathText.c_str(), FILESYSTEM_FLAG_NONE, nullptr, nullptr, nullptr);
        state.Require(hr == S_OK, std::format(L"Failed to delete '{}'. hr=0x{:08X}", name, static_cast<uint32_t>(hr)));
    };
    const auto refresh = [&](size_t expectedCount, std::wstring_view expectedCurrent, std::wstring_view stage) noexcept
    {
        const uint32_t before = enumerationCount.load(std::memory_order_acquire);
        g_folderWindow.CommandRefresh(FolderWindow::Pane::Left);
        state.Require(WaitForAtomicAtLeast(enumerationCount, before + 1u, SelfTest::Scale(10000ms)), std::format(L"{} enumeration did not complete.", stage));
        state.Require(WaitForFolderViewItemCount(FolderWindow::Pane::Left, expectedCount, SelfTest::Scale(10000ms)),
                      std::format(L"{} item model did not settle.", stage));
        if (! expectedCurrent.empty())
        {
            state.Require(WaitForFolderViewFocusedItem(FolderWindow::Pane::Left, expectedCurrent, SelfTest::Scale(3000ms)),
                          std::format(L"{} current did not settle on '{}'.", stage, expectedCurrent));
        }
        return requireInvariant(expectedCurrent, expectedCount, stage);
    };

    state.Require(g_folderWindow.DebugFocusItemByDisplayName(FolderWindow::Pane::Left, L"b.txt"), L"Could not focus b.txt.");
    g_folderWindow.SetPaneSelectionByDisplayNamePredicate(
        FolderWindow::Pane::Left, [](std::wstring_view name) noexcept { return name == L"a.txt" || name == L"e.txt"; }, true);
    const auto beforeSingle = g_folderWindow.DebugGetFocusSelectionStateSnapshot(FolderWindow::Pane::Left);
    deleteItem(L"b.txt");
    const auto afterSingle = refresh(4u, L"c.txt", L"single-row keyed successor");
    state.Require(afterSingle.selectionDigest == beforeSingle.selectionDigest && afterSingle.selectedCount == beforeSingle.selectedCount,
                  L"Generic current repair mutated the surviving selection.");
    state.Require(afterSingle.resolutionReason == FolderView::CurrentResolutionReason::GenericSuccessor,
                  L"Single-row disappearance did not report GenericSuccessor.");

    state.Require(g_folderWindow.DebugFocusItemByDisplayName(FolderWindow::Pane::Left, L"c.txt"), L"Could not focus c.txt.");
    g_folderWindow.SetPaneSelectionByDisplayNamePredicate(FolderWindow::Pane::Left, [](std::wstring_view name) noexcept { return name == L"e.txt"; }, true);
    const auto beforeMultiple = g_folderWindow.DebugGetFocusSelectionStateSnapshot(FolderWindow::Pane::Left);
    deleteItem(L"a.txt");
    deleteItem(L"c.txt");
    const auto afterMultiple = refresh(2u, L"d.txt", L"multi-row keyed successor");
    state.Require(afterMultiple.selectionDigest == beforeMultiple.selectionDigest && afterMultiple.selectedCount == 1u,
                  L"Multi-row current repair mutated the surviving selection.");
    state.Require(afterMultiple.resolutionReason == FolderView::CurrentResolutionReason::GenericSuccessor,
                  L"Multi-row disappearance did not report GenericSuccessor.");

    state.Require(g_folderWindow.DebugFocusItemByDisplayName(FolderWindow::Pane::Left, L"e.txt"), L"Could not focus e.txt.");
    deleteItem(L"e.txt");
    const auto afterLast = refresh(1u, L"d.txt", L"keyed predecessor");
    state.Require(afterLast.resolutionReason == FolderView::CurrentResolutionReason::GenericPredecessor,
                  L"Last-row disappearance did not report GenericPredecessor.");
    state.Require(afterLast.selectedCount == 0u, L"Removed selection survived as latent selection.");

    for (const std::wstring_view name : {L"none0.txt", L"none1.txt", L"none2.txt", L"none3.txt", L"none4.txt"})
    {
        createItem(name);
    }
    refresh(6u, L"d.txt", L"Sort None fixture population");
    g_folderWindow.SetSort(FolderWindow::Pane::Left, FolderView::SortBy::None, FolderView::SortDirection::Ascending);
    state.Require(g_folderWindow.DebugFocusItemByDisplayName(FolderWindow::Pane::Left, L"none2.txt"), L"Could not focus none2.txt.");
    deleteItem(L"none1.txt");
    deleteItem(L"none2.txt");
    deleteItem(L"none3.txt");
    const auto sortNoneSuccessor = refresh(3u, L"none4.txt", L"Sort None prior-order successor");
    state.Require(sortNoneSuccessor.resolutionReason == FolderView::CurrentResolutionReason::GenericSuccessor,
                  L"Sort None disappearance did not choose its prior-order successor.");
    deleteItem(L"none4.txt");
    const auto sortNonePredecessor = refresh(2u, L"none0.txt", L"Sort None prior-order predecessor");
    state.Require(sortNonePredecessor.resolutionReason == FolderView::CurrentResolutionReason::GenericPredecessor,
                  L"Sort None tail disappearance did not choose its nearest prior-order predecessor.");

    deleteItem(L"d.txt");
    deleteItem(L"none0.txt");
    refresh(0u, {}, L"empty result");
    createItem(L"z.txt");
    const auto repopulated = refresh(1u, L"z.txt", L"repopulation fail-safe");
    state.Require(repopulated.resolutionReason == FolderView::CurrentResolutionReason::FirstItem,
                  L"Repopulation from empty did not establish the first row as current.");

    for (const std::wstring_view name : {L"a.txt", L"b.log", L"c.txt"})
    {
        createItem(name);
    }
    refresh(4u, L"z.txt", L"filter/hide repair fixture population");
    g_folderWindow.SetSort(FolderWindow::Pane::Left, FolderView::SortBy::Name, FolderView::SortDirection::Ascending);
    state.Require(g_folderWindow.DebugFocusItemByDisplayName(FolderWindow::Pane::Left, L"b.log"), L"Could not focus b.log before filter repair.");
    const uint32_t beforeFilter = enumerationCount.load(std::memory_order_acquire);
    g_folderWindow.SetNameFilterState(FolderWindow::Pane::Left, FolderView::NameFilterState{.enabled = true, .text = L"*.txt"}, true);
    state.Require(WaitForAtomicAtLeast(enumerationCount, beforeFilter + 1u, SelfTest::Scale(10000ms)), L"Filter repair enumeration did not complete.");
    state.Require(WaitForFolderViewItemCount(FolderWindow::Pane::Left, 3u, SelfTest::Scale(10000ms)) &&
                      WaitForFolderViewFocusedItem(FolderWindow::Pane::Left, L"c.txt", SelfTest::Scale(3000ms)),
                  L"Filtering the current item did not choose the next item in resulting UI order.");
    const auto filteredRepair = requireInvariant(L"c.txt", 3u, L"filter-removal successor");
    state.Require(filteredRepair.resolutionReason == FolderView::CurrentResolutionReason::GenericSuccessor, L"Filter removal did not report GenericSuccessor.");

    g_folderWindow.SetPaneSelectionByDisplayNamePredicate(FolderWindow::Pane::Left, [](std::wstring_view name) noexcept { return name == L"c.txt"; }, true);
    const uint32_t beforeHide = enumerationCount.load(std::memory_order_acquire);
    observeHiddenRepair       = true;
    g_folderWindow.CommandSelectionHideSelectedNames(FolderWindow::Pane::Left);
    state.Require(WaitForAtomicAtLeast(enumerationCount, beforeHide + 1u, SelfTest::Scale(10000ms)), L"Hide Selected repair enumeration did not complete.");
    state.Require(WaitForFolderViewItemCount(FolderWindow::Pane::Left, 2u, SelfTest::Scale(10000ms)) &&
                      WaitForFolderViewFocusedItem(FolderWindow::Pane::Left, L"z.txt", SelfTest::Scale(3000ms)),
                  L"Hiding the selected current item did not choose the next resulting visible item.");
    const auto hiddenRepair = requireInvariant(L"z.txt", 2u, L"hidden-name successor");
    observeHiddenRepair     = false;
    state.Require(
        hiddenRepairObserved && hiddenRepairReason == FolderView::CurrentResolutionReason::GenericSuccessor && hiddenRepairSelectionCount == 0u,
        std::format(L"Hidden current transition mismatch: observed={} reason={} expected={} selected={} latestReason={} enumerations={} beforeHide={}.",
                    hiddenRepairObserved,
                    static_cast<uint32_t>(hiddenRepairReason),
                    static_cast<uint32_t>(FolderView::CurrentResolutionReason::GenericSuccessor),
                    hiddenRepairSelectionCount,
                    static_cast<uint32_t>(hiddenRepair.resolutionReason),
                    enumerationCount.load(std::memory_order_acquire),
                    beforeHide));
    state.Require(hiddenRepair.selectedCount == 0u,
                  std::format(L"Hidden current repair selected its replacement: selected={} reason={}.",
                              hiddenRepair.selectedCount,
                              static_cast<uint32_t>(hiddenRepair.resolutionReason)));

    const uint32_t beforeShow = enumerationCount.load(std::memory_order_acquire);
    g_folderWindow.CommandSelectionShowHiddenNames(FolderWindow::Pane::Left);
    state.Require(WaitForAtomicAtLeast(enumerationCount, beforeShow + 1u, SelfTest::Scale(10000ms)),
                  L"Show Hidden Names enumeration did not complete after repair test.");
    state.Require(! g_folderWindow.DebugIsItemSelected(FolderWindow::Pane::Left, L"c.txt"), L"A hidden selected identity resurrected when shown again.");
    g_folderWindow.SetNameFilterState(FolderWindow::Pane::Left, FolderView::NameFilterState{}, true);

    return state.failure.empty();
}

[[nodiscard]] bool TestFolderViewFocusMemoryBoundedLru(HWND mainWindow, CaseState& state) noexcept
{
    if (! mainWindow || IsWindow(mainWindow) == FALSE)
    {
        state.Require(false, L"Main window handle invalid for FolderView focus-memory LRU test.");
        return false;
    }
    if (! PrepareMainWindowForIsolatedUiCase(mainWindow, state, L"FolderView bounded focus memory"))
    {
        return false;
    }

    FolderViewDummyPluginHandles dummy{};
    state.Require(LoadFolderViewDummyPlugin(state, dummy), L"Failed to load dummy file system for FolderView focus-memory LRU test.");
    if (! state.failure.empty())
    {
        return false;
    }

    const std::wstring pluginBefore                       = std::wstring(g_folderWindow.GetFileSystemPluginId(FolderWindow::Pane::Left));
    const std::optional<std::filesystem::path> pathBefore = g_folderWindow.GetCurrentPath(FolderWindow::Pane::Left);
    const auto restorePane                                = wil::scope_exit([&]() noexcept
    {
        static_cast<void>(g_folderWindow.SetFileSystemPluginForPane(FolderWindow::Pane::Left, pluginBefore));
        if (pathBefore.has_value())
        {
            g_folderWindow.SetFolderPath(FolderWindow::Pane::Left, pathBefore.value());
        }
    });

    state.Require(SUCCEEDED(g_folderWindow.SetFileSystemPluginForPane(FolderWindow::Pane::Left, kBuiltinDummyFileSystemIdForFolderViewPerf.data())),
                  L"Failed to switch to dummy file system for FolderView focus-memory LRU test.");
    g_folderWindow.DebugClearPaneFocusMemoryForSelfTest(FolderWindow::Pane::Left);

    const std::filesystem::path memoryRoot = L"/folderview-focus-memory-lru";
    for (size_t index = 0u; index < 512u; ++index)
    {
        state.Require(g_folderWindow.DebugRememberPaneFocusMemoryEntryForSelfTest(
                          FolderWindow::Pane::Left, memoryRoot / std::format(L"location_{:03}", index), std::format(L"item_{:03}.txt", index)),
                      std::format(L"Failed to cache focus-memory entry {}.", index));
    }
    FolderView::DebugFocusSelectionStateSnapshot snapshot = g_folderWindow.DebugGetFocusSelectionStateSnapshot(FolderWindow::Pane::Left);
    state.Require(snapshot.focusMemoryEntryCount == 512u, L"Focus-memory entry cap fixture did not reach exactly 512 entries.");
    state.Require(snapshot.focusMemoryPayloadBytes <= 512u * 1024u, L"Focus-memory payload exceeded 512 KiB before eviction.");
    state.Require(snapshot.focusMemoryEvictionCount == 0u, L"Focus-memory evicted an entry before reaching either cap.");

    const std::wstring touched = g_folderWindow.DebugLookupPaneFocusMemoryEntryForSelfTest(FolderWindow::Pane::Left, memoryRoot / L"location_000");
    state.Require(OrdinalString::EqualsNoCase(touched, L"item_000.txt"), L"Focus-memory touch lookup did not return entry zero.");
    state.Require(g_folderWindow.DebugRememberPaneFocusMemoryEntryForSelfTest(FolderWindow::Pane::Left, memoryRoot / L"location_512", L"item_512.txt"),
                  L"Failed to insert the entry-cap eviction probe.");

    snapshot = g_folderWindow.DebugGetFocusSelectionStateSnapshot(FolderWindow::Pane::Left);
    state.Require(snapshot.focusMemoryEntryCount == 512u, L"Focus-memory did not enforce the 512-entry cap.");
    state.Require(snapshot.focusMemoryPayloadBytes <= 512u * 1024u, L"Focus-memory payload exceeded 512 KiB after entry-cap eviction.");
    state.Require(snapshot.focusMemoryEvictionCount == 1u, L"Focus-memory did not evict exactly one least-recently-used entry.");
    state.Require(g_folderWindow.DebugLookupPaneFocusMemoryEntryForSelfTest(FolderWindow::Pane::Left, memoryRoot / L"location_001").empty(),
                  L"Focus-memory did not evict the deterministic least-recently-used entry.");
    state.Require(OrdinalString::EqualsNoCase(g_folderWindow.DebugLookupPaneFocusMemoryEntryForSelfTest(FolderWindow::Pane::Left, memoryRoot / L"location_000"),
                                              L"item_000.txt"),
                  L"Focus-memory evicted the recently touched entry.");

    state.Require(SUCCEEDED(g_folderWindow.SetFileSystemPluginForPane(FolderWindow::Pane::Left, L"builtin/file-system")),
                  L"Failed to switch providers during focus-memory isolation test.");
    state.Require(g_folderWindow.DebugLookupPaneFocusMemoryEntryForSelfTest(FolderWindow::Pane::Left, memoryRoot / L"location_000").empty(),
                  L"Focus-memory collided across provider identity.");
    state.Require(SUCCEEDED(g_folderWindow.SetFileSystemPluginForPane(FolderWindow::Pane::Left, kBuiltinDummyFileSystemIdForFolderViewPerf.data())),
                  L"Failed to restore dummy provider during focus-memory isolation test.");
    state.Require(OrdinalString::EqualsNoCase(g_folderWindow.DebugLookupPaneFocusMemoryEntryForSelfTest(FolderWindow::Pane::Left, memoryRoot / L"location_000"),
                                              L"item_000.txt"),
                  L"Focus-memory did not survive a provider round-trip.");

    g_folderWindow.DebugClearPaneFocusMemoryForSelfTest(FolderWindow::Pane::Left);
    state.Require(g_folderWindow.DebugRememberPaneFocusMemoryEntryForSelfTest(FolderWindow::Pane::Left, memoryRoot / L"useful", L"useful.txt"),
                  L"Failed to insert useful focus-memory entry before oversized probe.");
    const std::wstring oversizedItem(300000u, L'x');
    state.Require(! g_folderWindow.DebugRememberPaneFocusMemoryEntryForSelfTest(FolderWindow::Pane::Left, memoryRoot / L"oversized", oversizedItem),
                  L"Focus-memory accepted an individually oversized entry.");
    snapshot = g_folderWindow.DebugGetFocusSelectionStateSnapshot(FolderWindow::Pane::Left);
    state.Require(snapshot.focusMemoryEntryCount == 1u && snapshot.focusMemoryEvictionCount == 0u,
                  L"Oversized focus-memory insertion evicted the useful cache.");
    state.Require(snapshot.focusMemoryOversizedEntryNoCacheCount == 1u &&
                      snapshot.focusMemoryLastNoCacheReason == FolderView::FocusMemoryNoCacheReason::OversizedEntry,
                  L"Oversized focus-memory insertion did not report its no-cache reason.");

    g_folderWindow.DebugClearPaneFocusMemoryForSelfTest(FolderWindow::Pane::Left);
    const std::wstring payloadItemOne(140000u, L'a');
    const std::wstring payloadItemTwo(140000u, L'b');
    state.Require(g_folderWindow.DebugRememberPaneFocusMemoryEntryForSelfTest(FolderWindow::Pane::Left, memoryRoot / L"payload-one", payloadItemOne),
                  L"Failed to insert the first payload-cap entry.");
    state.Require(g_folderWindow.DebugRememberPaneFocusMemoryEntryForSelfTest(FolderWindow::Pane::Left, memoryRoot / L"payload-two", payloadItemTwo),
                  L"Failed to insert the second payload-cap entry.");
    snapshot = g_folderWindow.DebugGetFocusSelectionStateSnapshot(FolderWindow::Pane::Left);
    state.Require(snapshot.focusMemoryEntryCount == 1u && snapshot.focusMemoryEvictionCount == 1u,
                  L"Focus-memory did not deterministically evict for the 512-KiB payload cap.");
    state.Require(snapshot.focusMemoryPayloadBytes <= 512u * 1024u, L"Focus-memory exceeded the 512-KiB payload cap after eviction.");
    state.Require(g_folderWindow.DebugLookupPaneFocusMemoryEntryForSelfTest(FolderWindow::Pane::Left, memoryRoot / L"payload-one").empty(),
                  L"Focus-memory retained the least-recently-used payload entry.");
    state.Require(g_folderWindow.DebugLookupPaneFocusMemoryEntryForSelfTest(FolderWindow::Pane::Left, memoryRoot / L"payload-two").size() ==
                      payloadItemTwo.size(),
                  L"Focus-memory did not retain the newest payload entry.");

    const std::wstring dummyPluginId             = std::wstring(g_folderWindow.GetFileSystemPluginId(FolderWindow::Pane::Left));
    const std::wstring dummyContext              = std::wstring(g_folderWindow.GetFileSystemInstanceContext(FolderWindow::Pane::Left));
    const std::filesystem::path sameTextLocation = memoryRoot / L"same-text-location";
    g_folderWindow.DebugClearPaneFocusMemoryForSelfTest(FolderWindow::Pane::Left);
    g_folderWindow.DebugSetPaneFileSystemContextForSelfTest(FolderWindow::Pane::Left, dummyPluginId, L"mount-A");
    state.Require(g_folderWindow.DebugRememberPaneFocusMemoryEntryForSelfTest(FolderWindow::Pane::Left, sameTextLocation, L"mount-a.txt"),
                  L"Failed to record mount-A focus memory.");
    g_folderWindow.DebugSetPaneFileSystemContextForSelfTest(FolderWindow::Pane::Left, dummyPluginId, L"mount-B");
    state.Require(g_folderWindow.DebugLookupPaneFocusMemoryEntryForSelfTest(FolderWindow::Pane::Left, sameTextLocation).empty(),
                  L"Focus memory collided across provider instance/mount context.");
    state.Require(g_folderWindow.DebugRememberPaneFocusMemoryEntryForSelfTest(FolderWindow::Pane::Left, sameTextLocation, L"mount-b.txt"),
                  L"Failed to record mount-B focus memory.");
    g_folderWindow.DebugSetPaneFileSystemContextForSelfTest(FolderWindow::Pane::Left, dummyPluginId, L"mount-A");
    state.Require(
        OrdinalString::EqualsNoCase(g_folderWindow.DebugLookupPaneFocusMemoryEntryForSelfTest(FolderWindow::Pane::Left, sameTextLocation), L"mount-a.txt"),
        L"Focus memory did not restore the independent mount-A entry.");
    g_folderWindow.DebugSetPaneFileSystemContextForSelfTest(FolderWindow::Pane::Left, dummyPluginId, L"mount-B");
    state.Require(
        OrdinalString::EqualsNoCase(g_folderWindow.DebugLookupPaneFocusMemoryEntryForSelfTest(FolderWindow::Pane::Left, sameTextLocation), L"mount-b.txt"),
        L"Focus memory did not restore the independent mount-B entry.");
    g_folderWindow.DebugSetPaneFileSystemContextForSelfTest(FolderWindow::Pane::Left, dummyPluginId, dummyContext);

    return state.failure.empty();
}

[[nodiscard]] bool TestFolderViewFocusMemoryNavigationRoundtrip(HWND mainWindow, CaseState& state) noexcept
{
    using namespace std::chrono_literals;

    if (! mainWindow || IsWindow(mainWindow) == FALSE)
    {
        state.Require(false, L"Main window handle invalid for FolderView focus-memory navigation test.");
        return false;
    }
    if (! PrepareMainWindowForIsolatedUiCase(mainWindow, state, L"FolderView focus-memory navigation round-trip"))
    {
        return false;
    }

    FolderViewDummyPluginHandles dummy{};
    state.Require(LoadFolderViewDummyPlugin(state, dummy), L"Failed to load dummy file system for FolderView focus-memory navigation test.");
    if (! state.failure.empty())
    {
        return false;
    }

    std::string previousDummyConfig;
    state.Require(BackupPluginConfigurationForFolderViewPerf(dummy.informations.get(), previousDummyConfig),
                  L"Failed to snapshot dummy configuration for FolderView focus-memory navigation test.");
    const auto restoreDummyConfig =
        wil::scope_exit([&]() noexcept { static_cast<void>(SetPluginConfigurationForFolderViewPerf(dummy.informations.get(), previousDummyConfig)); });
    constexpr std::string_view kDeterministicEmptyDummyConfig =
        R"json({"maxChildrenPerDirectory":0,"maxDepth":10,"seed":42,"latencyMs":0,"streamChunkLatencyMs":0,"virtualSpeedLimit":"0"})json";
    state.Require(SetPluginConfigurationForFolderViewPerf(dummy.informations.get(), kDeterministicEmptyDummyConfig),
                  L"Failed to apply deterministic dummy configuration for FolderView focus-memory navigation test.");

    const std::filesystem::path root    = std::filesystem::path(L"/folderview-focus-memory-navigation") / SanitizeFolderViewDummyPathSegment(NewGuidText());
    const std::filesystem::path folderA = root / L"a";
    const std::filesystem::path folderB = root / L"b";
    state.Require(EnsureFolderViewDummyFolderExists(dummy.fileSystem.get(), folderA), L"Failed to create focus-memory folder A.");
    state.Require(EnsureFolderViewDummyFolderExists(dummy.fileSystem.get(), folderB), L"Failed to create focus-memory folder B.");
    state.Require(WriteTextFileFsIoForFolderViewPerf(dummy.io, folderA / L"one.txt", "1"), L"Failed to create folder A item one.");
    state.Require(WriteTextFileFsIoForFolderViewPerf(dummy.io, folderA / L"two.txt", "2"), L"Failed to create folder A item two.");
    state.Require(WriteTextFileFsIoForFolderViewPerf(dummy.io, folderB / L"other.txt", "3"), L"Failed to create folder B item.");
    if (! state.failure.empty())
    {
        return false;
    }
    const auto cleanupRoot = wil::scope_exit([&]() noexcept
    {
        const std::wstring rootText = root.generic_wstring();
        static_cast<void>(dummy.fileSystem->DeleteItem(rootText.c_str(), FILESYSTEM_FLAG_RECURSIVE, nullptr, nullptr, nullptr));
    });

    const std::wstring pluginBefore                       = std::wstring(g_folderWindow.GetFileSystemPluginId(FolderWindow::Pane::Left));
    const std::optional<std::filesystem::path> pathBefore = g_folderWindow.GetCurrentPath(FolderWindow::Pane::Left);
    const FolderView::SortBy sortBefore                   = g_folderWindow.GetSortBy(FolderWindow::Pane::Left);
    const FolderView::SortDirection directionBefore       = g_folderWindow.GetSortDirection(FolderWindow::Pane::Left);
    const auto restorePane                                = wil::scope_exit([&]() noexcept
    {
        static_cast<void>(g_folderWindow.SetFileSystemPluginForPane(FolderWindow::Pane::Left, pluginBefore));
        g_folderWindow.SetSort(FolderWindow::Pane::Left, sortBefore, directionBefore);
        if (pathBefore.has_value())
        {
            g_folderWindow.SetFolderPath(FolderWindow::Pane::Left, pathBefore.value());
        }
    });

    state.Require(SUCCEEDED(g_folderWindow.SetFileSystemPluginForPane(FolderWindow::Pane::Left, kBuiltinDummyFileSystemIdForFolderViewPerf.data())),
                  L"Failed to switch to dummy provider for focus-memory navigation test.");
    g_folderWindow.SetSort(FolderWindow::Pane::Left, FolderView::SortBy::Name, FolderView::SortDirection::Ascending);
    g_folderWindow.DebugClearPaneFocusMemoryForSelfTest(FolderWindow::Pane::Left);

    std::atomic<uint32_t> enumerationCount{0u};
    g_folderWindow.SetPaneEnumerationCompletedCallback(
        FolderWindow::Pane::Left, [&](const std::filesystem::path&) noexcept { enumerationCount.fetch_add(1u, std::memory_order_release); });
    const auto clearEnumerationCallback = wil::scope_exit([&]() noexcept { g_folderWindow.SetPaneEnumerationCompletedCallback(FolderWindow::Pane::Left, {}); });
    const auto navigate                 = [&](const std::filesystem::path& folder, size_t itemCount, std::wstring_view stage) noexcept
    {
        const uint32_t before = enumerationCount.load(std::memory_order_acquire);
        g_folderWindow.SetFolderPath(FolderWindow::Pane::Left, folder);
        state.Require(WaitForPanePluginPathForFolderViewPerf(FolderWindow::Pane::Left, folder, SelfTest::Scale(10000ms)),
                      std::format(L"{} path did not settle.", stage));
        state.Require(WaitForAtomicAtLeast(enumerationCount, before + 1u, SelfTest::Scale(10000ms)), std::format(L"{} enumeration did not complete.", stage));
        state.Require(WaitForFolderViewItemCount(FolderWindow::Pane::Left, itemCount, SelfTest::Scale(10000ms)),
                      std::format(L"{} model did not settle.", stage));
    };

    navigate(folderA, 2u, L"initial folder A");
    state.Require(g_folderWindow.DebugFocusItemByDisplayName(FolderWindow::Pane::Left, L"two.txt"), L"Failed to focus folder A item two.");
    g_folderWindow.SetPaneSelectionByDisplayNamePredicate(FolderWindow::Pane::Left, [](std::wstring_view name) noexcept { return name == L"one.txt"; }, true);
    state.Require(g_folderWindow.DebugGetSelectedCount(FolderWindow::Pane::Left) == 1u, L"Failed to establish the selection-clearing navigation fixture.");
    FolderView::SelectionStats cachedSelection = g_folderWindow.DebugGetCachedPaneSelectionStatsForSelfTest(FolderWindow::Pane::Left);
    state.Require(cachedSelection.selectedFiles == 1u && cachedSelection.selectedFolders == 0u,
                  L"FolderWindow did not receive the selected-file fixture before navigation.");

    navigate(folderB, 1u, L"folder B");
    state.Require(g_folderWindow.DebugGetSelectedCount(FolderWindow::Pane::Left) == 0u, L"Navigation to folder B retained selection from folder A.");
    cachedSelection = g_folderWindow.DebugGetCachedPaneSelectionStatsForSelfTest(FolderWindow::Pane::Left);
    state.Require(cachedSelection.selectedFiles == 0u && cachedSelection.selectedFolders == 0u && ! cachedSelection.singleItem.has_value(),
                  L"Successful navigation did not notify FolderWindow that the prior selection was cleared.");
    navigate(folderA, 2u, L"folder A return");
    state.Require(WaitForFolderViewFocusedItem(FolderWindow::Pane::Left, L"two.txt", SelfTest::Scale(3000ms)),
                  L"Folder A current item was not restored after the navigation round-trip.");
    FolderView::DebugFocusSelectionStateSnapshot snapshot = g_folderWindow.DebugGetFocusSelectionStateSnapshot(FolderWindow::Pane::Left);
    state.Require(snapshot.resolutionReason == FolderView::CurrentResolutionReason::NavigationMemoryRestore,
                  L"Folder A return did not report NavigationMemoryRestore.");
    state.Require(snapshot.selectedCount == 0u, L"Focus-memory restoration also restored selection.");

    const uint32_t beforeHistoryBack = enumerationCount.load(std::memory_order_acquire);
    SendMessageW(mainWindow, WM_COMMAND, MAKEWPARAM(IDM_LEFT_GO_TO_BACK, 0), 0);
    state.Require(WaitForPanePluginPathForFolderViewPerf(FolderWindow::Pane::Left, folderB, SelfTest::Scale(10000ms)),
                  L"History Back did not return to folder B.");
    state.Require(WaitForAtomicAtLeast(enumerationCount, beforeHistoryBack + 1u, SelfTest::Scale(10000ms)), L"History Back enumeration did not complete.");
    state.Require(WaitForFolderViewFocusedItem(FolderWindow::Pane::Left, L"other.txt", SelfTest::Scale(3000ms)) &&
                      g_folderWindow.DebugGetSelectedCount(FolderWindow::Pane::Left) == 0u,
                  L"History Back did not restore folder B current-only state.");

    const uint32_t beforeHistoryForward = enumerationCount.load(std::memory_order_acquire);
    SendMessageW(mainWindow, WM_COMMAND, MAKEWPARAM(IDM_LEFT_GO_TO_FORWARD, 0), 0);
    state.Require(WaitForPanePluginPathForFolderViewPerf(FolderWindow::Pane::Left, folderA, SelfTest::Scale(10000ms)),
                  L"History Forward did not return to folder A.");
    state.Require(WaitForAtomicAtLeast(enumerationCount, beforeHistoryForward + 1u, SelfTest::Scale(10000ms)),
                  L"History Forward enumeration did not complete.");
    state.Require(WaitForFolderViewFocusedItem(FolderWindow::Pane::Left, L"two.txt", SelfTest::Scale(3000ms)) &&
                      g_folderWindow.DebugGetSelectedCount(FolderWindow::Pane::Left) == 0u,
                  L"History Forward did not restore folder A current-only state.");

    state.Require(SUCCEEDED(g_folderWindow.SetFileSystemPluginForPane(FolderWindow::Pane::Left, L"builtin/file-system")),
                  L"Failed to switch away from dummy provider during navigation round-trip.");
    state.Require(SUCCEEDED(g_folderWindow.SetFileSystemPluginForPane(FolderWindow::Pane::Left, kBuiltinDummyFileSystemIdForFolderViewPerf.data())),
                  L"Failed to switch back to dummy provider during navigation round-trip.");
    const std::wstring rememberedAfterProviderSwitch = g_folderWindow.DebugLookupPaneFocusMemoryEntryForSelfTest(FolderWindow::Pane::Left, folderA);
    state.Require(OrdinalString::EqualsNoCase(rememberedAfterProviderSwitch, L"two.txt"),
                  std::format(L"Folder A focus-memory entry was unavailable after provider round-trip; remembered='{}', context='{}'.",
                              rememberedAfterProviderSwitch,
                              g_folderWindow.GetFileSystemInstanceContext(FolderWindow::Pane::Left)));
    navigate(folderA, 2u, L"folder A provider return");
    state.Require(WaitForFolderViewFocusedItem(FolderWindow::Pane::Left, L"two.txt", SelfTest::Scale(3000ms)),
                  L"Folder A current item was not restored across the provider round-trip.");
    snapshot = g_folderWindow.DebugGetFocusSelectionStateSnapshot(FolderWindow::Pane::Left);
    state.Require(snapshot.resolutionReason == FolderView::CurrentResolutionReason::NavigationMemoryRestore && snapshot.selectedCount == 0u,
                  L"Provider round-trip did not restore current-only state from focus memory.");

    return state.failure.empty();
}

[[nodiscard]] bool TestFolderViewSelectionInputContract(HWND mainWindow, CaseState& state) noexcept
{
    using namespace std::chrono_literals;

    if (! mainWindow || IsWindow(mainWindow) == FALSE || ! PrepareMainWindowForIsolatedUiCase(mainWindow, state, L"FolderView selection input contract"))
    {
        state.Require(false, L"Main window is unavailable for FolderView selection input contract.");
        return false;
    }

    const std::filesystem::path root = SelfTest::GetTempRoot(SelfTest::SelfTestSuite::Commands) / L"work" / (L"folderview_selection_input_" + NewGuidText());
    std::error_code cleanupError;
    std::filesystem::remove_all(root, cleanupError);
    state.Require(SelfTest::EnsureDirectory(root), L"Failed to create FolderView selection-input fixture root.");
    for (const std::wstring_view name : {L"a.txt", L"b.txt", L"c.txt", L"d.txt"})
    {
        state.Require(SelfTest::WriteTextFile(root / name, "x"), std::format(L"Failed to create '{}'.", name));
    }
    if (! state.failure.empty())
    {
        return false;
    }
    const auto cleanupRoot = wil::scope_exit([&]() noexcept
    {
        std::error_code error;
        std::filesystem::remove_all(root, error);
    });

    const std::wstring pluginBefore                       = std::wstring(g_folderWindow.GetFileSystemPluginId(FolderWindow::Pane::Left));
    const std::optional<std::filesystem::path> pathBefore = g_folderWindow.GetCurrentPath(FolderWindow::Pane::Left);
    const FolderView::SortBy sortBefore                   = g_folderWindow.GetSortBy(FolderWindow::Pane::Left);
    const FolderView::SortDirection directionBefore       = g_folderWindow.GetSortDirection(FolderWindow::Pane::Left);
    const auto restorePane                                = wil::scope_exit([&]() noexcept
    {
        static_cast<void>(g_folderWindow.SetFileSystemPluginForPane(FolderWindow::Pane::Left, pluginBefore));
        g_folderWindow.SetSort(FolderWindow::Pane::Left, sortBefore, directionBefore);
        if (pathBefore.has_value())
        {
            g_folderWindow.SetFolderPath(FolderWindow::Pane::Left, pathBefore.value());
        }
    });

    g_folderWindow.DebugResetPaneVisibilityState(FolderWindow::Pane::Left);
    state.Require(SUCCEEDED(g_folderWindow.SetFileSystemPluginForPane(FolderWindow::Pane::Left, L"builtin/file-system")),
                  L"Failed to switch to local provider for FolderView selection-input contract.");
    g_folderWindow.SetSort(FolderWindow::Pane::Left, FolderView::SortBy::Name, FolderView::SortDirection::Ascending);
    std::atomic<uint32_t> enumerationCount{0u};
    g_folderWindow.SetPaneEnumerationCompletedCallback(FolderWindow::Pane::Left,
                                                       [&](const std::filesystem::path& folder) noexcept
    {
        if (OrdinalString::EqualsNoCasePath(folder, root))
        {
            enumerationCount.fetch_add(1u, std::memory_order_release);
        }
    });
    const auto clearEnumerationCallback = wil::scope_exit([&]() noexcept { g_folderWindow.SetPaneEnumerationCompletedCallback(FolderWindow::Pane::Left, {}); });
    g_folderWindow.SetFolderPath(FolderWindow::Pane::Left, root);
    state.Require(WaitForPanePath(FolderWindow::Pane::Left, root, SelfTest::Scale(5000ms)), L"Selection-input path did not settle.");
    state.Require(WaitForAtomicAtLeast(enumerationCount, 1u, SelfTest::Scale(5000ms)), L"Selection-input enumeration did not complete.");
    state.Require(WaitForPaneItems(FolderWindow::Pane::Left, {L"a.txt", L"b.txt", L"c.txt", L"d.txt"}, SelfTest::Scale(5000ms)),
                  L"Selection-input items did not settle.");
    const HWND folderView = g_folderWindow.GetFolderViewHwnd(FolderWindow::Pane::Left);
    state.Require(folderView && IsWindow(folderView) != FALSE, L"Selection-input FolderView handle is unavailable.");
    if (! state.failure.empty())
    {
        return false;
    }

    const auto pointFor = [&](std::wstring_view name) noexcept
    {
        const std::optional<POINT> point = g_folderWindow.DebugGetPaneItemCenterClientPointForSelfTest(FolderWindow::Pane::Left, name);
        state.Require(point.has_value(), std::format(L"No pointer point for '{}'.", name));
        return point.value_or(POINT{});
    };
    const auto press = [&](std::wstring_view name, WPARAM modifiers, bool release = true) noexcept
    {
        const POINT point = pointFor(name);
        SendMessageW(folderView, WM_LBUTTONDOWN, MK_LBUTTON | modifiers, MAKELPARAM(point.x, point.y));
        const FolderView::DebugFocusSelectionStateSnapshot down = g_folderWindow.DebugGetFocusSelectionStateSnapshot(FolderWindow::Pane::Left);
        state.Require(OrdinalString::EqualsNoCase(down.currentDisplayName, name),
                      std::format(L"Left-button-down on '{}' did not establish current immediately.", name));
        if (release)
        {
            SendMessageW(folderView, WM_LBUTTONUP, modifiers, MAKELPARAM(point.x, point.y));
        }
        return down;
    };
    const auto selectNames = [&](std::initializer_list<std::wstring_view> names) noexcept
    {
        g_folderWindow.SetPaneSelectionByDisplayNamePredicate(FolderWindow::Pane::Left, [names](std::wstring_view candidate) noexcept {
            return std::ranges::any_of(names, [&](std::wstring_view name) noexcept { return candidate == name; });
        }, true);
    };
    struct ItemContextMenuObservation final
    {
        bool opened       = false;
        bool shapeCorrect = false;
    };
    const auto openAndDismissPointerMenu = [&](std::wstring_view name) noexcept
    {
        POINT screenPoint = pointFor(name);
        ClientToScreen(folderView, &screenPoint);
        const DWORD uiThreadId = GetWindowThreadProcessId(folderView, nullptr);
        std::atomic<bool> opened{false};
        std::atomic<bool> shapeCorrect{false};
        std::jthread closer([&](std::stop_token stopToken) noexcept
        {
            const auto deadline = std::chrono::steady_clock::now() + SelfTest::Scale(3000ms);
            while (! stopToken.stop_requested() && std::chrono::steady_clock::now() < deadline)
            {
                GUITHREADINFO info{};
                info.cbSize       = sizeof(info);
                const bool inMenu = GetGUIThreadInfo(uiThreadId, &info) != FALSE && (info.flags & GUI_INMENUMODE) != 0;
                const HWND popup  = FindVisibleOwnedDxUiContextMenuWindow(folderView);
                if (inMenu || popup)
                {
                    opened.store(true, std::memory_order_release);
                    DxUi::ContextMenuPopupDebugState popupState{};
                    if (popup && DxUi::DebugGetContextMenuPopupState(popup, popupState))
                    {
                        const auto cut               = std::ranges::find(popupState.itemTexts, L"Cut");
                        const auto properties        = std::ranges::find(popupState.itemTexts, L"Properties");
                        const size_t cutIndex        = static_cast<size_t>(std::distance(popupState.itemTexts.begin(), cut));
                        const size_t propertiesIndex = static_cast<size_t>(std::distance(popupState.itemTexts.begin(), properties));
                        const bool propertiesIsFinalNormalAction =
                            properties != popupState.itemTexts.end() &&
                            (propertiesIndex + 1u == popupState.itemTexts.size() ||
                             (propertiesIndex + 2u < popupState.itemTexts.size() && propertiesIndex + 1u < popupState.itemKinds.size() &&
                              popupState.itemKinds[propertiesIndex + 1u] == DxUi::MenuItemKind::Separator &&
                              popupState.itemTexts[propertiesIndex + 2u].find(L"[dbg]") != std::wstring::npos));
                        shapeCorrect.store(cut != popupState.itemTexts.end() && cutIndex < popupState.itemEnabled.size() && popupState.itemEnabled[cutIndex] &&
                                               propertiesIsFinalNormalAction,
                                           std::memory_order_release);
                    }
                    const HWND target = popup ? popup : (info.hwndMenuOwner ? info.hwndMenuOwner : folderView);
                    PostMessageW(target, WM_KEYDOWN, VK_ESCAPE, 0);
                    PostMessageW(target, WM_KEYUP, VK_ESCAPE, 0);
                    return;
                }
                std::this_thread::sleep_for(10ms);
            }
        });
        SendMessageW(folderView, WM_CONTEXTMENU, reinterpret_cast<WPARAM>(folderView), MAKELPARAM(screenPoint.x, screenPoint.y));
        return ItemContextMenuObservation{
            .opened       = opened.load(std::memory_order_acquire),
            .shapeCorrect = shapeCorrect.load(std::memory_order_acquire),
        };
    };

    state.Require(g_folderWindow.DebugFocusItemByDisplayName(FolderWindow::Pane::Left, L"a.txt"), L"Failed to establish initial current item.");
    press(L"c.txt", 0u);
    state.Require(g_folderWindow.DebugGetSelectedCount(FolderWindow::Pane::Left) == 1u &&
                      g_folderWindow.DebugIsItemSelected(FolderWindow::Pane::Left, L"c.txt"),
                  L"Plain press on an unselected item did not replace selection.");

    selectNames({L"a.txt", L"c.txt"});
    state.Require(g_folderWindow.DebugFocusItemByDisplayName(FolderWindow::Pane::Left, L"a.txt"), L"Failed to reset current before selected-item press.");
    selectNames({L"a.txt", L"c.txt"});
    press(L"c.txt", 0u);
    state.Require(g_folderWindow.DebugGetSelectedCount(FolderWindow::Pane::Left) == 2u,
                  L"Plain press on an already-selected item did not preserve multi-selection.");

    press(L"b.txt", MK_CONTROL);
    state.Require(g_folderWindow.DebugGetSelectedCount(FolderWindow::Pane::Left) == 3u &&
                      g_folderWindow.DebugIsItemSelected(FolderWindow::Pane::Left, L"b.txt"),
                  L"Ctrl+Click did not add only the clicked item.");
    const FolderView::DebugFocusSelectionStateSnapshot ctrlOff = press(L"b.txt", MK_CONTROL, false);
    state.Require(ctrlOff.selectedCount == 2u && ctrlOff.potentialDragSourceCount == 0u, L"Ctrl+Click deselection armed a drag from the leftover selection.");
    SendMessageW(folderView, WM_LBUTTONUP, MK_CONTROL, MAKELPARAM(pointFor(L"b.txt").x, pointFor(L"b.txt").y));

    state.Require(g_folderWindow.DebugFocusItemByDisplayName(FolderWindow::Pane::Left, L"b.txt"), L"Failed to establish no-anchor Shift fixture current.");
    g_folderWindow.DebugClearPaneSelectionAnchorForSelfTest(FolderWindow::Pane::Left);
    press(L"d.txt", MK_SHIFT);
    state.Require(
        g_folderWindow.DebugGetSelectedCount(FolderWindow::Pane::Left) == 3u && g_folderWindow.DebugIsItemSelected(FolderWindow::Pane::Left, L"b.txt") &&
            g_folderWindow.DebugIsItemSelected(FolderWindow::Pane::Left, L"c.txt") && g_folderWindow.DebugIsItemSelected(FolderWindow::Pane::Left, L"d.txt"),
        L"No-anchor Shift+Click did not include pre-press current through clicked endpoint.");

    state.Require(g_folderWindow.DebugFocusItemByDisplayName(FolderWindow::Pane::Left, L"b.txt"), L"Failed to establish additive range current.");
    selectNames({L"a.txt"});
    g_folderWindow.DebugClearPaneSelectionAnchorForSelfTest(FolderWindow::Pane::Left);
    press(L"d.txt", MK_CONTROL | MK_SHIFT);
    state.Require(g_folderWindow.DebugGetSelectedCount(FolderWindow::Pane::Left) == 4u,
                  L"No-anchor Ctrl+Shift+Click did not add the inclusive pre-press-current range.");

    state.Require(g_folderWindow.DebugFocusItemByDisplayName(FolderWindow::Pane::Left, L"a.txt"), L"Failed to establish pointer right-click fixture current.");
    selectNames({L"a.txt", L"c.txt"});
    const ItemContextMenuObservation unselectedItemMenu = openAndDismissPointerMenu(L"b.txt");
    state.Require(unselectedItemMenu.opened, L"Pointer menu on an unselected item did not open.");
    state.Require(unselectedItemMenu.shapeCorrect, L"Local item context menu should enable Cut and keep Properties as the final normal action.");
    FolderView::DebugFocusSelectionStateSnapshot snapshot = g_folderWindow.DebugGetFocusSelectionStateSnapshot(FolderWindow::Pane::Left);
    state.Require(snapshot.currentDisplayName == L"b.txt" && snapshot.selectedCount == 1u &&
                      g_folderWindow.DebugIsItemSelected(FolderWindow::Pane::Left, L"b.txt"),
                  L"Right-click on an unselected item did not establish it as the sole item target.");
    selectNames({L"a.txt", L"c.txt"});
    const ItemContextMenuObservation selectedItemMenu = openAndDismissPointerMenu(L"c.txt");
    state.Require(selectedItemMenu.opened, L"Pointer menu on a selected item did not open.");
    state.Require(selectedItemMenu.shapeCorrect, L"Selected-set item context menu should enable Cut and keep Properties as the final normal action.");
    snapshot = g_folderWindow.DebugGetFocusSelectionStateSnapshot(FolderWindow::Pane::Left);
    state.Require(snapshot.currentDisplayName == L"c.txt" && snapshot.selectedCount == 2u &&
                      g_folderWindow.DebugIsItemSelected(FolderWindow::Pane::Left, L"a.txt") &&
                      g_folderWindow.DebugIsItemSelected(FolderWindow::Pane::Left, L"c.txt"),
                  L"Right-click on a selected item did not preserve the selected set while moving current.");

    state.Require(g_folderWindow.DebugFocusItemByDisplayName(FolderWindow::Pane::Left, L"b.txt"),
                  L"Failed to establish ordinary keyboard-move fixture current.");
    selectNames({L"a.txt", L"d.txt"});
    const uint64_t keyboardMoveSelectionDigest = g_folderWindow.DebugGetFocusSelectionStateSnapshot(FolderWindow::Pane::Left).selectionDigest;
    g_folderWindow.DebugSendPaneKeyForSelfTest(FolderWindow::Pane::Left, VK_DOWN, false, false);
    snapshot = g_folderWindow.DebugGetFocusSelectionStateSnapshot(FolderWindow::Pane::Left);
    state.Require(snapshot.currentDisplayName == L"c.txt" && snapshot.selectedCount == 2u && snapshot.selectionDigest == keyboardMoveSelectionDigest,
                  L"Ordinary keyboard navigation changed selection while moving current.");

    state.Require(g_folderWindow.DebugFocusItemByDisplayName(FolderWindow::Pane::Left, L"b.txt"),
                  L"Failed to establish no-anchor Shift+keyboard fixture current.");
    selectNames({L"a.txt"});
    g_folderWindow.DebugClearPaneSelectionAnchorForSelfTest(FolderWindow::Pane::Left);
    g_folderWindow.DebugSendPaneKeyForSelfTest(FolderWindow::Pane::Left, VK_DOWN, false, true);
    snapshot = g_folderWindow.DebugGetFocusSelectionStateSnapshot(FolderWindow::Pane::Left);
    state.Require(snapshot.currentDisplayName == L"c.txt" && snapshot.selectedCount == 2u &&
                      g_folderWindow.DebugIsItemSelected(FolderWindow::Pane::Left, L"b.txt") &&
                      g_folderWindow.DebugIsItemSelected(FolderWindow::Pane::Left, L"c.txt"),
                  L"No-anchor Shift+keyboard did not replace selection with the inclusive pre-move-current range.");

    state.Require(g_folderWindow.DebugFocusItemByDisplayName(FolderWindow::Pane::Left, L"b.txt"),
                  L"Failed to establish no-anchor Ctrl+Shift+keyboard fixture current.");
    selectNames({L"a.txt"});
    g_folderWindow.DebugClearPaneSelectionAnchorForSelfTest(FolderWindow::Pane::Left);
    g_folderWindow.DebugSendPaneKeyForSelfTest(FolderWindow::Pane::Left, VK_END, true, true);
    snapshot = g_folderWindow.DebugGetFocusSelectionStateSnapshot(FolderWindow::Pane::Left);
    state.Require(snapshot.currentDisplayName == L"d.txt" && snapshot.selectedCount == 4u,
                  L"No-anchor Ctrl+Shift+End did not add the inclusive pre-move-current range.");

    state.Require(g_folderWindow.DebugFocusItemByDisplayName(FolderWindow::Pane::Left, L"c.txt"), L"Failed to establish Home/End fixture current.");
    selectNames({L"a.txt", L"d.txt"});
    const uint64_t homeEndSelectionDigest = g_folderWindow.DebugGetFocusSelectionStateSnapshot(FolderWindow::Pane::Left).selectionDigest;
    g_folderWindow.DebugSendPaneKeyForSelfTest(FolderWindow::Pane::Left, VK_HOME, false, false);
    g_folderWindow.DebugSendPaneKeyForSelfTest(FolderWindow::Pane::Left, VK_END, false, false);
    snapshot = g_folderWindow.DebugGetFocusSelectionStateSnapshot(FolderWindow::Pane::Left);
    state.Require(snapshot.currentDisplayName == L"d.txt" && snapshot.selectionDigest == homeEndSelectionDigest,
                  L"Home/End navigation did not preserve selection while moving current.");

    SendMessageW(mainWindow, WM_COMMAND, MAKEWPARAM(IDM_PANE_SELECTION_SELECT_ALL, 0), 0);
    state.Require(g_folderWindow.DebugGetSelectedCount(FolderWindow::Pane::Left) == 4u, L"Ctrl+A command routing did not select the complete displayed set.");
    g_folderWindow.CommandSelectionInvert(FolderWindow::Pane::Left);
    state.Require(g_folderWindow.DebugGetSelectedCount(FolderWindow::Pane::Left) == 0u, L"Invert Selection did not mutate the concrete displayed set.");
    state.Require(g_folderWindow.DebugFocusItemByDisplayName(FolderWindow::Pane::Left, L"a.txt"), L"Failed to establish extension-mask fixture current.");
    g_folderWindow.CommandSelectionSelectSameExtension(FolderWindow::Pane::Left);
    state.Require(g_folderWindow.DebugGetSelectedCount(FolderWindow::Pane::Left) == 4u, L"Select Same Extension did not add every displayed .txt identity.");
    g_folderWindow.CommandSelectionUnselectSameExtension(FolderWindow::Pane::Left);
    state.Require(g_folderWindow.DebugGetSelectedCount(FolderWindow::Pane::Left) == 0u,
                  L"Unselect Same Extension did not remove every displayed .txt identity.");

    state.Require(g_folderWindow.DebugFocusItemByDisplayName(FolderWindow::Pane::Left, L"b.txt"),
                  L"Failed to establish selected-name navigation fixture current.");
    selectNames({L"a.txt", L"c.txt"});
    const FolderView::DebugFocusSelectionStateSnapshot selectedNameBefore = g_folderWindow.DebugGetFocusSelectionStateSnapshot(FolderWindow::Pane::Left);
    g_folderWindow.CommandSelectionGoToNextSelectedName(FolderWindow::Pane::Left);
    snapshot = g_folderWindow.DebugGetFocusSelectionStateSnapshot(FolderWindow::Pane::Left);
    state.Require(snapshot.currentDisplayName == L"c.txt" && snapshot.selectedCount == 2u && snapshot.anchorIndex == snapshot.currentIndex &&
                      snapshot.focusOwnershipEpoch > selectedNameBefore.focusOwnershipEpoch,
                  L"Alt+Down selected-name navigation did not preserve selection and establish destination current/anchor ownership.");
    g_folderWindow.CommandSelectionGoToNextSelectedName(FolderWindow::Pane::Left);
    state.Require(g_folderWindow.DebugGetFocusedItemDisplayName(FolderWindow::Pane::Left) == L"a.txt",
                  L"Alt+Down selected-name navigation did not wrap within selected identities.");
    g_folderWindow.CommandSelectionGoToPreviousSelectedName(FolderWindow::Pane::Left);
    state.Require(g_folderWindow.DebugGetFocusedItemDisplayName(FolderWindow::Pane::Left) == L"c.txt" &&
                      g_folderWindow.DebugGetSelectedCount(FolderWindow::Pane::Left) == 2u,
                  L"Alt+Up selected-name navigation did not wrap while preserving selection.");

    state.Require(g_folderWindow.DebugFocusItemByDisplayName(FolderWindow::Pane::Left, L"a.txt"), L"Failed to establish Space fixture current.");
    const FolderWindow::DebugSelectionSizeSnapshot unselectedSpaceSizeBefore = g_folderWindow.DebugGetSelectionSizeSnapshot(FolderWindow::Pane::Left);
    SendMessageW(folderView, WM_KEYDOWN, VK_SPACE, 0);
    SendMessageW(folderView, WM_KEYUP, VK_SPACE, 0);
    snapshot                                               = g_folderWindow.DebugGetFocusSelectionStateSnapshot(FolderWindow::Pane::Left);
    FolderWindow::DebugSelectionSizeSnapshot selectionSize = g_folderWindow.DebugGetSelectionSizeSnapshot(FolderWindow::Pane::Left);
    state.Require(snapshot.currentDisplayName == L"b.txt" && snapshot.selectedCount == 1u &&
                      g_folderWindow.DebugIsItemSelected(FolderWindow::Pane::Left, L"a.txt") &&
                      ! g_folderWindow.DebugIsItemSelected(FolderWindow::Pane::Left, L"b.txt") && snapshot.anchorIndex == snapshot.currentIndex &&
                      snapshot.selectedFileCount == 1u && snapshot.selectedFileBytes == 1u,
                  L"Space did not select the operated unselected current, request its post-toggle set, then advance without selecting destination.");
    state.Require(selectionSize.requestCount == unselectedSpaceSizeBefore.requestCount + 1u && selectionSize.lastRequestedSelectedPaths.size() == 1u &&
                      selectionSize.lastRequestedSelectedPaths.front().filename() == L"a.txt",
                  L"Space did not submit the complete post-toggle selection-size snapshot for the operated unselected current item.");

    state.Require(g_folderWindow.DebugFocusItemByDisplayName(FolderWindow::Pane::Left, L"b.txt"), L"Failed to establish selected-current Space fixture.");
    selectNames({L"b.txt"});
    const FolderWindow::DebugSelectionSizeSnapshot selectedSpaceSizeBefore = g_folderWindow.DebugGetSelectionSizeSnapshot(FolderWindow::Pane::Left);
    SendMessageW(folderView, WM_KEYDOWN, VK_SPACE, 0);
    SendMessageW(folderView, WM_KEYUP, VK_SPACE, 0);
    snapshot      = g_folderWindow.DebugGetFocusSelectionStateSnapshot(FolderWindow::Pane::Left);
    selectionSize = g_folderWindow.DebugGetSelectionSizeSnapshot(FolderWindow::Pane::Left);
    state.Require(snapshot.currentDisplayName == L"c.txt" && snapshot.selectedCount == 0u && snapshot.anchorIndex == snapshot.currentIndex,
                  L"Space did not deselect the operated selected current and advance without wrap/implicit destination selection.");
    state.Require(selectionSize.requestCount == selectedSpaceSizeBefore.requestCount + 1u && selectionSize.lastRequestedSelectedPaths.empty() &&
                      ! selectionSize.folderBytesPending && ! selectionSize.folderBytesValid && selectionSize.folderBytes == 0u,
                  L"Space deselection did not cancel size work and submit the empty post-toggle selected set.");

    state.Require(g_folderWindow.DebugFocusItemByDisplayName(FolderWindow::Pane::Left, L"d.txt"), L"Failed to establish last-row Space fixture.");
    SendMessageW(folderView, WM_KEYDOWN, VK_SPACE, 0);
    SendMessageW(folderView, WM_KEYUP, VK_SPACE, 0);
    snapshot = g_folderWindow.DebugGetFocusSelectionStateSnapshot(FolderWindow::Pane::Left);
    state.Require(snapshot.currentDisplayName == L"d.txt" && g_folderWindow.DebugIsItemSelected(FolderWindow::Pane::Left, L"d.txt"),
                  L"Space wrapped or failed to toggle at the last row.");

    state.Require(g_folderWindow.DebugFocusItemByDisplayName(FolderWindow::Pane::Left, L"a.txt"), L"Failed to establish Insert fixture current.");
    const uint64_t insertSizeRequestsBefore = g_folderWindow.DebugGetSelectionSizeSnapshot(FolderWindow::Pane::Left).requestCount;
    SendMessageW(folderView, WM_KEYDOWN, VK_INSERT, 0);
    SendMessageW(folderView, WM_KEYUP, VK_INSERT, 0);
    snapshot = g_folderWindow.DebugGetFocusSelectionStateSnapshot(FolderWindow::Pane::Left);
    state.Require(snapshot.currentDisplayName == L"b.txt" && g_folderWindow.DebugIsItemSelected(FolderWindow::Pane::Left, L"a.txt") &&
                      ! g_folderWindow.DebugIsItemSelected(FolderWindow::Pane::Left, L"b.txt"),
                  L"Insert did not toggle operated current and advance without selecting destination.");
    state.Require(g_folderWindow.DebugGetSelectionSizeSnapshot(FolderWindow::Pane::Left).requestCount == insertSizeRequestsBefore,
                  L"Insert incorrectly requested explicit selection-size computation.");
    SendMessageW(folderView, WM_KEYDOWN, VK_ESCAPE, 0);
    SendMessageW(folderView, WM_KEYUP, VK_ESCAPE, 0);
    snapshot = g_folderWindow.DebugGetFocusSelectionStateSnapshot(FolderWindow::Pane::Left);
    state.Require(snapshot.selectedCount == 0u && snapshot.currentDisplayName == L"b.txt" && snapshot.anchorIndex == snapshot.currentIndex,
                  L"Escape did not clear selection while retaining current and resetting the anchor.");

    return state.failure.empty();
}

[[nodiscard]] bool TestFolderViewEmptyBackgroundKeepsCurrent(HWND mainWindow, CaseState& state) noexcept
{
    using namespace std::chrono_literals;

    if (! mainWindow || IsWindow(mainWindow) == FALSE ||
        ! PrepareMainWindowForIsolatedUiCase(mainWindow, state, L"FolderView empty-background current contract"))
    {
        state.Require(false, L"Main window is unavailable for FolderView empty-background contract.");
        return false;
    }

    const std::filesystem::path root = SelfTest::GetTempRoot(SelfTest::SelfTestSuite::Commands) / L"work" / (L"folderview_empty_background_" + NewGuidText());
    const std::filesystem::path emptyRoot = root / L"empty";
    std::error_code cleanupError;
    std::filesystem::remove_all(root, cleanupError);
    state.Require(SelfTest::EnsureDirectory(root), L"Failed to create empty-background fixture root.");
    for (const std::wstring_view name : {L"a.txt", L"b.txt", L"c.txt"})
    {
        state.Require(SelfTest::WriteTextFile(root / name, "x"), std::format(L"Failed to create '{}'.", name));
    }
    if (! state.failure.empty())
    {
        return false;
    }
    const auto cleanupRoot = wil::scope_exit([&]() noexcept
    {
        std::error_code error;
        std::filesystem::remove_all(root, error);
    });

    const std::wstring pluginBefore                       = std::wstring(g_folderWindow.GetFileSystemPluginId(FolderWindow::Pane::Left));
    const std::optional<std::filesystem::path> pathBefore = g_folderWindow.GetCurrentPath(FolderWindow::Pane::Left);
    const auto restorePane                                = wil::scope_exit([&]() noexcept
    {
        g_folderWindow.DebugSetPaneSuppressOleDragDropForSelfTest(FolderWindow::Pane::Left, false);
        static_cast<void>(g_folderWindow.SetFileSystemPluginForPane(FolderWindow::Pane::Left, pluginBefore));
        if (pathBefore.has_value())
        {
            g_folderWindow.SetFolderPath(FolderWindow::Pane::Left, pathBefore.value());
        }
    });

    g_folderWindow.DebugResetPaneVisibilityState(FolderWindow::Pane::Left);
    state.Require(SUCCEEDED(g_folderWindow.SetFileSystemPluginForPane(FolderWindow::Pane::Left, L"builtin/file-system")),
                  L"Failed to switch to local provider for empty-background contract.");
    g_folderWindow.SetSort(FolderWindow::Pane::Left, FolderView::SortBy::Name, FolderView::SortDirection::Ascending);
    std::atomic<uint32_t> enumerationCount{0u};
    g_folderWindow.SetPaneEnumerationCompletedCallback(FolderWindow::Pane::Left,
                                                       [&](const std::filesystem::path& folder) noexcept
    {
        if (OrdinalString::EqualsNoCasePath(folder, root))
        {
            enumerationCount.fetch_add(1u, std::memory_order_release);
        }
    });
    const auto clearEnumerationCallback = wil::scope_exit([&]() noexcept { g_folderWindow.SetPaneEnumerationCompletedCallback(FolderWindow::Pane::Left, {}); });
    g_folderWindow.SetFolderPath(FolderWindow::Pane::Left, root);
    state.Require(WaitForPanePath(FolderWindow::Pane::Left, root, SelfTest::Scale(5000ms)), L"Empty-background path did not settle.");
    state.Require(WaitForAtomicAtLeast(enumerationCount, 1u, SelfTest::Scale(5000ms)), L"Empty-background enumeration did not complete.");
    state.Require(WaitForPaneItems(FolderWindow::Pane::Left, {L"a.txt", L"b.txt", L"c.txt"}, SelfTest::Scale(5000ms)),
                  L"Empty-background items did not settle.");
    const HWND folderView                      = g_folderWindow.GetFolderViewHwnd(FolderWindow::Pane::Left);
    const std::optional<POINT> backgroundPoint = g_folderWindow.DebugGetPaneEmptyBackgroundClientPointForSelfTest(FolderWindow::Pane::Left);
    state.Require(folderView && IsWindow(folderView) != FALSE && backgroundPoint.has_value(), L"Empty-background pointer target is unavailable.");
    if (! state.failure.empty())
    {
        return false;
    }

    g_folderWindow.DebugSetPaneSuppressOleDragDropForSelfTest(FolderWindow::Pane::Left, true);
    const auto establishFixture = [&]() noexcept
    {
        state.Require(g_folderWindow.DebugFocusItemByDisplayName(FolderWindow::Pane::Left, L"b.txt"), L"Failed to establish empty-background current item.");
        g_folderWindow.SetPaneSelectionByDisplayNamePredicate(
            FolderWindow::Pane::Left, [](std::wstring_view name) noexcept { return name == L"a.txt" || name == L"c.txt"; }, true);
        return g_folderWindow.DebugGetFocusSelectionStateSnapshot(FolderWindow::Pane::Left);
    };

    for (const WPARAM modifiers : std::array<WPARAM, 4u>{{0u, MK_CONTROL, MK_SHIFT, MK_CONTROL | MK_SHIFT}})
    {
        const FolderView::DebugFocusSelectionStateSnapshot before = establishFixture();
        SendMessageW(folderView, WM_LBUTTONDOWN, MK_LBUTTON | modifiers, MAKELPARAM(backgroundPoint->x, backgroundPoint->y));
        SendMessageW(folderView, WM_LBUTTONUP, modifiers, MAKELPARAM(backgroundPoint->x, backgroundPoint->y));
        const FolderView::DebugFocusSelectionStateSnapshot after = g_folderWindow.DebugGetFocusSelectionStateSnapshot(FolderWindow::Pane::Left);
        state.Require(after.currentDisplayName == L"b.txt" && after.currentIndex < after.itemCount && after.focusedFlagCount == 1u,
                      L"Modified empty-background press removed or duplicated current.");
        state.Require(after.selectedCount == 0u && after.anchorIndex == after.currentIndex && after.potentialDragSourceCount == 0u,
                      L"Modified empty-background press did not clear selection/drag and reset anchor to current.");
        state.Require(after.focusOwnershipEpoch == before.focusOwnershipEpoch, L"Modified empty-background press changed the current-ownership epoch.");
    }

    const uint64_t dragStartBefore = g_folderWindow.DebugGetPaneDragStartCountForSelfTest(FolderWindow::Pane::Left);
    const POINT farPoint{backgroundPoint->x + 100, backgroundPoint->y + 100};
    SendMessageW(folderView, WM_MOUSEMOVE, MK_LBUTTON, MAKELPARAM(farPoint.x, farPoint.y));
    state.Require(g_folderWindow.DebugGetPaneDragStartCountForSelfTest(FolderWindow::Pane::Left) == dragStartBefore,
                  L"Movement after an empty-background press promoted retained current into a drag source.");

    struct PointerContextMenuObservation final
    {
        bool opened                 = false;
        bool backgroundShapeCorrect = false;
    };
    const auto runPointerContextMenu = [&](POINT clientPoint) noexcept
    {
        POINT screenPoint = clientPoint;
        ClientToScreen(folderView, &screenPoint);
        std::atomic<bool> opened{false};
        std::atomic<bool> backgroundShapeCorrect{false};
        std::jthread closer([&](std::stop_token stopToken) noexcept
        {
            const auto deadline = std::chrono::steady_clock::now() + SelfTest::Scale(3000ms);
            while (! stopToken.stop_requested() && std::chrono::steady_clock::now() < deadline)
            {
                const HWND popup = FindVisibleOwnedDxUiContextMenuWindow(folderView);
                DxUi::ContextMenuPopupDebugState popupState{};
                if (popup && IsWindow(popup) != FALSE && DxUi::DebugGetContextMenuPopupState(popup, popupState))
                {
                    opened.store(true, std::memory_order_release);
                    const auto containsText = [&](std::wstring_view expected) noexcept
                    { return std::ranges::find(popupState.itemTexts, expected) != popupState.itemTexts.end(); };
                    backgroundShapeCorrect.store(popupState.itemTexts.size() >= 5u && popupState.itemTexts[0] == L"Paste" &&
                                                     popupState.itemTexts[1] == L"New" && containsText(L"Refresh") &&
                                                     containsText(L"Calculate Occupied Space") && ! containsText(L"Open") && ! containsText(L"Delete...") &&
                                                     ! containsText(L"Properties"),
                                                 std::memory_order_release);

                    PostMessageW(popup, WM_KEYDOWN, VK_ESCAPE, 0);
                    PostMessageW(popup, WM_KEYUP, VK_ESCAPE, 0);
                    return;
                }
                std::this_thread::sleep_for(10ms);
            }
        });
        SendMessageW(folderView, WM_CONTEXTMENU, reinterpret_cast<WPARAM>(folderView), MAKELPARAM(screenPoint.x, screenPoint.y));
        return PointerContextMenuObservation{
            .opened                 = opened.load(std::memory_order_acquire),
            .backgroundShapeCorrect = backgroundShapeCorrect.load(std::memory_order_acquire),
        };
    };

    FolderView::DebugFocusSelectionStateSnapshot before = establishFixture();
    const PointerContextMenuObservation pointerMenu     = runPointerContextMenu(backgroundPoint.value());
    state.Require(pointerMenu.opened, L"Pointer background context menu did not open.");
    state.Require(pointerMenu.backgroundShapeCorrect,
                  L"Background context menu should expose Paste, New, Refresh, and Calculate Occupied Space without item actions.");
    FolderView::DebugFocusSelectionStateSnapshot after = g_folderWindow.DebugGetFocusSelectionStateSnapshot(FolderWindow::Pane::Left);
    state.Require(after.currentDisplayName == L"b.txt" && after.selectedCount == 0u && after.anchorIndex == after.currentIndex &&
                      after.focusOwnershipEpoch == before.focusOwnershipEpoch,
                  L"Pointer background context route did not clear selection while retaining current and ownership.");

    before                 = establishFixture();
    const DWORD uiThreadId = GetWindowThreadProcessId(folderView, nullptr);
    const UiMenuRoundTripResult keyboardMenu =
        TriggerAndDismissKeyboardActivatedUiMenu(folderView, VK_APPS, uiThreadId, folderView, SelfTest::Scale(3000ms), SelfTest::Scale(3000ms));
    state.Require(keyboardMenu.opened && keyboardMenu.closed, L"Keyboard FolderView context menu did not complete its round-trip.");
    after = g_folderWindow.DebugGetFocusSelectionStateSnapshot(FolderWindow::Pane::Left);
    state.Require(after.currentDisplayName == L"b.txt" && after.selectedCount == 2u && after.selectionDigest == before.selectionDigest &&
                      after.focusOwnershipEpoch == before.focusOwnershipEpoch,
                  L"Keyboard context menu behaved like a synthetic pointer miss.");

    before = establishFixture();
    SendMessageW(folderView, WM_LBUTTONDOWN, MK_LBUTTON, MAKELPARAM(backgroundPoint->x, backgroundPoint->y));
    SendMessageW(folderView, WM_LBUTTONUP, 0, MAKELPARAM(backgroundPoint->x, backgroundPoint->y));
    after = g_folderWindow.DebugGetFocusSelectionStateSnapshot(FolderWindow::Pane::Left);
    state.Require(after.currentDisplayName == L"b.txt" && after.selectedCount == 0u && after.focusOwnershipEpoch == before.focusOwnershipEpoch,
                  L"Removal-focus E2E fixture did not retain current ownership after the background miss.");

    std::atomic<uint32_t> completedDeletes{0u};
    std::atomic<HRESULT> lastDeleteResult{E_PENDING};
    const uint64_t completionToken      = g_folderWindow.AddFileOperationCompletedCallback([&](const FolderWindow::FileOperationCompletedEvent& event) noexcept
    {
        if (event.operation == FILESYSTEM_DELETE && event.sourcePaths.size() == 1u && OrdinalString::EqualsNoCasePath(event.sourcePaths[0], root / L"b.txt"))
        {
            lastDeleteResult.store(event.hr, std::memory_order_release);
            completedDeletes.fetch_add(1u, std::memory_order_release);
        }
    });
    const auto removeCompletionCallback = wil::scope_exit([&]() noexcept { g_folderWindow.RemoveFileOperationCompletedCallback(completionToken); });

    const uint32_t enumerationBeforeDelete = enumerationCount.load(std::memory_order_acquire);
    FocusFolderViewPane(FolderWindow::Pane::Left);
    g_folderWindow.CommandDelete(FolderWindow::Pane::Left);
    const auto deleteDeadline = std::chrono::steady_clock::now() + SelfTest::Scale(8000ms);
    bool deleteRehomed        = false;
    while (std::chrono::steady_clock::now() < deleteDeadline)
    {
        PumpPendingMessages();
        std::error_code existsError;
        const bool removed                                                = ! std::filesystem::exists(root / L"b.txt", existsError) && ! existsError;
        const FolderView::DebugFocusSelectionStateSnapshot deleteSnapshot = g_folderWindow.DebugGetFocusSelectionStateSnapshot(FolderWindow::Pane::Left);
        if (completedDeletes.load(std::memory_order_acquire) >= 1u && lastDeleteResult.load(std::memory_order_acquire) == S_OK && removed &&
            enumerationCount.load(std::memory_order_acquire) > enumerationBeforeDelete && deleteSnapshot.itemCount == 2u &&
            deleteSnapshot.currentDisplayName == L"c.txt" && deleteSnapshot.selectedCount == 0u &&
            deleteSnapshot.resolutionReason == FolderView::CurrentResolutionReason::HostRemovalIntent)
        {
            deleteRehomed = true;
            break;
        }
        std::this_thread::sleep_for(10ms);
    }
    state.Require(deleteRehomed,
                  std::format(L"Background-clear Delete did not retain removal eligibility and rehome through host proof: completions={}, "
                              L"hr=0x{:08X}, enumerations={}, current='{}', selected={}, reason={}.",
                              completedDeletes.load(std::memory_order_acquire),
                              static_cast<unsigned long>(lastDeleteResult.load(std::memory_order_acquire)),
                              enumerationCount.load(std::memory_order_acquire),
                              g_folderWindow.DebugGetFocusedItemDisplayName(FolderWindow::Pane::Left),
                              g_folderWindow.DebugGetSelectedCount(FolderWindow::Pane::Left),
                              static_cast<unsigned>(g_folderWindow.DebugGetFocusSelectionStateSnapshot(FolderWindow::Pane::Left).resolutionReason)));

    state.Require(SelfTest::EnsureDirectory(emptyRoot), L"Failed to create empty-pane keyboard context fixture.");
    std::atomic<uint32_t> emptyEnumerationCount{0u};
    g_folderWindow.SetPaneEnumerationCompletedCallback(FolderWindow::Pane::Left,
                                                       [&](const std::filesystem::path& folder) noexcept
    {
        if (OrdinalString::EqualsNoCasePath(folder, emptyRoot))
        {
            emptyEnumerationCount.fetch_add(1u, std::memory_order_release);
        }
    });
    g_folderWindow.SetFolderPath(FolderWindow::Pane::Left, emptyRoot);
    state.Require(WaitForPanePath(FolderWindow::Pane::Left, emptyRoot, SelfTest::Scale(5000ms)), L"Empty-pane keyboard context path did not settle.");
    state.Require(WaitForAtomicAtLeast(emptyEnumerationCount, 1u, SelfTest::Scale(5000ms)), L"Empty-pane keyboard context enumeration did not complete.");
    state.Require(WaitForFolderViewItemCount(FolderWindow::Pane::Left, 0u, SelfTest::Scale(3000ms)),
                  L"Empty-pane keyboard context fixture should contain no items.");

    std::atomic<bool> emptyKeyboardMenuOpened{false};
    std::atomic<bool> emptyKeyboardMenuIsBackground{false};
    std::jthread emptyMenuCloser([&](std::stop_token stopToken) noexcept
    {
        const auto deadline = std::chrono::steady_clock::now() + SelfTest::Scale(3000ms);
        while (! stopToken.stop_requested() && std::chrono::steady_clock::now() < deadline)
        {
            const HWND popup = FindVisibleOwnedDxUiContextMenuWindow(folderView);
            DxUi::ContextMenuPopupDebugState popupState{};
            if (popup && IsWindow(popup) != FALSE && DxUi::DebugGetContextMenuPopupState(popup, popupState))
            {
                emptyKeyboardMenuOpened.store(true, std::memory_order_release);
                const auto containsText = [&](std::wstring_view expected) noexcept
                { return std::ranges::find(popupState.itemTexts, expected) != popupState.itemTexts.end(); };
                emptyKeyboardMenuIsBackground.store(containsText(L"Paste") && containsText(L"New") && containsText(L"Refresh") && ! containsText(L"Open") &&
                                                        ! containsText(L"Cut") && ! containsText(L"Delete...") && ! containsText(L"Properties"),
                                                    std::memory_order_release);
                PostMessageW(popup, WM_KEYDOWN, VK_ESCAPE, 0);
                PostMessageW(popup, WM_KEYUP, VK_ESCAPE, 0);
                return;
            }
            std::this_thread::sleep_for(10ms);
        }
    });
    FocusFolderViewPane(FolderWindow::Pane::Left);
    SendMessageW(folderView, WM_CONTEXTMENU, reinterpret_cast<WPARAM>(folderView), MAKELPARAM(static_cast<WORD>(-1), static_cast<WORD>(-1)));
    emptyMenuCloser.join();
    state.Require(emptyKeyboardMenuOpened.load(std::memory_order_acquire), L"Keyboard context menu did not open for an empty pane.");
    state.Require(emptyKeyboardMenuIsBackground.load(std::memory_order_acquire),
                  L"Shift+F10/VK_APPS on an empty pane must show the background menu and omit item-only actions.");

    const std::filesystem::path artifactRoot  = root / L"artifact";
    constexpr std::wstring_view kArtifactName = L"user.rs_tmp_0123456789abcdef0123456789abcdef_1";
    state.Require(SelfTest::EnsureDirectory(artifactRoot), L"Failed to create artifact-menu ordering fixture.");
    state.Require(SelfTest::WriteTextFile(artifactRoot / kArtifactName, "artifact"), L"Failed to create artifact-menu ordering item.");
    std::atomic<uint32_t> artifactEnumerationCount{0u};
    g_folderWindow.SetPaneEnumerationCompletedCallback(FolderWindow::Pane::Left,
                                                       [&](const std::filesystem::path& folder) noexcept
    {
        if (OrdinalString::EqualsNoCasePath(folder, artifactRoot))
        {
            artifactEnumerationCount.fetch_add(1u, std::memory_order_release);
        }
    });
    g_folderWindow.SetFolderPath(FolderWindow::Pane::Left, artifactRoot);
    state.Require(WaitForPanePath(FolderWindow::Pane::Left, artifactRoot, SelfTest::Scale(5000ms)), L"Artifact-menu ordering path did not settle.");
    state.Require(WaitForAtomicAtLeast(artifactEnumerationCount, 1u, SelfTest::Scale(5000ms)), L"Artifact-menu ordering enumeration did not complete.");
    state.Require(WaitForPaneItems(FolderWindow::Pane::Left, {kArtifactName}, SelfTest::Scale(5000ms)) &&
                      g_folderWindow.DebugFocusItemByDisplayName(FolderWindow::Pane::Left, kArtifactName),
                  L"Artifact-menu ordering item did not become current.");
    const std::optional<POINT> artifactPoint = g_folderWindow.DebugGetPaneItemCenterClientPointForSelfTest(FolderWindow::Pane::Left, kArtifactName);
    state.Require(artifactPoint.has_value(), L"Artifact-menu ordering pointer target is unavailable.");
    if (! state.failure.empty())
    {
        return false;
    }

    std::atomic<bool> artifactMenuOpened{false};
    std::atomic<bool> artifactBeforeProperties{false};
    std::jthread artifactMenuCloser([&](std::stop_token stopToken) noexcept
    {
        const auto deadline = std::chrono::steady_clock::now() + SelfTest::Scale(3000ms);
        while (! stopToken.stop_requested() && std::chrono::steady_clock::now() < deadline)
        {
            const HWND popup = FindVisibleOwnedDxUiContextMenuWindow(folderView);
            DxUi::ContextMenuPopupDebugState popupState{};
            if (popup && IsWindow(popup) != FALSE && DxUi::DebugGetContextMenuPopupState(popup, popupState))
            {
                artifactMenuOpened.store(true, std::memory_order_release);
                const auto artifact   = std::ranges::find(popupState.itemTexts, LoadStringResource(nullptr, IDS_FILEOPS_ARTIFACT_MENU_TITLE));
                const auto properties = std::ranges::find(popupState.itemTexts, L"Properties");
                if (artifact != popupState.itemTexts.end() && properties != popupState.itemTexts.end())
                {
                    const size_t artifactIndex   = static_cast<size_t>(std::distance(popupState.itemTexts.begin(), artifact));
                    const size_t propertiesIndex = static_cast<size_t>(std::distance(popupState.itemTexts.begin(), properties));
                    const bool propertiesIsFinalNormalAction =
                        propertiesIndex + 1u == popupState.itemTexts.size() ||
                        (propertiesIndex + 2u < popupState.itemTexts.size() && propertiesIndex + 1u < popupState.itemKinds.size() &&
                         popupState.itemKinds[propertiesIndex + 1u] == DxUi::MenuItemKind::Separator &&
                         popupState.itemTexts[propertiesIndex + 2u].find(L"[dbg]") != std::wstring::npos);
                    artifactBeforeProperties.store(propertiesIndex == artifactIndex + 2u && artifactIndex + 1u < popupState.itemKinds.size() &&
                                                       popupState.itemKinds[artifactIndex + 1u] == DxUi::MenuItemKind::Separator &&
                                                       propertiesIsFinalNormalAction,
                                                   std::memory_order_release);
                }
                PostMessageW(popup, WM_KEYDOWN, VK_ESCAPE, 0);
                PostMessageW(popup, WM_KEYUP, VK_ESCAPE, 0);
                return;
            }
            std::this_thread::sleep_for(10ms);
        }
    });
    POINT artifactScreenPoint = artifactPoint.value();
    ClientToScreen(folderView, &artifactScreenPoint);
    SendMessageW(folderView, WM_CONTEXTMENU, reinterpret_cast<WPARAM>(folderView), MAKELPARAM(artifactScreenPoint.x, artifactScreenPoint.y));
    artifactMenuCloser.join();
    state.Require(artifactMenuOpened.load(std::memory_order_acquire), L"Artifact item context menu did not open.");
    state.Require(artifactBeforeProperties.load(std::memory_order_acquire),
                  L"Operation artifact submenu must be inserted before a separator and the final Properties action.");

    return state.failure.empty();
}

[[nodiscard]] bool TestFolderViewSelectionRefreshFilterContract(HWND mainWindow, CaseState& state) noexcept
{
    using namespace std::chrono_literals;

    if (! mainWindow || IsWindow(mainWindow) == FALSE ||
        ! PrepareMainWindowForIsolatedUiCase(mainWindow, state, L"FolderView selection refresh/filter contract"))
    {
        state.Require(false, L"Main window is unavailable for FolderView selection refresh/filter contract.");
        return false;
    }

    const std::filesystem::path root =
        SelfTest::GetTempRoot(SelfTest::SelfTestSuite::Commands) / L"work" / (L"folderview_selection_refresh_filter_" + NewGuidText());
    std::error_code error;
    std::filesystem::remove_all(root, error);
    state.Require(SelfTest::EnsureDirectory(root), L"Failed to create selection refresh/filter fixture root.");
    for (const std::wstring_view name : {L"a.txt", L"b.log", L"c.txt"})
    {
        state.Require(SelfTest::WriteTextFile(root / name, "x"), std::format(L"Failed to create '{}'.", name));
    }
    if (! state.failure.empty())
    {
        return false;
    }
    const auto cleanupRoot = wil::scope_exit([&]() noexcept
    {
        std::error_code cleanupError;
        std::filesystem::remove_all(root, cleanupError);
    });

    const std::wstring pluginBefore                       = std::wstring(g_folderWindow.GetFileSystemPluginId(FolderWindow::Pane::Left));
    const std::optional<std::filesystem::path> pathBefore = g_folderWindow.GetCurrentPath(FolderWindow::Pane::Left);
    const FolderView::SortBy sortBefore                   = g_folderWindow.GetSortBy(FolderWindow::Pane::Left);
    const FolderView::SortDirection directionBefore       = g_folderWindow.GetSortDirection(FolderWindow::Pane::Left);
    const FolderView::NameFilterState filterBefore        = g_folderWindow.DebugGetNameFilterState(FolderWindow::Pane::Left);
    const auto restorePane                                = wil::scope_exit([&]() noexcept
    {
        g_folderWindow.DismissPaneAlertOverlay(FolderWindow::Pane::Left);
        g_folderWindow.SetNameFilterState(FolderWindow::Pane::Left, filterBefore, false);
        static_cast<void>(g_folderWindow.SetFileSystemPluginForPane(FolderWindow::Pane::Left, pluginBefore));
        g_folderWindow.SetSort(FolderWindow::Pane::Left, sortBefore, directionBefore);
        if (pathBefore.has_value())
        {
            g_folderWindow.SetFolderPath(FolderWindow::Pane::Left, pathBefore.value());
        }
    });

    g_folderWindow.DebugResetPaneVisibilityState(FolderWindow::Pane::Left);
    state.Require(SUCCEEDED(g_folderWindow.SetFileSystemPluginForPane(FolderWindow::Pane::Left, L"builtin/file-system")),
                  L"Failed to switch to local provider for selection refresh/filter contract.");
    g_folderWindow.SetSort(FolderWindow::Pane::Left, FolderView::SortBy::Name, FolderView::SortDirection::Ascending);
    std::atomic<uint32_t> enumerationCount{0u};
    g_folderWindow.SetPaneEnumerationCompletedCallback(FolderWindow::Pane::Left,
                                                       [&](const std::filesystem::path& folder) noexcept
    {
        if (OrdinalString::EqualsNoCasePath(folder, root))
        {
            enumerationCount.fetch_add(1u, std::memory_order_release);
        }
    });
    const auto clearEnumerationCallback = wil::scope_exit([&]() noexcept { g_folderWindow.SetPaneEnumerationCompletedCallback(FolderWindow::Pane::Left, {}); });
    const auto waitForAcceptedRootModel = [&](uint32_t previousEnumerationCount,
                                              size_t expectedItemCount,
                                              std::initializer_list<std::wstring_view> expectedNames,
                                              std::wstring_view stage) noexcept
    {
        state.Require(WaitForAtomicAtLeast(enumerationCount, previousEnumerationCount + 1u, SelfTest::Scale(5000ms)),
                      std::format(L"{} enumeration did not complete.", stage));
        state.Require(WaitForFolderViewItemCount(FolderWindow::Pane::Left, expectedItemCount, SelfTest::Scale(5000ms)),
                      std::format(L"{} item count did not settle.", stage));
        state.Require(WaitForPaneItems(FolderWindow::Pane::Left, expectedNames, SelfTest::Scale(5000ms)),
                      std::format(L"{} expected identities did not settle.", stage));
    };

    g_folderWindow.SetFolderPath(FolderWindow::Pane::Left, root);
    state.Require(WaitForPanePath(FolderWindow::Pane::Left, root, SelfTest::Scale(5000ms)), L"Selection refresh/filter path did not settle.");
    state.Require(WaitForAtomicAtLeast(enumerationCount, 1u, SelfTest::Scale(5000ms)), L"Selection refresh/filter initial enumeration did not complete.");
    state.Require(WaitForPaneItems(FolderWindow::Pane::Left, {L"a.txt", L"b.log", L"c.txt"}, SelfTest::Scale(5000ms)),
                  L"Selection refresh/filter fixture did not settle.");

    SendMessageW(mainWindow, WM_COMMAND, MAKEWPARAM(IDM_PANE_SELECTION_SELECT_ALL, 0), 0);
    state.Require(g_folderWindow.DebugGetSelectedCount(FolderWindow::Pane::Left) == 3u, L"Select All did not materialize the initial displayed set.");

    uint32_t before = enumerationCount.load(std::memory_order_acquire);
    g_folderWindow.SetNameFilterState(FolderWindow::Pane::Left, FolderView::NameFilterState{.enabled = true, .text = L"*.txt"}, true);
    waitForAcceptedRootModel(before, 2u, {L"a.txt", L"c.txt"}, L"Select All followed by filter");
    state.Require(g_folderWindow.DebugGetSelectedCount(FolderWindow::Pane::Left) == 2u &&
                      g_folderWindow.DebugIsItemSelected(FolderWindow::Pane::Left, L"a.txt") &&
                      g_folderWindow.DebugIsItemSelected(FolderWindow::Pane::Left, L"c.txt"),
                  L"Filtering did not retain only continuously displayed selected identities.");

    before = enumerationCount.load(std::memory_order_acquire);
    g_folderWindow.SetNameFilterState(FolderWindow::Pane::Left, FolderView::NameFilterState{}, true);
    waitForAcceptedRootModel(before, 3u, {L"a.txt", L"b.log", L"c.txt"}, L"Select All filter clear");
    state.Require(g_folderWindow.DebugGetSelectedCount(FolderWindow::Pane::Left) == 2u &&
                      ! g_folderWindow.DebugIsItemSelected(FolderWindow::Pane::Left, L"b.log"),
                  L"Clearing the filter resurrected the formerly Select-All-only b.log identity.");

    state.Require(SelfTest::WriteTextFile(root / L"d.txt", "new"), L"Failed to add d.txt for refresh selection contract.");
    before = enumerationCount.load(std::memory_order_acquire);
    g_folderWindow.CommandRefresh(FolderWindow::Pane::Left);
    waitForAcceptedRootModel(before, 4u, {L"a.txt", L"b.log", L"c.txt", L"d.txt"}, L"accepted refresh with new identity");
    state.Require(g_folderWindow.DebugIsItemSelected(FolderWindow::Pane::Left, L"a.txt") &&
                      g_folderWindow.DebugIsItemSelected(FolderWindow::Pane::Left, L"c.txt") &&
                      ! g_folderWindow.DebugIsItemSelected(FolderWindow::Pane::Left, L"b.log") &&
                      ! g_folderWindow.DebugIsItemSelected(FolderWindow::Pane::Left, L"d.txt"),
                  L"Accepted refresh did not preserve survivors while leaving the new identity unselected.");

    g_folderWindow.SetSort(FolderWindow::Pane::Left, FolderView::SortBy::Name, FolderView::SortDirection::Descending);
    state.Require(g_folderWindow.DebugIsItemSelected(FolderWindow::Pane::Left, L"a.txt") &&
                      g_folderWindow.DebugIsItemSelected(FolderWindow::Pane::Left, L"c.txt") &&
                      g_folderWindow.DebugGetSelectedCount(FolderWindow::Pane::Left) == 2u,
                  L"Sort did not preserve the concrete surviving selected identities.");
    g_folderWindow.SetSort(FolderWindow::Pane::Left, FolderView::SortBy::Name, FolderView::SortDirection::Ascending);

    error.clear();
    std::filesystem::remove(root / L"a.txt", error);
    state.Require(! error, L"Failed to remove selected a.txt for no-resurrection refresh.");
    before = enumerationCount.load(std::memory_order_acquire);
    g_folderWindow.CommandRefresh(FolderWindow::Pane::Left);
    waitForAcceptedRootModel(before, 3u, {L"b.log", L"c.txt", L"d.txt"}, L"selected identity removal");
    state.Require(g_folderWindow.DebugGetSelectedCount(FolderWindow::Pane::Left) == 1u &&
                      g_folderWindow.DebugIsItemSelected(FolderWindow::Pane::Left, L"c.txt"),
                  L"Removing a selected identity did not drop it from the concrete selected set.");

    state.Require(SelfTest::WriteTextFile(root / L"a.txt", "recreated"), L"Failed to recreate a.txt for no-resurrection refresh.");
    before = enumerationCount.load(std::memory_order_acquire);
    g_folderWindow.CommandRefresh(FolderWindow::Pane::Left);
    waitForAcceptedRootModel(before, 4u, {L"a.txt", L"b.log", L"c.txt", L"d.txt"}, L"ordinary identity recreation");
    state.Require(! g_folderWindow.DebugIsItemSelected(FolderWindow::Pane::Left, L"a.txt") &&
                      g_folderWindow.DebugIsItemSelected(FolderWindow::Pane::Left, L"c.txt") &&
                      g_folderWindow.DebugGetSelectedCount(FolderWindow::Pane::Left) == 1u,
                  L"An ordinarily recreated identity resurrected its old selection.");

    g_folderWindow.SetPaneSelectionByDisplayNamePredicate(FolderWindow::Pane::Left, [](std::wstring_view) noexcept { return false; }, true);
    state.Require(g_folderWindow.DebugFocusItemByDisplayName(FolderWindow::Pane::Left, L"b.log"),
                  L"Failed to focus b.log before automatic-current repair selection check.");
    error.clear();
    std::filesystem::remove(root / L"b.log", error);
    state.Require(! error, L"Failed to remove b.log before automatic-current repair selection check.");
    before = enumerationCount.load(std::memory_order_acquire);
    g_folderWindow.CommandRefresh(FolderWindow::Pane::Left);
    waitForAcceptedRootModel(before, 3u, {L"a.txt", L"c.txt", L"d.txt"}, L"automatic-current repair");
    state.Require(WaitForFolderViewFocusedItem(FolderWindow::Pane::Left, L"c.txt", SelfTest::Scale(3000ms)) &&
                      g_folderWindow.DebugGetSelectedCount(FolderWindow::Pane::Left) == 0u &&
                      ! g_folderWindow.DebugIsItemSelected(FolderWindow::Pane::Left, L"c.txt"),
                  L"Automatic current repair selected the replacement identity.");

    g_folderWindow.SetPaneSelectionByDisplayNamePredicate(FolderWindow::Pane::Left, [](std::wstring_view name) noexcept { return name == L"c.txt"; }, true);
    const FolderView::DebugFocusSelectionStateSnapshot beforeFailedResult = g_folderWindow.DebugGetFocusSelectionStateSnapshot(FolderWindow::Pane::Left);
    g_folderWindow.SetFolderPath(FolderWindow::Pane::Left, root / L"missing-folder");
    FolderView::AlertOverlayDebugSnapshot alert{};
    const auto failureDeadline = std::chrono::steady_clock::now() + SelfTest::Scale(5000ms);
    while (std::chrono::steady_clock::now() < failureDeadline)
    {
        PumpPendingMessages();
        if (g_folderWindow.DebugGetPaneAlertSnapshot(FolderWindow::Pane::Left, alert) && alert.visible &&
            alert.kind == FolderView::ErrorOverlayKind::Enumeration)
        {
            break;
        }
        std::this_thread::sleep_for(10ms);
    }
    const FolderView::DebugFocusSelectionStateSnapshot afterFailedResult = g_folderWindow.DebugGetFocusSelectionStateSnapshot(FolderWindow::Pane::Left);
    state.Require(alert.visible && alert.kind == FolderView::ErrorOverlayKind::Enumeration &&
                      afterFailedResult.currentDisplayName == beforeFailedResult.currentDisplayName &&
                      afterFailedResult.selectedCount == beforeFailedResult.selectedCount &&
                      afterFailedResult.selectionDigest == beforeFailedResult.selectionDigest,
                  std::format(L"A failed enumeration result mutated the current displayed selection: alert={} kind={} current '{}' -> '{}', "
                              L"selected {} -> {}, digest {} -> {}.",
                              alert.visible ? 1 : 0,
                              static_cast<unsigned>(alert.kind),
                              beforeFailedResult.currentDisplayName,
                              afterFailedResult.currentDisplayName,
                              beforeFailedResult.selectedCount,
                              afterFailedResult.selectedCount,
                              beforeFailedResult.selectionDigest,
                              afterFailedResult.selectionDigest));

    return state.failure.empty();
}

[[nodiscard]] bool TestFolderViewSelectionVisibilityRestoreContract(HWND mainWindow, CaseState& state) noexcept
{
    using namespace std::chrono_literals;

    if (! mainWindow || IsWindow(mainWindow) == FALSE ||
        ! PrepareMainWindowForIsolatedUiCase(mainWindow, state, L"FolderView selection visibility/restore contract"))
    {
        state.Require(false, L"Main window is unavailable for FolderView selection visibility/restore contract.");
        return false;
    }

    const std::filesystem::path root =
        SelfTest::GetTempRoot(SelfTest::SelfTestSuite::Commands) / L"work" / (L"folderview_selection_visibility_" + NewGuidText());
    std::error_code error;
    std::filesystem::remove_all(root, error);
    state.Require(SelfTest::EnsureDirectory(root), L"Failed to create selection visibility fixture root.");
    for (const std::wstring_view name : {L"a.txt", L"b.log", L"hidden.txt", L"system.txt"})
    {
        state.Require(SelfTest::WriteTextFile(root / name, "x"), std::format(L"Failed to create '{}'.", name));
    }
    state.Require(SetFileAttributesW((root / L"hidden.txt").c_str(), FILE_ATTRIBUTE_HIDDEN) != FALSE, L"Failed to mark hidden.txt hidden.");
    state.Require(SetFileAttributesW((root / L"system.txt").c_str(), FILE_ATTRIBUTE_SYSTEM) != FALSE, L"Failed to mark system.txt system.");
    if (! state.failure.empty())
    {
        return false;
    }
    const auto cleanupRoot = wil::scope_exit([&]() noexcept
    {
        static_cast<void>(SetFileAttributesW((root / L"hidden.txt").c_str(), FILE_ATTRIBUTE_NORMAL));
        static_cast<void>(SetFileAttributesW((root / L"system.txt").c_str(), FILE_ATTRIBUTE_NORMAL));
        std::error_code cleanupError;
        std::filesystem::remove_all(root, cleanupError);
    });

    const std::wstring pluginBefore                       = std::wstring(g_folderWindow.GetFileSystemPluginId(FolderWindow::Pane::Left));
    const std::optional<std::filesystem::path> pathBefore = g_folderWindow.GetCurrentPath(FolderWindow::Pane::Left);
    const FolderView::NameFilterState filterBefore        = g_folderWindow.DebugGetNameFilterState(FolderWindow::Pane::Left);
    const bool showHiddenBefore                           = g_folderWindow.GetShowHiddenFiles();
    const bool showSystemBefore                           = g_folderWindow.GetShowSystemFiles();
    const auto restorePane                                = wil::scope_exit([&]() noexcept
    {
        g_folderWindow.DismissPaneAlertOverlay(FolderWindow::Pane::Left);
        g_folderWindow.SetNameFilterState(FolderWindow::Pane::Left, filterBefore, false);
        g_folderWindow.SetShowHiddenFiles(showHiddenBefore);
        g_folderWindow.SetShowSystemFiles(showSystemBefore);
        static_cast<void>(g_folderWindow.SetFileSystemPluginForPane(FolderWindow::Pane::Left, pluginBefore));
        if (pathBefore.has_value())
        {
            g_folderWindow.SetFolderPath(FolderWindow::Pane::Left, pathBefore.value());
        }
    });

    g_folderWindow.DebugResetPaneVisibilityState(FolderWindow::Pane::Left);
    state.Require(SUCCEEDED(g_folderWindow.SetFileSystemPluginForPane(FolderWindow::Pane::Left, L"builtin/file-system")),
                  L"Failed to switch to local provider for selection visibility contract.");
    g_folderWindow.SetShowHiddenFiles(true);
    g_folderWindow.SetShowSystemFiles(true);
    g_folderWindow.SetSort(FolderWindow::Pane::Left, FolderView::SortBy::Name, FolderView::SortDirection::Ascending);

    std::atomic<uint32_t> enumerationCount{0u};
    g_folderWindow.SetPaneEnumerationCompletedCallback(FolderWindow::Pane::Left,
                                                       [&](const std::filesystem::path& folder) noexcept
    {
        if (OrdinalString::EqualsNoCasePath(folder, root))
        {
            enumerationCount.fetch_add(1u, std::memory_order_release);
        }
    });
    const auto clearEnumerationCallback = wil::scope_exit([&]() noexcept { g_folderWindow.SetPaneEnumerationCompletedCallback(FolderWindow::Pane::Left, {}); });
    const auto waitForAcceptedRootModel = [&](uint32_t previousEnumerationCount,
                                              size_t expectedItemCount,
                                              std::initializer_list<std::wstring_view> expectedNames,
                                              std::wstring_view stage) noexcept
    {
        state.Require(WaitForAtomicAtLeast(enumerationCount, previousEnumerationCount + 1u, SelfTest::Scale(5000ms)),
                      std::format(L"{} enumeration did not complete.", stage));
        if (! WaitForFolderViewItemCount(FolderWindow::Pane::Left, expectedItemCount, SelfTest::Scale(5000ms)))
        {
            const auto filter = g_folderWindow.DebugGetNameFilterState(FolderWindow::Pane::Left);
            const auto path   = g_folderWindow.GetCurrentPath(FolderWindow::Pane::Left);
            state.Require(false,
                          std::format(L"{} item count did not settle: expected={} actual={} filterEnabled={} filter='{}' path='{}' enumerations={}.",
                                      stage,
                                      expectedItemCount,
                                      g_folderWindow.DebugGetItemCount(FolderWindow::Pane::Left),
                                      filter.enabled,
                                      filter.text,
                                      path.has_value() ? path.value().wstring() : L"<none>",
                                      enumerationCount.load(std::memory_order_acquire)));
        }
        state.Require(WaitForPaneItems(FolderWindow::Pane::Left, expectedNames, SelfTest::Scale(5000ms)),
                      std::format(L"{} expected identities did not settle.", stage));
    };
    const auto selectNames = [&](std::initializer_list<std::wstring_view> names) noexcept
    {
        g_folderWindow.SetPaneSelectionByDisplayNamePredicate(FolderWindow::Pane::Left, [names](std::wstring_view candidate) noexcept {
            return std::ranges::any_of(names, [&](std::wstring_view name) noexcept { return candidate == name; });
        }, true);
    };

    g_folderWindow.SetFolderPath(FolderWindow::Pane::Left, root);
    state.Require(WaitForPanePath(FolderWindow::Pane::Left, root, SelfTest::Scale(5000ms)), L"Selection visibility path did not settle.");
    state.Require(WaitForAtomicAtLeast(enumerationCount, 1u, SelfTest::Scale(5000ms)), L"Selection visibility initial enumeration did not complete.");
    state.Require(WaitForPaneItems(FolderWindow::Pane::Left, {L"a.txt", L"b.log", L"hidden.txt", L"system.txt"}, SelfTest::Scale(5000ms)),
                  L"Selection visibility fixture did not settle.");

    selectNames({L"a.txt"});
    uint32_t before = enumerationCount.load(std::memory_order_acquire);
    g_folderWindow.CommandSelectionHideSelectedNames(FolderWindow::Pane::Left);
    waitForAcceptedRootModel(before, 3u, {L"b.log", L"hidden.txt", L"system.txt"}, L"Hide Selected Names");
    state.Require(g_folderWindow.DebugGetSelectedCount(FolderWindow::Pane::Left) == 0u,
                  L"Hide Selected Names retained latent selection for the hidden identity.");
    before = enumerationCount.load(std::memory_order_acquire);
    g_folderWindow.CommandSelectionShowHiddenNames(FolderWindow::Pane::Left);
    waitForAcceptedRootModel(before, 4u, {L"a.txt", L"b.log", L"hidden.txt", L"system.txt"}, L"Show hidden selected name");
    state.Require(! g_folderWindow.DebugIsItemSelected(FolderWindow::Pane::Left, L"a.txt"),
                  L"Show Hidden Names resurrected the formerly hidden selected identity.");

    selectNames({L"b.log"});
    before = enumerationCount.load(std::memory_order_acquire);
    g_folderWindow.CommandSelectionHideUnselectedNames(FolderWindow::Pane::Left);
    waitForAcceptedRootModel(before, 1u, {L"b.log"}, L"Hide Unselected Names");
    state.Require(g_folderWindow.DebugIsItemSelected(FolderWindow::Pane::Left, L"b.log"),
                  L"Hide Unselected Names did not preserve the continuously displayed selected identity.");
    before = enumerationCount.load(std::memory_order_acquire);
    g_folderWindow.CommandSelectionShowHiddenNames(FolderWindow::Pane::Left);
    waitForAcceptedRootModel(before, 4u, {L"a.txt", L"b.log", L"hidden.txt", L"system.txt"}, L"Show hidden unselected names");
    state.Require(g_folderWindow.DebugGetSelectedCount(FolderWindow::Pane::Left) == 1u &&
                      g_folderWindow.DebugIsItemSelected(FolderWindow::Pane::Left, L"b.log") &&
                      ! g_folderWindow.DebugIsItemSelected(FolderWindow::Pane::Left, L"a.txt"),
                  L"Show Hidden Names selected an identity that was not continuously displayed.");

    selectNames({L"hidden.txt", L"system.txt"});
    before = enumerationCount.load(std::memory_order_acquire);
    g_folderWindow.SetShowHiddenFiles(false);
    waitForAcceptedRootModel(before, 3u, {L"a.txt", L"b.log", L"system.txt"}, L"disable Hidden Files");
    state.Require(g_folderWindow.DebugGetSelectedCount(FolderWindow::Pane::Left) == 1u &&
                      g_folderWindow.DebugIsItemSelected(FolderWindow::Pane::Left, L"system.txt"),
                  L"Disabling Hidden Files did not drop only the no-longer-visible selected identity.");
    before = enumerationCount.load(std::memory_order_acquire);
    g_folderWindow.SetShowHiddenFiles(true);
    waitForAcceptedRootModel(before, 4u, {L"a.txt", L"b.log", L"hidden.txt", L"system.txt"}, L"re-enable Hidden Files");
    state.Require(! g_folderWindow.DebugIsItemSelected(FolderWindow::Pane::Left, L"hidden.txt") &&
                      g_folderWindow.DebugIsItemSelected(FolderWindow::Pane::Left, L"system.txt"),
                  L"Re-enabling Hidden Files resurrected selection or lost a continuous survivor.");

    before = enumerationCount.load(std::memory_order_acquire);
    g_folderWindow.SetShowSystemFiles(false);
    waitForAcceptedRootModel(before, 3u, {L"a.txt", L"b.log", L"hidden.txt"}, L"disable System Files");
    before = enumerationCount.load(std::memory_order_acquire);
    g_folderWindow.SetShowSystemFiles(true);
    waitForAcceptedRootModel(before, 4u, {L"a.txt", L"b.log", L"hidden.txt", L"system.txt"}, L"re-enable System Files");
    state.Require(! g_folderWindow.DebugIsItemSelected(FolderWindow::Pane::Left, L"system.txt"),
                  L"Re-enabling System Files resurrected selection for system.txt.");

    selectNames({});
    before = enumerationCount.load(std::memory_order_acquire);
    g_folderWindow.SetNameFilterState(FolderWindow::Pane::Left, FolderView::NameFilterState{.enabled = true, .text = L"*.txt"}, true);
    waitForAcceptedRootModel(before, 3u, {L"a.txt", L"hidden.txt", L"system.txt"}, L"filtered selection commands");
    state.Require(g_folderWindow.DebugFocusItemByDisplayName(FolderWindow::Pane::Left, L"a.txt"),
                  L"Failed to focus a.txt for filtered same-extension command.");
    g_folderWindow.CommandSelectionSelectSameExtension(FolderWindow::Pane::Left);
    state.Require(g_folderWindow.DebugGetSelectedCount(FolderWindow::Pane::Left) == 3u,
                  L"Same Extension did not affect exactly the displayed filtered identities.");
    g_folderWindow.CommandSelectionInvert(FolderWindow::Pane::Left);
    state.Require(g_folderWindow.DebugGetSelectedCount(FolderWindow::Pane::Left) == 0u, L"Invert did not mutate exactly the displayed filtered identities.");
    before = enumerationCount.load(std::memory_order_acquire);
    g_folderWindow.SetNameFilterState(FolderWindow::Pane::Left, FolderView::NameFilterState{}, true);
    waitForAcceptedRootModel(before, 4u, {L"a.txt", L"b.log", L"hidden.txt", L"system.txt"}, L"clear filtered selection commands");
    state.Require(! g_folderWindow.DebugIsItemSelected(FolderWindow::Pane::Left, L"b.log"),
                  L"A selection command mutated the later-visible b.log identity while it was filtered out.");

    selectNames({L"a.txt", L"hidden.txt"});
    g_folderWindow.CommandSelectionSave(FolderWindow::Pane::Left);
    state.Require(g_folderWindow.HasSavedSelection(), L"Save Selection did not capture the visible selected identities.");
    before = enumerationCount.load(std::memory_order_acquire);
    g_folderWindow.SetNameFilterState(FolderWindow::Pane::Left, FolderView::NameFilterState{.enabled = true, .text = L"a*"}, true);
    waitForAcceptedRootModel(before, 1u, {L"a.txt"}, L"narrow before Restore Selection");
    g_folderWindow.CommandSelectionRestore(FolderWindow::Pane::Left);
    state.Require(g_folderWindow.DebugGetSelectedCount(FolderWindow::Pane::Left) == 1u &&
                      g_folderWindow.DebugIsItemSelected(FolderWindow::Pane::Left, L"a.txt"),
                  L"Restore Selection did not select only saved identities visible at restore time.");
    g_folderWindow.DismissPaneAlertOverlay(FolderWindow::Pane::Left);
    before = enumerationCount.load(std::memory_order_acquire);
    g_folderWindow.SetNameFilterState(FolderWindow::Pane::Left, FolderView::NameFilterState{}, true);
    waitForAcceptedRootModel(before, 4u, {L"a.txt", L"b.log", L"hidden.txt", L"system.txt"}, L"widen after Restore Selection");
    state.Require(g_folderWindow.DebugIsItemSelected(FolderWindow::Pane::Left, L"a.txt") &&
                      ! g_folderWindow.DebugIsItemSelected(FolderWindow::Pane::Left, L"hidden.txt") &&
                      g_folderWindow.DebugGetSelectedCount(FolderWindow::Pane::Left) == 1u,
                  L"Widening visibility resurrected a saved identity that was absent during Restore Selection.");
    g_folderWindow.CommandSelectionRestore(FolderWindow::Pane::Left);
    state.Require(g_folderWindow.DebugGetSelectedCount(FolderWindow::Pane::Left) == 2u &&
                      g_folderWindow.DebugIsItemSelected(FolderWindow::Pane::Left, L"a.txt") &&
                      g_folderWindow.DebugIsItemSelected(FolderWindow::Pane::Left, L"hidden.txt"),
                  L"Explicit Restore Selection did not select the now-visible saved identities.");

    return state.failure.empty();
}

[[nodiscard]] bool TestFolderViewDragSourceTargetContract(HWND mainWindow, CaseState& state) noexcept
{
    using namespace std::chrono_literals;

    if (! mainWindow || IsWindow(mainWindow) == FALSE || ! PrepareMainWindowForIsolatedUiCase(mainWindow, state, L"FolderView drag source target contract"))
    {
        state.Require(false, L"Main window is unavailable for FolderView drag-source contract.");
        return false;
    }

    const std::filesystem::path root = SelfTest::GetTempRoot(SelfTest::SelfTestSuite::Commands) / L"work" / (L"folderview_drag_source_" + NewGuidText());
    std::error_code cleanupError;
    std::filesystem::remove_all(root, cleanupError);
    state.Require(SelfTest::EnsureDirectory(root), L"Failed to create drag-source fixture root.");
    for (const std::wstring_view name : {L"a.txt", L"b.txt", L"c.txt"})
    {
        state.Require(SelfTest::WriteTextFile(root / name, "x"), std::format(L"Failed to create '{}'.", name));
    }
    if (! state.failure.empty())
    {
        return false;
    }
    const auto cleanupRoot = wil::scope_exit([&]() noexcept
    {
        std::error_code error;
        std::filesystem::remove_all(root, error);
    });

    const std::wstring pluginBefore                       = std::wstring(g_folderWindow.GetFileSystemPluginId(FolderWindow::Pane::Left));
    const std::optional<std::filesystem::path> pathBefore = g_folderWindow.GetCurrentPath(FolderWindow::Pane::Left);
    const auto restorePane                                = wil::scope_exit([&]() noexcept
    {
        g_folderWindow.DebugSetPaneSuppressOleDragDropForSelfTest(FolderWindow::Pane::Left, false);
        static_cast<void>(g_folderWindow.SetFileSystemPluginForPane(FolderWindow::Pane::Left, pluginBefore));
        if (pathBefore.has_value())
        {
            g_folderWindow.SetFolderPath(FolderWindow::Pane::Left, pathBefore.value());
        }
    });

    g_folderWindow.DebugResetPaneVisibilityState(FolderWindow::Pane::Left);
    state.Require(SUCCEEDED(g_folderWindow.SetFileSystemPluginForPane(FolderWindow::Pane::Left, L"builtin/file-system")),
                  L"Failed to switch to local provider for drag-source contract.");
    g_folderWindow.SetSort(FolderWindow::Pane::Left, FolderView::SortBy::Name, FolderView::SortDirection::Ascending);
    std::atomic<uint32_t> enumerationCount{0u};
    g_folderWindow.SetPaneEnumerationCompletedCallback(FolderWindow::Pane::Left,
                                                       [&](const std::filesystem::path& folder) noexcept
    {
        if (OrdinalString::EqualsNoCasePath(folder, root))
        {
            enumerationCount.fetch_add(1u, std::memory_order_release);
        }
    });
    const auto clearEnumerationCallback = wil::scope_exit([&]() noexcept { g_folderWindow.SetPaneEnumerationCompletedCallback(FolderWindow::Pane::Left, {}); });
    g_folderWindow.SetFolderPath(FolderWindow::Pane::Left, root);
    state.Require(WaitForPanePath(FolderWindow::Pane::Left, root, SelfTest::Scale(5000ms)), L"Drag-source path did not settle.");
    state.Require(WaitForAtomicAtLeast(enumerationCount, 1u, SelfTest::Scale(5000ms)), L"Drag-source enumeration did not complete.");
    state.Require(WaitForPaneItems(FolderWindow::Pane::Left, {L"a.txt", L"b.txt", L"c.txt"}, SelfTest::Scale(5000ms)), L"Drag-source items did not settle.");
    const HWND folderView                      = g_folderWindow.GetFolderViewHwnd(FolderWindow::Pane::Left);
    const std::optional<POINT> backgroundPoint = g_folderWindow.DebugGetPaneEmptyBackgroundClientPointForSelfTest(FolderWindow::Pane::Left);
    state.Require(folderView && IsWindow(folderView) != FALSE && backgroundPoint.has_value(), L"Drag-source pointer targets are unavailable.");
    if (! state.failure.empty())
    {
        return false;
    }

    const auto pointFor = [&](std::wstring_view name) noexcept
    {
        const std::optional<POINT> point = g_folderWindow.DebugGetPaneItemCenterClientPointForSelfTest(FolderWindow::Pane::Left, name);
        state.Require(point.has_value(), std::format(L"No drag-source pointer point for '{}'.", name));
        return point.value_or(POINT{});
    };
    const auto down = [&](std::wstring_view name, WPARAM modifiers = 0u) noexcept
    {
        const POINT point = pointFor(name);
        SendMessageW(folderView, WM_LBUTTONDOWN, MK_LBUTTON | modifiers, MAKELPARAM(point.x, point.y));
        return point;
    };
    const auto release = [&](POINT point, WPARAM modifiers = 0u) noexcept { SendMessageW(folderView, WM_LBUTTONUP, modifiers, MAKELPARAM(point.x, point.y)); };
    const auto selectNames = [&](std::initializer_list<std::wstring_view> names) noexcept
    {
        g_folderWindow.SetPaneSelectionByDisplayNamePredicate(FolderWindow::Pane::Left, [names](std::wstring_view candidate) noexcept {
            return std::ranges::any_of(names, [&](std::wstring_view name) noexcept { return candidate == name; });
        }, true);
    };

    g_folderWindow.DebugSetPaneSuppressOleDragDropForSelfTest(FolderWindow::Pane::Left, true);
    state.Require(g_folderWindow.DebugFocusItemByDisplayName(FolderWindow::Pane::Left, L"a.txt"), L"Failed to establish empty-selection drag current.");
    std::vector<std::filesystem::path> commandTargets = g_folderWindow.DebugGetPaneCommandTargetPathsForSelfTest(FolderWindow::Pane::Left);
    state.Require(commandTargets.size() == 1u && commandTargets[0].filename() == L"a.txt" &&
                      g_folderWindow.DebugGetSelectedCount(FolderWindow::Pane::Left) == 0u,
                  L"Empty selection did not expose current-only command fallback while status remained selection-only.");
    POINT point                                           = down(L"a.txt");
    FolderView::DebugFocusSelectionStateSnapshot snapshot = g_folderWindow.DebugGetFocusSelectionStateSnapshot(FolderWindow::Pane::Left);
    state.Require(snapshot.potentialDragSourceCount == 1u, L"Empty-selection item press did not arm current-item fallback.");
    const UINT dragDpi   = GetDpiForWindow(folderView);
    const int dragWidth  = (std::max)(1, GetSystemMetricsForDpi(SM_CXDRAG, dragDpi));
    const int dragHeight = (std::max)(1, GetSystemMetricsForDpi(SM_CYDRAG, dragDpi));
    const POINT insideThreshold{
        point.x + (dragWidth - dragWidth / 2) - 1,
        point.y + (dragHeight - dragHeight / 2) - 1,
    };
    const POINT outsideThreshold{
        point.x + (dragWidth - dragWidth / 2),
        point.y,
    };
    SendMessageW(folderView, WM_MOUSEMOVE, MK_LBUTTON, MAKELPARAM(insideThreshold.x, insideThreshold.y));
    state.Require(g_folderWindow.DebugGetPaneDragStartCountForSelfTest(FolderWindow::Pane::Left) == 0u,
                  L"Movement at the inclusive edge of the system drag-threshold rectangle started a drag.");
    SendMessageW(folderView, WM_MOUSEMOVE, MK_LBUTTON, MAKELPARAM(outsideThreshold.x, outsideThreshold.y));
    std::vector<std::filesystem::path> startedPaths = g_folderWindow.DebugGetPaneLastDragStartPathsForSelfTest(FolderWindow::Pane::Left);
    state.Require(g_folderWindow.DebugGetPaneDragStartCountForSelfTest(FolderWindow::Pane::Left) == 1u && startedPaths.size() == 1u &&
                      startedPaths[0].filename() == L"a.txt",
                  L"Leaving the threshold did not start from immutable current-item fallback.");

    state.Require(g_folderWindow.DebugFocusItemByDisplayName(FolderWindow::Pane::Left, L"a.txt"), L"Failed to reset selected-set drag current.");
    selectNames({L"a.txt", L"c.txt"});
    snapshot = g_folderWindow.DebugGetFocusSelectionStateSnapshot(FolderWindow::Pane::Left);
    state.Require(snapshot.selectedCount == 2u,
                  std::format(L"Selected-set drag fixture did not contain two items before press; selected={}.", snapshot.selectedCount));
    point          = down(L"c.txt");
    snapshot       = g_folderWindow.DebugGetFocusSelectionStateSnapshot(FolderWindow::Pane::Left);
    commandTargets = g_folderWindow.DebugGetPaneCommandTargetPathsForSelfTest(FolderWindow::Pane::Left);
    state.Require(snapshot.potentialDragSourceCount == 2u && snapshot.selectedCount == 2u,
                  std::format(L"Press on selected item did not snapshot the selected set; selected={}, source={}, current='{}'.",
                              snapshot.selectedCount,
                              snapshot.potentialDragSourceCount,
                              snapshot.currentDisplayName));
    state.Require(commandTargets.size() == snapshot.potentialDragSourceCount && std::ranges::all_of(commandTargets,
                                                                                                    [&](const std::filesystem::path& path) noexcept
    { return path.filename() == L"a.txt" || path.filename() == L"c.txt"; }),
                  L"Selection-aware command targets and drag-source resolution did not use the same selected-set fallback.");
    release(point);
    state.Require(g_folderWindow.DebugGetFocusSelectionStateSnapshot(FolderWindow::Pane::Left).potentialDragSourceCount == 0u,
                  L"Button release did not disarm the potential drag.");

    selectNames({L"a.txt", L"c.txt"});
    point    = down(L"b.txt");
    snapshot = g_folderWindow.DebugGetFocusSelectionStateSnapshot(FolderWindow::Pane::Left);
    state.Require(snapshot.selectedCount == 1u && g_folderWindow.DebugIsItemSelected(FolderWindow::Pane::Left, L"b.txt") &&
                      snapshot.potentialDragSourceCount == 1u,
                  L"Plain press on an unselected item did not replace selection before drag snapshot.");
    release(point);

    state.Require(g_folderWindow.DebugFocusItemByDisplayName(FolderWindow::Pane::Left, L"a.txt"), L"Failed to reset Ctrl+Click drag fixture.");
    selectNames({L"a.txt", L"c.txt"});
    point    = down(L"c.txt", MK_CONTROL);
    snapshot = g_folderWindow.DebugGetFocusSelectionStateSnapshot(FolderWindow::Pane::Left);
    state.Require(snapshot.selectedCount == 1u && ! g_folderWindow.DebugIsItemSelected(FolderWindow::Pane::Left, L"c.txt") &&
                      snapshot.potentialDragSourceCount == 0u,
                  L"Ctrl+Click deselection armed the leftover selection as drag source.");
    release(point, MK_CONTROL);

    point = down(L"a.txt");
    SendMessageW(folderView, WM_CANCELMODE, 0, 0);
    state.Require(g_folderWindow.DebugGetFocusSelectionStateSnapshot(FolderWindow::Pane::Left).potentialDragSourceCount == 0u,
                  L"Cancellation did not disarm potential drag.");
    point                                = down(L"a.txt");
    const uint64_t dragCountBeforeEscape = g_folderWindow.DebugGetPaneDragStartCountForSelfTest(FolderWindow::Pane::Left);
    SendMessageW(folderView, WM_KEYDOWN, VK_ESCAPE, 0);
    snapshot = g_folderWindow.DebugGetFocusSelectionStateSnapshot(FolderWindow::Pane::Left);
    state.Require(snapshot.potentialDragSourceCount == 0u && snapshot.selectedCount == 0u && snapshot.currentDisplayName == L"a.txt" &&
                      snapshot.anchorIndex == snapshot.currentIndex,
                  L"Escape did not clear selection, retain current/anchor, and disarm the potential drag source.");
    SendMessageW(folderView, WM_MOUSEMOVE, MK_LBUTTON, MAKELPARAM(point.x + dragWidth, point.y + dragHeight));
    state.Require(g_folderWindow.DebugGetPaneDragStartCountForSelfTest(FolderWindow::Pane::Left) == dragCountBeforeEscape,
                  L"Movement after Escape started a drag from the stale pre-Escape source snapshot.");
    release(point);
    point = down(L"a.txt");
    SendMessageW(folderView, WM_CAPTURECHANGED, 0, 0);
    state.Require(g_folderWindow.DebugGetFocusSelectionStateSnapshot(FolderWindow::Pane::Left).potentialDragSourceCount == 0u,
                  L"Capture loss did not disarm potential drag.");
    point = down(L"a.txt");
    g_folderWindow.SetSort(FolderWindow::Pane::Left, FolderView::SortBy::Name, FolderView::SortDirection::Descending);
    state.Require(g_folderWindow.DebugGetFocusSelectionStateSnapshot(FolderWindow::Pane::Left).potentialDragSourceCount == 0u,
                  L"Sort/model replacement did not disarm potential drag.");
    g_folderWindow.SetSort(FolderWindow::Pane::Left, FolderView::SortBy::Name, FolderView::SortDirection::Ascending);

    point                   = down(L"a.txt");
    const POINT secondPoint = down(L"b.txt");
    startedPaths            = g_folderWindow.DebugGetPaneLastDragStartPathsForSelfTest(FolderWindow::Pane::Left);
    snapshot                = g_folderWindow.DebugGetFocusSelectionStateSnapshot(FolderWindow::Pane::Left);
    state.Require(snapshot.potentialDragSourceCount == 1u && snapshot.currentDisplayName == L"b.txt",
                  L"A new press did not replace the older potential drag source.");
    release(secondPoint);

    point = down(L"a.txt");
    SendMessageW(folderView, WM_LBUTTONDOWN, MK_LBUTTON, MAKELPARAM(backgroundPoint->x, backgroundPoint->y));
    SendMessageW(folderView, WM_MOUSEMOVE, MK_LBUTTON, MAKELPARAM(backgroundPoint->x + 100, backgroundPoint->y + 100));
    state.Require(g_folderWindow.DebugGetFocusSelectionStateSnapshot(FolderWindow::Pane::Left).potentialDragSourceCount == 0u,
                  L"Empty-background movement inherited an older drag source.");
    SendMessageW(folderView, WM_LBUTTONUP, 0, MAKELPARAM(backgroundPoint->x, backgroundPoint->y));

    point = down(L"a.txt");
    SendMessageW(folderView, WM_LBUTTONDBLCLK, 0, MAKELPARAM(backgroundPoint->x, backgroundPoint->y));
    state.Require(g_folderWindow.DebugGetFocusSelectionStateSnapshot(FolderWindow::Pane::Left).potentialDragSourceCount == 0u,
                  L"Double-click inherited an older armed drag source.");
    ReleaseCapture();

    return state.failure.empty();
}

[[nodiscard]] bool TestFolderViewPerfFocusSelectionState(HWND mainWindow, CaseState& state) noexcept
{
    using namespace std::chrono_literals;

    if (! mainWindow || IsWindow(mainWindow) == FALSE)
    {
        state.Require(false, L"Main window handle invalid for FolderView focus/selection state perf.");
        return false;
    }

    if (! PrepareMainWindowForIsolatedUiCase(mainWindow, state, L"FolderView focus/selection state performance validation"))
    {
        return false;
    }

    FolderViewDummyPluginHandles dummy{};
    state.Require(LoadFolderViewDummyPlugin(state, dummy), L"Failed to load dummy file system for FolderView focus/selection state perf.");
    if (! state.failure.empty())
    {
        return false;
    }

    std::string previousDummyConfig;
    state.Require(BackupPluginConfigurationForFolderViewPerf(dummy.informations.get(), previousDummyConfig),
                  L"Failed to snapshot dummy configuration for FolderView focus/selection state perf.");
    if (! state.failure.empty())
    {
        return false;
    }
    const auto restoreDummyConfig =
        wil::scope_exit([&]() noexcept { static_cast<void>(SetPluginConfigurationForFolderViewPerf(dummy.informations.get(), previousDummyConfig)); });

    constexpr std::string_view kDeterministicEmptyDummyConfig =
        R"json({"maxChildrenPerDirectory":0,"maxDepth":10,"seed":42,"latencyMs":0,"streamChunkLatencyMs":0,"virtualSpeedLimit":"0"})json";
    state.Require(SetPluginConfigurationForFolderViewPerf(dummy.informations.get(), kDeterministicEmptyDummyConfig),
                  L"Failed to apply deterministic dummy configuration for FolderView focus/selection state perf.");

    constexpr size_t kItemCount       = 10000u;
    constexpr size_t kExtensionCount  = 64u;
    constexpr size_t kSortSampleCount = 200u;
    const auto makeFixtureName        = [](size_t index) noexcept
    {
        const size_t extensionIndex = index % kExtensionCount;
        return std::format(L"scaleprobe_{:05}_ext{:03}.fvx{:03}", index, extensionIndex, extensionIndex);
    };
    const std::filesystem::path dummyRoot = std::filesystem::path(L"/folderview-focus-selection-state") / SanitizeFolderViewDummyPathSegment(NewGuidText());
    std::wstring firstName;
    std::wstring middleName;
    std::wstring lastName;
    state.Require(MaterializeFolderViewDummyFiles(state, dummy, dummyRoot, kItemCount, kExtensionCount, &firstName, &middleName, &lastName),
                  L"Failed to materialize FolderView focus/selection state fixture.");
    if (! state.failure.empty())
    {
        return false;
    }
    const auto cleanupDummyRoot = wil::scope_exit([&]() noexcept
    {
        const std::wstring rootText = dummyRoot.generic_wstring();
        static_cast<void>(dummy.fileSystem->DeleteItem(rootText.c_str(), FILESYSTEM_FLAG_RECURSIVE, nullptr, nullptr, nullptr));
    });

    const std::wstring leftPluginBefore                   = std::wstring(g_folderWindow.GetFileSystemPluginId(FolderWindow::Pane::Left));
    const std::optional<std::filesystem::path> leftBefore = g_folderWindow.GetCurrentPath(FolderWindow::Pane::Left);
    const FolderView::DisplayMode displayBefore           = g_folderWindow.GetDisplayMode(FolderWindow::Pane::Left);
    const FolderView::SortBy sortBefore                   = g_folderWindow.GetSortBy(FolderWindow::Pane::Left);
    const FolderView::SortDirection directionBefore       = g_folderWindow.GetSortDirection(FolderWindow::Pane::Left);
    const FolderView::NameFilterState filterBefore        = g_folderWindow.DebugGetNameFilterState(FolderWindow::Pane::Left);
    const auto restorePaneState                           = wil::scope_exit([&]() noexcept
    {
        g_folderWindow.SetNameFilterState(FolderWindow::Pane::Left, filterBefore, false);
        static_cast<void>(g_folderWindow.SetFileSystemPluginForPane(FolderWindow::Pane::Left, leftPluginBefore));
        g_folderWindow.SetDisplayMode(FolderWindow::Pane::Left, displayBefore);
        g_folderWindow.SetSort(FolderWindow::Pane::Left, sortBefore, directionBefore);
        if (leftBefore.has_value())
        {
            g_folderWindow.SetFolderPath(FolderWindow::Pane::Left, leftBefore.value());
        }
    });

    state.Require(SUCCEEDED(g_folderWindow.SetFileSystemPluginForPane(FolderWindow::Pane::Left, kBuiltinDummyFileSystemIdForFolderViewPerf.data())),
                  L"Failed to switch left pane to dummy file system for FolderView focus/selection state perf.");
    g_folderWindow.SetDisplayMode(FolderWindow::Pane::Left, FolderView::DisplayMode::Detailed);
    g_folderWindow.SetSort(FolderWindow::Pane::Left, FolderView::SortBy::Name, FolderView::SortDirection::Ascending);
    g_folderWindow.DebugResetPaneVisibilityState(FolderWindow::Pane::Left);

    std::atomic<uint32_t> enumerationCount{0u};
    g_folderWindow.SetPaneEnumerationCompletedCallback(FolderWindow::Pane::Left,
                                                       [&](const std::filesystem::path& folder) noexcept
    {
        if (OrdinalString::EqualsNoCase(folder.generic_wstring(), dummyRoot.generic_wstring()))
        {
            enumerationCount.fetch_add(1u, std::memory_order_release);
        }
    });
    const auto clearEnumerationCallback = wil::scope_exit([&]() noexcept { g_folderWindow.SetPaneEnumerationCompletedCallback(FolderWindow::Pane::Left, {}); });

    const std::uintmax_t metricScanOffset = FolderViewPerfMetricScanOffset();
    g_folderWindow.SetFolderPath(FolderWindow::Pane::Left, dummyRoot);
    state.Require(WaitForPanePluginPathForFolderViewPerf(FolderWindow::Pane::Left, dummyRoot, SelfTest::Scale(20000ms)),
                  L"FolderView focus/selection state dummy path did not load.");
    state.Require(WaitForAtomicAtLeast(enumerationCount, 1u, SelfTest::Scale(20000ms)),
                  L"FolderView focus/selection state initial enumeration did not complete.");
    state.Require(WaitForFolderViewItemCount(FolderWindow::Pane::Left, kItemCount, SelfTest::Scale(20000ms)),
                  L"FolderView focus/selection state item count did not settle.");
    if (! state.failure.empty())
    {
        return false;
    }

    constexpr size_t kReasonCount = static_cast<size_t>(FolderView::CurrentResolutionReason::Unresolved) + 1u;
    std::array<uint64_t, kReasonCount> resolutionReasonCounts{};
    uint64_t modelChangeSamples           = 0u;
    uint64_t invariantViolationCount      = 0u;
    size_t maximumFocusMemoryEntries      = 0u;
    size_t maximumFocusMemoryPayloadBytes = 0u;
    auto observe                          = [&]() noexcept
    {
        const FolderView::DebugFocusSelectionStateSnapshot snapshot = g_folderWindow.DebugGetFocusSelectionStateSnapshot(FolderWindow::Pane::Left);
        const size_t reasonIndex                                    = static_cast<size_t>(snapshot.resolutionReason);
        if (reasonIndex < resolutionReasonCounts.size())
        {
            ++resolutionReasonCounts[reasonIndex];
        }
        ++modelChangeSamples;
        maximumFocusMemoryEntries      = (std::max)(maximumFocusMemoryEntries, snapshot.focusMemoryEntryCount);
        maximumFocusMemoryPayloadBytes = (std::max)(maximumFocusMemoryPayloadBytes, snapshot.focusMemoryPayloadBytes);
        if ((snapshot.itemCount == 0u && (snapshot.currentIndex != static_cast<size_t>(-1) || snapshot.focusedFlagCount != 0u || snapshot.selectedCount != 0u ||
                                          snapshot.anchorIndex != static_cast<size_t>(-1))) ||
            (snapshot.itemCount > 0u && (snapshot.currentIndex >= snapshot.itemCount || snapshot.focusedFlagCount != 1u)))
        {
            ++invariantViolationCount;
        }
        return snapshot;
    };

    FolderView::DebugFocusSelectionStateSnapshot initialSnapshot = observe();
    Debug::Perf::Emit(L"folder.focus_memory.entry_count", L"initial", 0u, initialSnapshot.focusMemoryEntryCount, kItemCount, S_OK);
    Debug::Perf::Emit(L"folder.focus_memory.payload_bytes", L"initial", 0u, initialSnapshot.focusMemoryPayloadBytes, kItemCount, S_OK);
    Debug::Perf::Emit(L"folder.focus_memory.eviction_count", L"initial", 0u, initialSnapshot.focusMemoryEvictionCount, kItemCount, S_OK);

    state.Require(g_folderWindow.DebugFocusItemByDisplayName(FolderWindow::Pane::Left, middleName),
                  L"Failed to focus the middle dummy item before the current-survives phase.");
    g_folderWindow.SetPaneSelectionByDisplayNamePredicate(
        FolderWindow::Pane::Left, [&](std::wstring_view name) noexcept { return name == firstName || name == middleName || name == lastName; }, true);
    const uint32_t refreshBeforeSurvival = enumerationCount.load(std::memory_order_acquire);
    g_folderWindow.CommandRefresh(FolderWindow::Pane::Left);
    state.Require(WaitForAtomicAtLeast(enumerationCount, refreshBeforeSurvival + 1u, SelfTest::Scale(20000ms)),
                  L"FolderView focus/selection state current-survives refresh did not complete.");
    observe();

    const HWND pointerFolderView             = g_folderWindow.GetFolderViewHwnd(FolderWindow::Pane::Left);
    const std::wstring pointerTargetName     = makeFixtureName(5001u);
    const std::optional<POINT> pointerTarget = g_folderWindow.DebugGetPaneItemCenterClientPointForSelfTest(FolderWindow::Pane::Left, pointerTargetName);
    state.Require(pointerFolderView && IsWindow(pointerFolderView) != FALSE && pointerTarget.has_value(),
                  L"FolderView focus/selection state pointer transition target is unavailable.");
    if (pointerFolderView && pointerTarget.has_value())
    {
        const uint64_t pointerMetricBefore = FolderViewPerfMetricCountInRun(L"folder.frame.input_to_paint_us", metricScanOffset);
        SendMessageW(pointerFolderView, WM_LBUTTONDOWN, MK_LBUTTON, MAKELPARAM(pointerTarget->x, pointerTarget->y));
        SendMessageW(pointerFolderView, WM_LBUTTONUP, 0, MAKELPARAM(pointerTarget->x, pointerTarget->y));
        UpdateWindow(pointerFolderView);
        PumpPendingMessages();
        const FolderView::DebugFocusSelectionStateSnapshot pointerSnapshot = g_folderWindow.DebugGetFocusSelectionStateSnapshot(FolderWindow::Pane::Left);
        state.Require(pointerSnapshot.currentDisplayName == pointerTargetName && pointerSnapshot.selectedCount == 1u &&
                          FolderViewPerfMetricCountInRun(L"folder.frame.input_to_paint_us", metricScanOffset) > pointerMetricBefore,
                      L"FolderView focus/selection state pointer transition did not produce current/selection and aggregate input-to-paint evidence.");
    }
    state.Require(g_folderWindow.DebugFocusItemByDisplayName(FolderWindow::Pane::Left, middleName),
                  L"Failed to restore middle current after pointer transition.");
    g_folderWindow.SetPaneSelectionByDisplayNamePredicate(
        FolderWindow::Pane::Left, [&](std::wstring_view name) noexcept { return name == firstName || name == middleName || name == lastName; }, true);

    for (size_t sample = 0u; sample < kSortSampleCount; ++sample)
    {
        switch (sample % 4u)
        {
            case 0u: g_folderWindow.SetSort(FolderWindow::Pane::Left, FolderView::SortBy::Name, FolderView::SortDirection::Descending); break;
            case 1u: g_folderWindow.SetSort(FolderWindow::Pane::Left, FolderView::SortBy::Extension, FolderView::SortDirection::Ascending); break;
            case 2u: g_folderWindow.SetSort(FolderWindow::Pane::Left, FolderView::SortBy::None, FolderView::SortDirection::Ascending); break;
            default: g_folderWindow.SetSort(FolderWindow::Pane::Left, FolderView::SortBy::Name, FolderView::SortDirection::Ascending); break;
        }
        observe();
    }

    g_folderWindow.SetPaneSelectionByDisplayNamePredicate(FolderWindow::Pane::Left, [](std::wstring_view) noexcept { return true; }, true);
    const uint32_t filterEnumerationBefore = enumerationCount.load(std::memory_order_acquire);
    g_folderWindow.SetNameFilterState(FolderWindow::Pane::Left, FolderView::NameFilterState{.enabled = true, .text = L"scaleprobe_00*"}, true);
    state.Require(WaitForAtomicAtLeast(enumerationCount, filterEnumerationBefore + 1u, SelfTest::Scale(20000ms)),
                  L"FolderView focus/selection state filter enumeration did not complete.");
    state.Require(g_folderWindow.DebugGetItemCount(FolderWindow::Pane::Left) > 0u && g_folderWindow.DebugGetItemCount(FolderWindow::Pane::Left) < kItemCount,
                  L"FolderView focus/selection state filter did not produce a nonempty subset.");
    observe();

    const uint32_t unfilterBefore = enumerationCount.load(std::memory_order_acquire);
    g_folderWindow.SetNameFilterState(FolderWindow::Pane::Left, FolderView::NameFilterState{}, true);
    state.Require(WaitForAtomicAtLeast(enumerationCount, unfilterBefore + 1u, SelfTest::Scale(20000ms)),
                  L"FolderView focus/selection state unfilter enumeration did not complete.");
    state.Require(WaitForFolderViewItemCount(FolderWindow::Pane::Left, kItemCount, SelfTest::Scale(20000ms)),
                  L"FolderView focus/selection state unfilter did not restore the full model.");
    observe();

    const HWND folderView = g_folderWindow.GetFolderViewHwnd(FolderWindow::Pane::Left);
    state.Require(folderView && IsWindow(folderView) != FALSE, L"FolderView focus/selection state window is unavailable.");
    if (folderView && IsWindow(folderView) != FALSE)
    {
        SendMessageW(folderView, WM_KEYDOWN, VK_ESCAPE, 0);
        SendMessageW(folderView, WM_KEYUP, VK_ESCAPE, 0);
    }
    state.Require(g_folderWindow.DebugFocusItemByDisplayName(FolderWindow::Pane::Left, middleName),
                  L"Failed to focus the middle dummy item before the disappearance phase.");

    for (const size_t index : std::array<size_t, 3u>{{4999u, 5000u, 5001u}})
    {
        const std::wstring pathText = (dummyRoot / makeFixtureName(index)).generic_wstring();
        const HRESULT deleteHr      = dummy.fileSystem->DeleteItem(pathText.c_str(), FILESYSTEM_FLAG_NONE, nullptr, nullptr, nullptr);
        state.Require(deleteHr == S_OK, std::format(L"Failed to remove focus-disappearance fixture {}. hr=0x{:08X}", index, static_cast<uint32_t>(deleteHr)));
    }
    const uint32_t disappearanceBefore = enumerationCount.load(std::memory_order_acquire);
    g_folderWindow.CommandRefresh(FolderWindow::Pane::Left);
    state.Require(WaitForAtomicAtLeast(enumerationCount, disappearanceBefore + 1u, SelfTest::Scale(20000ms)),
                  L"FolderView focus/selection state disappearance refresh did not complete.");
    state.Require(WaitForFolderViewItemCount(FolderWindow::Pane::Left, kItemCount - 3u, SelfTest::Scale(20000ms)),
                  L"FolderView focus/selection state disappearance model did not settle.");
    const FolderView::DebugFocusSelectionStateSnapshot keyedRepairSnapshot = observe();
    state.Require(keyedRepairSnapshot.resolutionReason == FolderView::CurrentResolutionReason::GenericSuccessor ||
                      keyedRepairSnapshot.resolutionReason == FolderView::CurrentResolutionReason::GenericPredecessor,
                  L"FolderView focus/selection state keyed disappearance did not exercise generic repair.");

    g_folderWindow.SetSort(FolderWindow::Pane::Left, FolderView::SortBy::None, FolderView::SortDirection::Ascending);
    observe();
    state.Require(g_folderWindow.DebugFocusItemByDisplayName(FolderWindow::Pane::Left, makeFixtureName(6000u)),
                  L"Failed to focus the Sort None disappearance fixture.");
    for (const size_t index : std::array<size_t, 3u>{{5999u, 6000u, 6001u}})
    {
        const std::wstring pathText = (dummyRoot / makeFixtureName(index)).generic_wstring();
        const HRESULT deleteHr      = dummy.fileSystem->DeleteItem(pathText.c_str(), FILESYSTEM_FLAG_NONE, nullptr, nullptr, nullptr);
        state.Require(deleteHr == S_OK,
                      std::format(L"Failed to remove Sort None focus-disappearance fixture {}. hr=0x{:08X}", index, static_cast<uint32_t>(deleteHr)));
    }
    const uint32_t sortNoneDisappearanceBefore = enumerationCount.load(std::memory_order_acquire);
    g_folderWindow.CommandRefresh(FolderWindow::Pane::Left);
    state.Require(WaitForAtomicAtLeast(enumerationCount, sortNoneDisappearanceBefore + 1u, SelfTest::Scale(20000ms)),
                  L"FolderView focus/selection state Sort None disappearance refresh did not complete.");
    state.Require(WaitForFolderViewItemCount(FolderWindow::Pane::Left, kItemCount - 6u, SelfTest::Scale(20000ms)),
                  L"FolderView focus/selection state Sort None disappearance model did not settle.");
    const FolderView::DebugFocusSelectionStateSnapshot sortNoneRepairSnapshot = observe();
    state.Require(sortNoneRepairSnapshot.resolutionReason == FolderView::CurrentResolutionReason::GenericSuccessor ||
                      sortNoneRepairSnapshot.resolutionReason == FolderView::CurrentResolutionReason::GenericPredecessor,
                  L"FolderView focus/selection state Sort None disappearance did not exercise generic repair.");

    const std::filesystem::path memoryRoot = std::filesystem::path(L"/folderview-focus-memory") / SanitizeFolderViewDummyPathSegment(NewGuidText());
    for (size_t index = 0u; index < 600u; ++index)
    {
        g_folderWindow.DebugRememberPaneFocusedItemForFolder(
            FolderWindow::Pane::Left, memoryRoot / std::format(L"location_{:03}", index), std::format(L"item_{:03}.txt", index));
    }
    const FolderView::DebugFocusSelectionStateSnapshot finalSnapshot = observe();
    Debug::Perf::Emit(L"folder.focus_memory.entry_count", L"post-churn", 0u, finalSnapshot.focusMemoryEntryCount, 600u, S_OK);
    Debug::Perf::Emit(L"folder.focus_memory.payload_bytes", L"post-churn", 0u, finalSnapshot.focusMemoryPayloadBytes, 600u, S_OK);
    Debug::Perf::Emit(L"folder.focus_memory.eviction_count", L"post-churn", 0u, finalSnapshot.focusMemoryEvictionCount, 600u, S_OK);

    maximumFocusMemoryEntries      = (std::max)(maximumFocusMemoryEntries, finalSnapshot.focusMemoryEntryCount);
    maximumFocusMemoryPayloadBytes = (std::max)(maximumFocusMemoryPayloadBytes, finalSnapshot.focusMemoryPayloadBytes);
    const uint64_t focusMemoryCapViolationCount =
        (finalSnapshot.focusMemoryEntryCount > 512u ? 1u : 0u) + (finalSnapshot.focusMemoryPayloadBytes > 512u * 1024u ? 1u : 0u);
    const uint64_t focusResolveMetricRows = FolderViewPerfMetricCountInRun(L"folder.focus.resolve_us", metricScanOffset);
    const uint64_t refreshMetricRows      = FolderViewPerfMetricCountInRun(L"folder.refresh.enumeration_count", metricScanOffset);
    state.Require(focusResolveMetricRows >= kSortSampleCount,
                  std::format(L"FolderView focus/selection state emitted {} resolver rows; expected at least {}.", focusResolveMetricRows, kSortSampleCount));
    state.Require(refreshMetricRows >= 4u, std::format(L"FolderView focus/selection state emitted {} refresh rows; expected at least 4.", refreshMetricRows));
    state.Require(invariantViolationCount == 0u,
                  std::format(L"FolderView focus/selection state observed {} current/selection invariant violation(s).", invariantViolationCount));
    state.Require(focusMemoryCapViolationCount == 0u,
                  std::format(L"FolderView focus/selection state observed {} focus-memory cap violation(s).", focusMemoryCapViolationCount));

    std::wstring json;
    json.append(L"{\n");
    json.append(L"  \"case\": \"folderView_perf_focus_selection_state\",\n");
    json.append(L"  \"provider\": \"builtin/file-system-dummy\",\n");
    json.append(std::format(L"  \"itemCount\": {},\n", kItemCount));
    json.append(std::format(L"  \"sortModelChangeSamples\": {},\n", kSortSampleCount));
    json.append(std::format(L"  \"observedModelChangeSamples\": {},\n", modelChangeSamples));
    json.append(std::format(L"  \"focusResolveMetricRows\": {},\n", focusResolveMetricRows));
    json.append(std::format(L"  \"refreshMetricRows\": {},\n", refreshMetricRows));
    json.append(std::format(L"  \"invariantViolationCount\": {},\n", invariantViolationCount));
    json.append(std::format(L"  \"focusMemoryCapViolationCount\": {},\n", focusMemoryCapViolationCount));
    json.append(L"  \"resolutionReasonCounts\": {");
    for (size_t index = 0u; index < resolutionReasonCounts.size(); ++index)
    {
        json.append(std::format(L"\"{}\": {}", index, resolutionReasonCounts[index]));
        json.append(index + 1u < resolutionReasonCounts.size() ? L", " : L"");
    }
    json.append(L"},\n");
    json.append(L"  \"focusMemory\": {\n");
    json.append(std::format(L"    \"maximumEntries\": {},\n", maximumFocusMemoryEntries));
    json.append(std::format(L"    \"maximumPayloadBytes\": {},\n", maximumFocusMemoryPayloadBytes));
    json.append(std::format(L"    \"finalEntries\": {},\n", finalSnapshot.focusMemoryEntryCount));
    json.append(std::format(L"    \"finalPayloadBytes\": {},\n", finalSnapshot.focusMemoryPayloadBytes));
    json.append(std::format(L"    \"evictions\": {},\n", finalSnapshot.focusMemoryEvictionCount));
    json.append(std::format(L"    \"hits\": {},\n", finalSnapshot.focusMemoryHitCount));
    json.append(std::format(L"    \"misses\": {},\n", finalSnapshot.focusMemoryMissCount));
    json.append(std::format(L"    \"noCache\": {},\n", finalSnapshot.focusMemoryNoCacheCount));
    json.append(std::format(L"    \"locationIdentityNoCache\": {},\n", finalSnapshot.focusMemoryLocationIdentityNoCacheCount));
    json.append(std::format(L"    \"itemIdentityNoCache\": {},\n", finalSnapshot.focusMemoryItemIdentityNoCacheCount));
    json.append(std::format(L"    \"oversizedEntryNoCache\": {},\n", finalSnapshot.focusMemoryOversizedEntryNoCacheCount));
    json.append(std::format(L"    \"lastNoCacheReason\": {}\n", static_cast<unsigned>(finalSnapshot.focusMemoryLastNoCacheReason)));
    json.append(L"  },\n");
    AppendFolderViewEnvironmentMatrixJson(json, CaptureFolderViewEnvironmentMatrix(mainWindow), L"  ");
    json.append(L"\n}\n");

    const std::filesystem::path artifactPath = SelfTest::GetPerfArtifactPath(L"folderView_perf_focus_selection_state_metrics.json");
    const bool artifactWriteOk               = ! artifactPath.empty() && SelfTest::WriteTextFile(artifactPath, json);
    state.Require(artifactWriteOk && SelfTest::PathExists(artifactPath), L"Failed to write FolderView focus/selection state perf artifact.");
    return state.failure.empty();
}

[[nodiscard]] bool CreateFolderViewColdFirstVisitFixture(
    CaseState& state, const std::filesystem::path& root, size_t itemCount, size_t extensionCount, std::wstring& firstName, std::wstring& lastName) noexcept
{
    state.Require(SelfTest::EnsureDirectory(root), L"Failed to create cold first-visit fixture root.");
    if (! state.failure.empty())
    {
        return false;
    }

    for (size_t i = 0; i < itemCount; ++i)
    {
        const size_t extensionIndex = extensionCount > 0u ? (i % extensionCount) : 0u;
        const std::wstring fileName = std::format(L"coldvisit_{:04}_unique{:03}.cfv{:03}", i, extensionIndex, extensionIndex);
        state.Require(SelfTest::WriteTextFile(root / fileName, "cold first visit"), std::format(L"Failed to create cold first-visit item {}.", fileName));
        if (! state.failure.empty())
        {
            return false;
        }
        if (i == 0u)
        {
            firstName = fileName;
        }
        if (i + 1u == itemCount)
        {
            lastName = fileName;
        }
    }

    return state.failure.empty();
}

[[nodiscard]] bool TestFolderViewPerfColdFirstVisit(HWND mainWindow, CaseState& state) noexcept
{
    using namespace std::chrono_literals;

    if (! mainWindow || ! IsWindow(mainWindow))
    {
        state.Require(false, L"Main window handle invalid for cold FolderView first-visit perf.");
        return false;
    }

    const std::filesystem::path suiteRoot = SelfTest::GetTempRoot(SelfTest::SelfTestSuite::Commands);
    state.Require(! suiteRoot.empty(), L"SelfTest temp root unavailable for cold FolderView first-visit perf.");
    if (suiteRoot.empty())
    {
        return false;
    }

    constexpr size_t kItemCount      = 384u;
    constexpr size_t kExtensionCount = 128u;
    const std::filesystem::path root = suiteRoot / L"work" / (L"folder_cold_first_visit_" + NewGuidText());
    std::error_code ec;
    std::filesystem::remove_all(root, ec);
    std::wstring firstName;
    std::wstring lastName;
    state.Require(CreateFolderViewColdFirstVisitFixture(state, root, kItemCount, kExtensionCount, firstName, lastName),
                  L"Failed to create cold FolderView first-visit fixture.");
    if (! state.failure.empty())
    {
        return false;
    }

    const std::wstring leftPluginBefore                   = std::wstring(g_folderWindow.GetFileSystemPluginId(FolderWindow::Pane::Left));
    const std::optional<std::filesystem::path> leftBefore = g_folderWindow.GetCurrentPath(FolderWindow::Pane::Left);
    const FolderView::DisplayMode displayBefore           = g_folderWindow.GetDisplayMode(FolderWindow::Pane::Left);
    const FolderView::SortBy sortBefore                   = g_folderWindow.GetSortBy(FolderWindow::Pane::Left);
    const FolderView::SortDirection directionBefore       = g_folderWindow.GetSortDirection(FolderWindow::Pane::Left);
    const auto restorePaneState                           = wil::scope_exit([&]() noexcept
    {
        g_folderWindow.DebugSetThumbnailProviderMode(FolderWindow::Pane::Left, FolderView::DebugThumbnailProviderMode::Shell);
        static_cast<void>(g_folderWindow.SetFileSystemPluginForPane(FolderWindow::Pane::Left, leftPluginBefore));
        g_folderWindow.SetDisplayMode(FolderWindow::Pane::Left, displayBefore);
        g_folderWindow.SetSort(FolderWindow::Pane::Left, sortBefore, directionBefore);
        if (leftBefore.has_value())
        {
            g_folderWindow.SetFolderPath(FolderWindow::Pane::Left, leftBefore.value());
        }
    });

    IconCache::GetInstance().Clear();
    const std::uintmax_t metricScanOffset = FolderViewPerfMetricScanOffset();
    const auto coldPerfBefore             = g_folderWindow.DebugGetWarmPanePerfSnapshot(FolderWindow::Pane::Left);
    std::atomic<uint32_t> enumerationCount{0};
    g_folderWindow.SetPaneEnumerationCompletedCallback(FolderWindow::Pane::Left,
                                                       [&](const std::filesystem::path& folder) noexcept
    {
        if (OrdinalString::EqualsNoCasePath(folder, root))
        {
            enumerationCount.fetch_add(1u, std::memory_order_release);
        }
    });
    const auto clearEnumCallback = wil::scope_exit([&] { g_folderWindow.SetPaneEnumerationCompletedCallback(FolderWindow::Pane::Left, {}); });

    state.Require(SUCCEEDED(g_folderWindow.SetFileSystemPluginForPane(FolderWindow::Pane::Left, L"builtin/file-system")),
                  L"Failed to switch left pane to local file system for cold FolderView first-visit perf.");
    g_folderWindow.SetDisplayMode(FolderWindow::Pane::Left, FolderView::DisplayMode::Detailed);
    g_folderWindow.SetSort(FolderWindow::Pane::Left, FolderView::SortBy::Name, FolderView::SortDirection::Ascending);
    g_folderWindow.DebugResetPaneVisibilityState(FolderWindow::Pane::Left);

    const auto navigationStart = std::chrono::steady_clock::now();
    g_folderWindow.SetFolderPath(FolderWindow::Pane::Left, root);
    state.Require(WaitForPanePath(FolderWindow::Pane::Left, root, SelfTest::Scale(10000ms)), L"Cold FolderView first-visit path did not load.");
    state.Require(WaitForAtomicAtLeast(enumerationCount, 1u, SelfTest::Scale(10000ms)), L"Cold FolderView first-visit enumeration did not complete.");
    const uint64_t enumerationUs = Debug::Perf::ElapsedUs(navigationStart);
    state.Require(WaitForFolderViewItemCount(FolderWindow::Pane::Left, kItemCount, SelfTest::Scale(10000ms)),
                  std::format(L"Cold FolderView first-visit item count mismatch; expected={} actual={}.",
                              kItemCount,
                              g_folderWindow.DebugGetItemCount(FolderWindow::Pane::Left)));
    state.Require(g_folderWindow.DebugHasItemDisplayName(FolderWindow::Pane::Left, firstName) &&
                      g_folderWindow.DebugHasItemDisplayName(FolderWindow::Pane::Left, lastName),
                  L"Cold FolderView first-visit probe items did not load.");
    if (! state.failure.empty())
    {
        return false;
    }

    state.Require(g_folderWindow.DebugWarmPaneRendering(FolderWindow::Pane::Left), L"Cold FolderView first-visit first paint failed.");
    const uint64_t firstPaintUs = Debug::Perf::ElapsedUs(navigationStart);
    const auto iconStart        = std::chrono::steady_clock::now();
    state.Require(WaitForFolderViewBitmapIconCount(FolderWindow::Pane::Left, 1u, SelfTest::Scale(5000ms)),
                  L"Cold FolderView first-visit did not resolve any bitmap icons.");
    const uint64_t iconSettleUs           = Debug::Perf::ElapsedUs(iconStart);
    const auto coldPerfAfterIcons         = g_folderWindow.DebugGetWarmPanePerfSnapshot(FolderWindow::Pane::Left);
    const uint64_t iconQueueCalls         = coldPerfAfterIcons.queueIconLoadingCalls - coldPerfBefore.queueIconLoadingCalls;
    const uint64_t iconProcessQueueCalls  = coldPerfAfterIcons.processIconQueueCalls - coldPerfBefore.processIconQueueCalls;
    const uint64_t iconBatchUpdateCalls   = coldPerfAfterIcons.batchIconUpdateCalls - coldPerfBefore.batchIconUpdateCalls;
    const uint64_t iconIndexLookupMetrics = FolderViewPerfMetricCountInRun(L"iconcache.shgetfileinfo_us", metricScanOffset);

    g_folderWindow.DebugSetThumbnailProviderMode(FolderWindow::Pane::Left, FolderView::DebugThumbnailProviderMode::ForceFallback);
    const auto thumbnailFallbackStart = std::chrono::steady_clock::now();
    g_folderWindow.SetDisplayMode(FolderWindow::Pane::Left, FolderView::DisplayMode::Thumbnails);
    FolderWindow::PaneViewOptionsDebugSnapshot thumbnailFallbackSnapshot{};
    state.Require(WaitForPaneThumbnailStats(FolderWindow::Pane::Left,
                                            [](const FolderWindow::PaneViewOptionsDebugSnapshot& snapshot) noexcept
    { return snapshot.thumbnailPendingCount == 0u && snapshot.thumbnailCompletedCount > 0u && snapshot.thumbnailFallbackCount > 0u; },
                                            SelfTest::Scale(8000ms),
                                            &thumbnailFallbackSnapshot),
                  L"Cold FolderView first-visit forced thumbnail fallback did not settle.");
    state.Require(g_folderWindow.DebugWarmPaneRendering(FolderWindow::Pane::Left), L"Cold FolderView first-visit thumbnail fallback paint failed.");
    if (! state.failure.empty())
    {
        return false;
    }
    const uint64_t thumbnailFallbackUs = Debug::Perf::ElapsedUs(thumbnailFallbackStart);

    Debug::Perf::Emit(L"folder.cold_first_visit.enumeration_us", L"local-unique-extensions", enumerationUs, kItemCount, kExtensionCount, S_OK);
    Debug::Perf::Emit(L"folder.cold_first_visit.first_paint_us", L"local-unique-extensions", firstPaintUs, kItemCount, kExtensionCount, S_OK);
    Debug::Perf::Emit(
        L"folder.cold_first_visit.icon_index_lookup_count", L"iconcache.shgetfileinfo_us", iconIndexLookupMetrics, kItemCount, kExtensionCount, S_OK);
    Debug::Perf::Emit(
        L"folder.cold_first_visit.icon_bitmap_queue_count", L"first-icon-bitmap-queue", iconQueueCalls, iconProcessQueueCalls, iconBatchUpdateCalls, S_OK);
    Debug::Perf::Emit(L"folder.cold_first_visit.icon_settle_us",
                      L"local-unique-extensions",
                      iconSettleUs,
                      static_cast<uint64_t>(g_folderWindow.DebugGetPaneBitmapIconCount(FolderWindow::Pane::Left)),
                      kItemCount,
                      S_OK);
    Debug::Perf::Emit(L"folder.cold_first_visit.thumbnail_fallback_us",
                      L"force-fallback-first-visit",
                      thumbnailFallbackUs,
                      thumbnailFallbackSnapshot.thumbnailFallbackCount,
                      thumbnailFallbackSnapshot.thumbnailCompletedCount,
                      S_OK);

    const uint64_t totalFrameCount   = FolderViewPerfMetricCountInRun(L"folder.frame.total_us", metricScanOffset);
    const uint64_t presentFrameCount = FolderViewPerfMetricCountInRun(L"folder.frame.present_us", metricScanOffset);
    std::wstring json;
    json.append(L"{\n");
    json.append(L"  \"case\": \"folderView_perf_cold_first_visit\",\n");
    json.append(L"  \"root\": ");
    AppendFolderViewColumnJsonString(json, root.native());
    json.append(L",\n");
    json.append(std::format(L"  \"itemCount\": {},\n", kItemCount));
    json.append(std::format(L"  \"uniqueExtensionCount\": {},\n", kExtensionCount));
    json.append(L"  \"cacheScope\": \"application IconCache cleared; OS shell cache is intentionally uncontrolled\",\n");
    json.append(std::format(L"  \"enumerationUs\": {},\n", enumerationUs));
    json.append(std::format(L"  \"firstPaintUs\": {},\n", firstPaintUs));
    json.append(std::format(L"  \"iconIndexLookupMetricCount\": {},\n", iconIndexLookupMetrics));
    json.append(std::format(L"  \"iconQueueLoadingCalls\": {},\n", iconQueueCalls));
    json.append(std::format(L"  \"iconProcessQueueCalls\": {},\n", iconProcessQueueCalls));
    json.append(std::format(L"  \"iconBatchUpdateCalls\": {},\n", iconBatchUpdateCalls));
    json.append(std::format(L"  \"iconSettleUs\": {},\n", iconSettleUs));
    json.append(std::format(L"  \"bitmapIconCount\": {},\n", g_folderWindow.DebugGetPaneBitmapIconCount(FolderWindow::Pane::Left)));
    json.append(std::format(L"  \"thumbnailFallbackUs\": {},\n", thumbnailFallbackUs));
    json.append(std::format(L"  \"thumbnailFallbackCount\": {},\n", thumbnailFallbackSnapshot.thumbnailFallbackCount));
    json.append(std::format(L"  \"thumbnailCompletedCount\": {},\n", thumbnailFallbackSnapshot.thumbnailCompletedCount));
    json.append(std::format(L"  \"thumbnailPendingCount\": {},\n", thumbnailFallbackSnapshot.thumbnailPendingCount));
    json.append(L"  \"metricQuality\": {\n");
    AppendFolderViewMetricQualityJson(json, totalFrameCount, presentFrameCount, L"cold-first-visit", L"    ");
    json.append(L"\n");
    json.append(L"  },\n");
    AppendFolderViewEnvironmentMatrixJson(json, CaptureFolderViewEnvironmentMatrix(mainWindow), L"  ");
    json.append(L"\n");
    json.append(L"}\n");

    const std::filesystem::path artifactPath = SelfTest::GetPerfArtifactPath(L"folderView_perf_cold_first_visit_metrics.json");
    const bool artifactWriteOk               = ! artifactPath.empty() && SelfTest::WriteTextFile(artifactPath, json);
    state.Require(artifactWriteOk && SelfTest::PathExists(artifactPath), L"Failed to write cold FolderView first-visit perf artifact.");

    return state.failure.empty();
}

[[nodiscard]] bool TestFolderViewPerfSlowVirtualProvider(HWND mainWindow, CaseState& state) noexcept
{
    using namespace std::chrono_literals;

    if (! mainWindow || ! IsWindow(mainWindow))
    {
        state.Require(false, L"Main window handle invalid for slow virtual FolderView provider perf.");
        return false;
    }

    const std::uintmax_t metricScanOffset = FolderViewPerfMetricScanOffset();

    FolderViewDummyPluginHandles dummy{};
    state.Require(LoadFolderViewDummyPlugin(state, dummy), L"Failed to load dummy file system for slow virtual FolderView provider perf.");
    if (! state.failure.empty())
    {
        return false;
    }

    std::string previousDummyConfig;
    state.Require(BackupPluginConfigurationForFolderViewPerf(dummy.informations.get(), previousDummyConfig),
                  L"Failed to snapshot dummy configuration for slow virtual FolderView provider perf.");
    if (! state.failure.empty())
    {
        return false;
    }
    const auto restoreDummyConfig =
        wil::scope_exit([&]() noexcept { static_cast<void>(SetPluginConfigurationForFolderViewPerf(dummy.informations.get(), previousDummyConfig)); });

    constexpr std::string_view kEmptyFastConfig =
        R"json({"maxChildrenPerDirectory":0,"maxDepth":10,"seed":43,"latencyMs":0,"streamChunkLatencyMs":0,"virtualSpeedLimit":"0"})json";
    constexpr std::string_view kSlowConfig =
        R"json({"maxChildrenPerDirectory":0,"maxDepth":10,"seed":43,"latencyMs":1,"streamChunkLatencyMs":0,"virtualSpeedLimit":"0"})json";
    state.Require(SetPluginConfigurationForFolderViewPerf(dummy.informations.get(), kEmptyFastConfig),
                  L"Failed to apply fast empty dummy configuration for slow virtual FolderView provider perf.");
    const std::filesystem::path dummyRoot = std::filesystem::path(L"/folderview-slow-provider") / SanitizeFolderViewDummyPathSegment(NewGuidText());
    constexpr size_t kItemCount           = 80u;
    constexpr size_t kExtensionCount      = 80u;
    std::wstring firstName;
    std::wstring middleName;
    std::wstring lastName;
    state.Require(MaterializeFolderViewDummyFiles(state, dummy, dummyRoot, kItemCount, kExtensionCount, &firstName, &middleName, &lastName),
                  L"Failed to materialize slow virtual FolderView provider fixture.");
    state.Require(SetPluginConfigurationForFolderViewPerf(dummy.informations.get(), kSlowConfig),
                  L"Failed to enable dummy provider latency for slow virtual FolderView provider perf.");
    if (! state.failure.empty())
    {
        return false;
    }

    const std::wstring leftPluginBefore                   = std::wstring(g_folderWindow.GetFileSystemPluginId(FolderWindow::Pane::Left));
    const std::optional<std::filesystem::path> leftBefore = g_folderWindow.GetCurrentPath(FolderWindow::Pane::Left);
    const FolderView::DisplayMode displayBefore           = g_folderWindow.GetDisplayMode(FolderWindow::Pane::Left);
    const FolderView::SortBy sortBefore                   = g_folderWindow.GetSortBy(FolderWindow::Pane::Left);
    const FolderView::SortDirection directionBefore       = g_folderWindow.GetSortDirection(FolderWindow::Pane::Left);
    const auto restorePaneState                           = wil::scope_exit([&]() noexcept
    {
        SelfTestLatency::ClearAll();
        g_folderWindow.DebugSetThumbnailProviderMode(FolderWindow::Pane::Left, FolderView::DebugThumbnailProviderMode::Shell);
        static_cast<void>(g_folderWindow.SetFileSystemPluginForPane(FolderWindow::Pane::Left, leftPluginBefore));
        g_folderWindow.SetDisplayMode(FolderWindow::Pane::Left, displayBefore);
        g_folderWindow.SetSort(FolderWindow::Pane::Left, sortBefore, directionBefore);
        if (leftBefore.has_value())
        {
            g_folderWindow.SetFolderPath(FolderWindow::Pane::Left, leftBefore.value());
        }
    });

    IconCache::GetInstance().Clear();
    SelfTestLatency::ClearAll();
    SelfTestLatency::SetNextDelay(SelfTestLatency::Point::IconExtractSystemIcon, SelfTest::Scale(60ms));

    state.Require(SUCCEEDED(g_folderWindow.SetFileSystemPluginForPane(FolderWindow::Pane::Left, kBuiltinDummyFileSystemIdForFolderViewPerf.data())),
                  L"Failed to switch left pane to dummy file system for slow virtual FolderView provider perf.");
    g_folderWindow.SetDisplayMode(FolderWindow::Pane::Left, FolderView::DisplayMode::Detailed);
    g_folderWindow.SetSort(FolderWindow::Pane::Left, FolderView::SortBy::Name, FolderView::SortDirection::Ascending);
    g_folderWindow.DebugResetPaneVisibilityState(FolderWindow::Pane::Left);

    std::atomic<uint32_t> enumerationCount{0};
    g_folderWindow.SetPaneEnumerationCompletedCallback(FolderWindow::Pane::Left,
                                                       [&](const std::filesystem::path& folder) noexcept
    {
        if (OrdinalString::EqualsNoCase(folder.generic_wstring(), dummyRoot.generic_wstring()))
        {
            enumerationCount.fetch_add(1u, std::memory_order_release);
        }
    });
    const auto clearEnumCallback = wil::scope_exit([&] { g_folderWindow.SetPaneEnumerationCompletedCallback(FolderWindow::Pane::Left, {}); });

    const auto navigationStart = std::chrono::steady_clock::now();
    g_folderWindow.SetFolderPath(FolderWindow::Pane::Left, dummyRoot);
    state.Require(WaitForPanePluginPathForFolderViewPerf(FolderWindow::Pane::Left, dummyRoot, SelfTest::Scale(10000ms)),
                  L"Slow virtual FolderView provider path did not load.");
    state.Require(WaitForAtomicAtLeast(enumerationCount, 1u, SelfTest::Scale(10000ms)), L"Slow virtual FolderView provider enumeration did not complete.");
    const uint64_t enumerationUs = Debug::Perf::ElapsedUs(navigationStart);
    state.Require(WaitForFolderViewItemCount(FolderWindow::Pane::Left, kItemCount, SelfTest::Scale(10000ms)),
                  std::format(L"Slow virtual FolderView provider item count mismatch; expected={} actual={}.",
                              kItemCount,
                              g_folderWindow.DebugGetItemCount(FolderWindow::Pane::Left)));
    if (! state.failure.empty())
    {
        return false;
    }

    const HWND folderView = g_folderWindow.GetFolderViewHwnd(FolderWindow::Pane::Left);
    state.Require(folderView && IsWindow(folderView) != FALSE, L"Left FolderView handle unavailable for slow virtual FolderView provider perf.");
    state.Require(g_folderWindow.DebugWarmPaneRendering(FolderWindow::Pane::Left), L"Slow virtual FolderView provider first paint failed.");
    const uint64_t firstPaintUs = Debug::Perf::ElapsedUs(navigationStart);
    state.Require(WaitForLatencyConsume(SelfTestLatency::Point::IconExtractSystemIcon, 1u, SelfTest::Scale(5000ms)),
                  L"Slow virtual FolderView provider did not exercise the injected icon-extraction latency hook.");
    state.Require(WaitForFolderViewBitmapIconCount(FolderWindow::Pane::Left, 1u, SelfTest::Scale(5000ms)),
                  L"Slow virtual FolderView provider did not resolve any bitmap icons.");
    const uint64_t iconExtractLatencyConsumeCount = SelfTestLatency::ConsumeCount(SelfTestLatency::Point::IconExtractSystemIcon);
    const uint64_t bitmapIconCount                = g_folderWindow.DebugGetPaneBitmapIconCount(FolderWindow::Pane::Left);
    Debug::Perf::Emit(L"folder.slow_provider.enumeration_us", L"dummy-latency-1ms-per-entry", enumerationUs, kItemCount, 1u, S_OK);
    Debug::Perf::Emit(L"folder.slow_provider.first_visible_paint_us", L"dummy-latency-1ms-per-entry", firstPaintUs, kItemCount, 1u, S_OK);
    state.Require(enumerationUs >= 50000u,
                  std::format(L"Slow virtual FolderView provider did not expose the configured provider latency; enumerationUs={}.", enumerationUs));
    if (! state.failure.empty())
    {
        return false;
    }

    const std::filesystem::path suiteRoot = SelfTest::GetTempRoot(SelfTest::SelfTestSuite::Commands);
    state.Require(! suiteRoot.empty(), L"SelfTest temp root unavailable for slow virtual FolderView provider perf.");
    if (suiteRoot.empty())
    {
        return false;
    }

    std::error_code ec;
    const std::filesystem::path missingIconRoot = suiteRoot / L"work" / (L"slow_failed_icon_lookup_" + NewGuidText());
    const std::filesystem::path missingIconPath = missingIconRoot / L"offline-denied-placeholder.lnk";
    std::filesystem::remove_all(missingIconRoot, ec);
    ec.clear();
    state.Require(SelfTest::EnsureDirectory(missingIconRoot), L"Failed to create slow failed icon lookup fixture root.");
    state.Require(! std::filesystem::exists(missingIconPath, ec) && ! ec, L"Slow failed icon lookup probe path should not exist.");
    if (! state.failure.empty())
    {
        return false;
    }

    IconCache::GetInstance().Clear();
    SelfTestLatency::ClearAll();
    SelfTestLatency::SetNextDelay(SelfTestLatency::Point::IconPathLiveLookup, SelfTest::Scale(40ms));
    const auto firstFailedLookupStart             = std::chrono::steady_clock::now();
    const std::optional<int> firstFailedIcon      = IconCache::GetInstance().QuerySysIconIndexForPath(missingIconPath.c_str(), 0, false);
    const uint64_t firstFailedLookupUs            = Debug::Perf::ElapsedUs(firstFailedLookupStart);
    const uint64_t failedLookupConsumesAfterFirst = SelfTestLatency::ConsumeCount(SelfTestLatency::Point::IconPathLiveLookup);

    SelfTestLatency::SetNextDelay(SelfTestLatency::Point::IconPathLiveLookup, SelfTest::Scale(40ms));
    const auto repeatedFailedLookupStart           = std::chrono::steady_clock::now();
    const std::optional<int> repeatedFailedIcon    = IconCache::GetInstance().QuerySysIconIndexForPath(missingIconPath.c_str(), 0, false);
    const uint64_t repeatedFailedLookupUs          = Debug::Perf::ElapsedUs(repeatedFailedLookupStart);
    const uint64_t failedLookupConsumesAfterRepeat = SelfTestLatency::ConsumeCount(SelfTestLatency::Point::IconPathLiveLookup);
    const uint64_t repeatedFailedLookupCount =
        failedLookupConsumesAfterRepeat > failedLookupConsumesAfterFirst ? failedLookupConsumesAfterRepeat - failedLookupConsumesAfterFirst : 0u;
    Debug::Perf::Emit(L"icons.failed_lookup_first_us", L"path-live-missing-uncached", firstFailedLookupUs, 1u, 0u, S_FALSE);
    Debug::Perf::Emit(L"icons.failed_lookup_repeat_us", L"path-live-missing-backoff", repeatedFailedLookupUs, repeatedFailedLookupCount, 0u, S_OK);
    Debug::Perf::Emit(L"icons.repeated_failed_lookup_count", L"path-live-missing-backoff", 1u, repeatedFailedLookupCount, 2u, S_OK);
    state.Require(! firstFailedIcon.has_value(), L"First slow failed icon lookup should fail for the missing path.");
    state.Require(! repeatedFailedIcon.has_value(), L"Repeated slow failed icon lookup should still report no icon index.");
    state.Require(failedLookupConsumesAfterFirst == 1u,
                  std::format(L"First slow failed icon lookup should consume exactly one live lookup hook; consumed={}.", failedLookupConsumesAfterFirst));
    state.Require(repeatedFailedLookupCount == 0u,
                  std::format(L"Repeated failed live icon lookup should honor the bounded negative-cache backoff; repeated shell lookups={}.",
                              repeatedFailedLookupCount));
    if (! state.failure.empty())
    {
        return false;
    }

    const std::filesystem::path thumbnailRoot = suiteRoot / L"work" / (L"slow_thumbnail_provider_probe_" + NewGuidText());
    std::filesystem::remove_all(thumbnailRoot, ec);
    ec.clear();
    state.Require(SelfTest::EnsureDirectory(thumbnailRoot), L"Failed to create slow thumbnail provider probe root.");
    state.Require(SelfTest::WriteTextFile(thumbnailRoot / L"slow_provider_thumbnail_probe.txt", "slow thumbnail provider probe"),
                  L"Failed to write slow thumbnail provider probe file.");
    if (! state.failure.empty())
    {
        return false;
    }

    g_folderWindow.DebugSetThumbnailProviderMode(FolderWindow::Pane::Left, FolderView::DebugThumbnailProviderMode::ForceProviderAllowedProbe);
    g_folderWindow.SetDisplayMode(FolderWindow::Pane::Left, FolderView::DisplayMode::Detailed);
    state.Require(LoadLeftPaneThumbnailFixture(state, thumbnailRoot, {L"slow_provider_thumbnail_probe.txt"}, SelfTest::Scale(4000ms)),
                  L"Slow virtual FolderView provider thumbnail probe did not load.");
    if (! state.failure.empty())
    {
        return false;
    }

    SelfTestLatency::ClearAll();
    SelfTestLatency::SetNextDelay(SelfTestLatency::Point::ShellThumbnailProviderAllowed, SelfTest::Scale(40ms));
    const auto thumbnailLookupStart = std::chrono::steady_clock::now();
    g_folderWindow.SetDisplayMode(FolderWindow::Pane::Left, FolderView::DisplayMode::Thumbnails);
    state.Require(WaitForLatencyConsume(SelfTestLatency::Point::ShellThumbnailProviderAllowed, 1u, SelfTest::Scale(2000ms)),
                  L"Slow virtual FolderView provider did not exercise the provider-allowed thumbnail latency hook.");
    const uint64_t thumbnailProviderAllowedLookupUs = Debug::Perf::ElapsedUs(thumbnailLookupStart);
    FolderWindow::PaneViewOptionsDebugSnapshot slowThumbnailSnapshot{};
    state.Require(WaitForPaneThumbnailStats(FolderWindow::Pane::Left,
                                            [](const FolderWindow::PaneViewOptionsDebugSnapshot& snapshot) noexcept
    { return snapshot.thumbnailShellProviderAllowedCount >= 1u; },
                                            SelfTest::Scale(3000ms),
                                            &slowThumbnailSnapshot),
                  L"Slow virtual FolderView provider thumbnail probe did not report provider-allowed work.");
    const uint64_t thumbnailProviderAllowedConsumeCount = SelfTestLatency::ConsumeCount(SelfTestLatency::Point::ShellThumbnailProviderAllowed);
    Debug::Perf::Emit(L"thumbnails.provider_allowed_lookup_us",
                      L"slow-provider-task6",
                      thumbnailProviderAllowedLookupUs,
                      slowThumbnailSnapshot.thumbnailShellProviderAllowedCount,
                      thumbnailProviderAllowedConsumeCount,
                      S_OK);
    if (! state.failure.empty())
    {
        return false;
    }

    std::wstring json;
    json.append(L"{\n");
    json.append(L"  \"case\": \"folderView_perf_slow_virtual_provider\",\n");
    json.append(L"  \"provider\": \"builtin/file-system-dummy\",\n");
    json.append(L"  \"root\": ");
    AppendFolderViewColumnJsonString(json, dummyRoot.generic_wstring());
    json.append(L",\n");
    json.append(std::format(L"  \"itemCount\": {},\n", kItemCount));
    json.append(std::format(L"  \"extensionCount\": {},\n", kExtensionCount));
    json.append(L"  \"latencyModel\": \"1 ms per directory entry enumerated plus one injected slow icon extraction\",\n");
    json.append(std::format(L"  \"expectedProviderDelayUs\": {},\n", kItemCount * 1000u));
    json.append(std::format(L"  \"enumerationUs\": {},\n", enumerationUs));
    json.append(std::format(L"  \"firstPaintUs\": {},\n", firstPaintUs));
    json.append(std::format(L"  \"iconExtractLatencyConsumeCount\": {},\n", iconExtractLatencyConsumeCount));
    json.append(std::format(L"  \"bitmapIconCount\": {},\n", bitmapIconCount));
    json.append(std::format(L"  \"failedLookupFirstUs\": {},\n", firstFailedLookupUs));
    json.append(std::format(L"  \"failedLookupRepeatUs\": {},\n", repeatedFailedLookupUs));
    json.append(std::format(L"  \"iconPathLiveLookupConsumeCount\": {},\n", failedLookupConsumesAfterRepeat));
    json.append(std::format(L"  \"repeatedFailedLookupCount\": {},\n", repeatedFailedLookupCount));
    json.append(std::format(L"  \"thumbnailProviderAllowedLookupUs\": {},\n", thumbnailProviderAllowedLookupUs));
    json.append(std::format(L"  \"thumbnailProviderAllowedConsumeCount\": {},\n", thumbnailProviderAllowedConsumeCount));
    json.append(std::format(L"  \"thumbnailShellProviderAllowedCount\": {},\n", slowThumbnailSnapshot.thumbnailShellProviderAllowedCount));
    json.append(L"  \"pasteShortcutSaveCoverage\": \"cmd_pane_clipboardPasteShortcut_returns_before_worker_complete and "
                L"cmd_pane_clipboardPasteShortcut_close_does_not_wait_for_worker consume SelfTestLatency::Point::PasteShortcutSave\",\n");
    json.append(L"  \"fileExistenceProbeCoverage\": \"Paste Shortcut unique-name exists probes run on the async worker covered by the Paste Shortcut cases; "
                L"the live path icon failure probe above covers the repeated slow-then-fail FolderView icon-index path\",\n");
    AppendFolderViewEnvironmentMatrixJson(json, CaptureFolderViewEnvironmentMatrix(mainWindow), L"  ");
    json.append(L"\n");
    json.append(L"}\n");

    const std::filesystem::path artifactPath = SelfTest::GetPerfArtifactPath(L"folderView_perf_slow_virtual_provider_metrics.json");
    const bool artifactWriteOk               = ! artifactPath.empty() && SelfTest::WriteTextFile(artifactPath, json);
    state.Require(artifactWriteOk && SelfTest::PathExists(artifactPath), L"Failed to write slow virtual FolderView provider perf artifact.");

    if (! state.failure.empty())
    {
        return false;
    }
    return CheckFolderViewPerfBudgets(L"folderView_perf_slow_virtual_provider", metricScanOffset, state);
}

[[nodiscard]] bool TestFolderViewPerfRelayoutChurnWhileScrolled(HWND mainWindow, CaseState& state) noexcept
{
    using namespace std::chrono_literals;

    if (! mainWindow || ! IsWindow(mainWindow))
    {
        state.Require(false, L"Main window handle invalid for FolderView relayout churn perf.");
        return false;
    }

    if (! PrepareMainWindowForIsolatedUiCase(mainWindow, state, L"FolderView relayout churn performance validation"))
    {
        return false;
    }

    FolderViewDummyPluginHandles dummy{};
    state.Require(LoadFolderViewDummyPlugin(state, dummy), L"Failed to load dummy file system for FolderView relayout churn perf.");
    if (! state.failure.empty())
    {
        return false;
    }

    std::string previousDummyConfig;
    state.Require(BackupPluginConfigurationForFolderViewPerf(dummy.informations.get(), previousDummyConfig),
                  L"Failed to snapshot dummy configuration for FolderView relayout churn perf.");
    if (! state.failure.empty())
    {
        return false;
    }
    const auto restoreDummyConfig =
        wil::scope_exit([&]() noexcept { static_cast<void>(SetPluginConfigurationForFolderViewPerf(dummy.informations.get(), previousDummyConfig)); });

    constexpr std::string_view kDeterministicEmptyDummyConfig =
        R"json({"maxChildrenPerDirectory":0,"maxDepth":10,"seed":44,"latencyMs":0,"streamChunkLatencyMs":0,"virtualSpeedLimit":"0"})json";
    state.Require(SetPluginConfigurationForFolderViewPerf(dummy.informations.get(), kDeterministicEmptyDummyConfig),
                  L"Failed to apply deterministic empty dummy configuration for FolderView relayout churn perf.");

    constexpr size_t kItemCount           = 10000u;
    constexpr size_t kExtensionCount      = 24u;
    const std::filesystem::path dummyRoot = std::filesystem::path(L"/folderview-relayout-churn") / SanitizeFolderViewDummyPathSegment(NewGuidText());
    std::wstring firstName;
    std::wstring middleName;
    std::wstring lastName;
    state.Require(MaterializeFolderViewDummyFiles(state, dummy, dummyRoot, kItemCount, kExtensionCount, &firstName, &middleName, &lastName),
                  L"Failed to materialize FolderView relayout churn fixture.");
    if (! state.failure.empty())
    {
        return false;
    }

    const std::wstring leftPluginBefore                   = std::wstring(g_folderWindow.GetFileSystemPluginId(FolderWindow::Pane::Left));
    const std::optional<std::filesystem::path> leftBefore = g_folderWindow.GetCurrentPath(FolderWindow::Pane::Left);
    const FolderView::DisplayMode displayBefore           = g_folderWindow.GetDisplayMode(FolderWindow::Pane::Left);
    const FolderView::SortBy sortBefore                   = g_folderWindow.GetSortBy(FolderWindow::Pane::Left);
    const FolderView::SortDirection directionBefore       = g_folderWindow.GetSortDirection(FolderWindow::Pane::Left);
    const AppTheme originalTheme                          = g_folderWindow.GetTheme();
    const UINT originalWindowDpi                          = GetDpiForWindow(mainWindow);
    const float originalDpi                               = originalWindowDpi > 0u ? static_cast<float>(originalWindowDpi) : 96.0f;
    RECT originalWindowRect{};
    const bool haveOriginalWindowRect = GetWindowRect(mainWindow, &originalWindowRect) != FALSE;
    const auto restorePaneState       = wil::scope_exit([&]() noexcept
    {
        g_folderWindow.ApplyTheme(originalTheme);
        g_folderWindow.OnDpiChanged(originalDpi);
        if (haveOriginalWindowRect)
        {
            SetWindowPos(mainWindow,
                         nullptr,
                         originalWindowRect.left,
                         originalWindowRect.top,
                         originalWindowRect.right - originalWindowRect.left,
                         originalWindowRect.bottom - originalWindowRect.top,
                         SWP_NOZORDER | SWP_NOACTIVATE);
        }
        static_cast<void>(g_folderWindow.SetFileSystemPluginForPane(FolderWindow::Pane::Left, leftPluginBefore));
        g_folderWindow.SetDisplayMode(FolderWindow::Pane::Left, displayBefore);
        g_folderWindow.SetSort(FolderWindow::Pane::Left, sortBefore, directionBefore);
        if (leftBefore.has_value())
        {
            g_folderWindow.SetFolderPath(FolderWindow::Pane::Left, leftBefore.value());
        }
    });

    state.Require(SUCCEEDED(g_folderWindow.SetFileSystemPluginForPane(FolderWindow::Pane::Left, kBuiltinDummyFileSystemIdForFolderViewPerf.data())),
                  L"Failed to switch left pane to dummy file system for FolderView relayout churn perf.");
    g_folderWindow.SetDisplayMode(FolderWindow::Pane::Left, FolderView::DisplayMode::Detailed);
    g_folderWindow.SetSort(FolderWindow::Pane::Left, FolderView::SortBy::Name, FolderView::SortDirection::Ascending);
    g_folderWindow.DebugResetPaneVisibilityState(FolderWindow::Pane::Left);

    std::atomic<uint32_t> enumerationCount{0};
    g_folderWindow.SetPaneEnumerationCompletedCallback(FolderWindow::Pane::Left,
                                                       [&](const std::filesystem::path& folder) noexcept
    {
        if (OrdinalString::EqualsNoCase(folder.generic_wstring(), dummyRoot.generic_wstring()))
        {
            enumerationCount.fetch_add(1u, std::memory_order_release);
        }
    });
    const auto clearEnumCallback = wil::scope_exit([&] { g_folderWindow.SetPaneEnumerationCompletedCallback(FolderWindow::Pane::Left, {}); });

    g_folderWindow.SetFolderPath(FolderWindow::Pane::Left, dummyRoot);
    state.Require(WaitForPanePluginPathForFolderViewPerf(FolderWindow::Pane::Left, dummyRoot, SelfTest::Scale(10000ms)),
                  L"FolderView relayout churn plugin path did not load.");
    state.Require(WaitForAtomicAtLeast(enumerationCount, 1u, SelfTest::Scale(10000ms)), L"FolderView relayout churn enumeration did not complete.");
    state.Require(WaitForFolderViewItemCount(FolderWindow::Pane::Left, kItemCount, SelfTest::Scale(10000ms)),
                  std::format(L"FolderView relayout churn item count mismatch; expected={} actual={}.",
                              kItemCount,
                              g_folderWindow.DebugGetItemCount(FolderWindow::Pane::Left)));
    if (! state.failure.empty())
    {
        return false;
    }

    const HWND folderView = g_folderWindow.GetFolderViewHwnd(FolderWindow::Pane::Left);
    state.Require(folderView && IsWindow(folderView) != FALSE, L"Left FolderView handle unavailable for relayout churn perf.");
    if (! folderView || IsWindow(folderView) == FALSE)
    {
        return false;
    }

    state.Require(g_folderWindow.DebugWarmPaneRendering(FolderWindow::Pane::Left), L"FolderView relayout churn initial warm render failed.");
    FocusFolderViewPane(FolderWindow::Pane::Left);
    state.Require(g_folderWindow.DebugFocusItemByDisplayName(FolderWindow::Pane::Left, lastName),
                  L"FolderView relayout churn failed to focus the last item before measuring scrolled relayout.");
    state.Require(WaitForFolderViewFocusedItem(FolderWindow::Pane::Left, lastName, SelfTest::Scale(3000ms)),
                  L"FolderView relayout churn last item focus did not settle.");
    state.Require(g_folderWindow.DebugWarmPaneRendering(FolderWindow::Pane::Left), L"FolderView relayout churn bottom scroll warm render failed.");
    const FolderView::DebugWarmPerfSnapshot settleBefore = g_folderWindow.DebugGetWarmPanePerfSnapshot(FolderWindow::Pane::Left);
    const bool settled = WaitForFolderViewWarmPerfQuiescence(FolderWindow::Pane::Left, SelfTest::Scale(160ms), SelfTest::Scale(5000ms));
    const FolderView::DebugWarmPerfSnapshot settleAfter = g_folderWindow.DebugGetWarmPanePerfSnapshot(FolderWindow::Pane::Left);
    state.Require(settled,
                  std::format(L"FolderView relayout churn did not settle before measured relayout cycles; "
                              L"warm={0}->{1} deferred={2}->{3} render={4}->{5} queueIcons={6}->{7} processIcons={8}->{9} "
                              L"batchIcons={10}->{11} searchEffects={12}->{13}.",
                              settleBefore.warmRenderingCalls,
                              settleAfter.warmRenderingCalls,
                              settleBefore.deferredInitCalls,
                              settleAfter.deferredInitCalls,
                              settleBefore.renderCalls,
                              settleAfter.renderCalls,
                              settleBefore.queueIconLoadingCalls,
                              settleAfter.queueIconLoadingCalls,
                              settleBefore.processIconQueueCalls,
                              settleAfter.processIconQueueCalls,
                              settleBefore.batchIconUpdateCalls,
                              settleAfter.batchIconUpdateCalls,
                              settleBefore.incrementalSearchEffectUpdates,
                              settleAfter.incrementalSearchEffectUpdates));

    FolderView::DebugColumnLayoutSnapshot scrolledBefore{};
    state.Require(g_folderWindow.DebugGetPaneColumnLayoutSnapshot(FolderWindow::Pane::Left, scrolledBefore),
                  L"FolderView relayout churn failed to capture scrolled baseline snapshot.");
    state.Require(scrolledBefore.firstVisibleIndex > 0u,
                  std::format(L"FolderView relayout churn baseline should be scrolled; firstVisibleIndex={}.", scrolledBefore.firstVisibleIndex));
    if (! state.failure.empty())
    {
        return false;
    }

    std::vector<uint64_t> relayoutUs;
    relayoutUs.reserve(6u);
    const std::uintmax_t relayoutMetricScanOffset                  = FolderViewPerfMetricScanOffset();
    const float alternateDpi                                       = std::abs(originalDpi - 144.0f) > 0.5f ? 144.0f : 120.0f;
    constexpr std::array<ThemeMode, 3> kRelayoutThemes             = {{ThemeMode::Dark, ThemeMode::Light, ThemeMode::HighContrast}};
    constexpr std::array<std::wstring_view, 3> kRelayoutThemeNames = {{L"dark", L"light", L"high-contrast"}};
    for (size_t cycle = 0; cycle < 6u; ++cycle)
    {
        const float dpi                = (cycle % 2u) == 0u ? alternateDpi : originalDpi;
        const size_t themeIndex        = cycle % kRelayoutThemes.size();
        const std::wstring cycleDetail = std::format(L"dpi-{:.0f}:theme-{}:cycle-{}", dpi, kRelayoutThemeNames[themeIndex], cycle);
        const auto relayoutStart       = std::chrono::steady_clock::now();
        auto phaseStart                = std::chrono::steady_clock::now();
        g_folderWindow.OnDpiChanged(dpi);
        Debug::Perf::Emit(L"folder.relayout.dpi_change_us", cycleDetail, Debug::Perf::ElapsedUs(phaseStart), static_cast<uint64_t>(cycle), kItemCount, S_OK);
        phaseStart = std::chrono::steady_clock::now();
        g_folderWindow.ApplyTheme(ResolveAppTheme(kRelayoutThemes[themeIndex], std::format(L"folderview-relayout-churn-{}", cycle)));
        Debug::Perf::Emit(L"folder.relayout.apply_theme_us", cycleDetail, Debug::Perf::ElapsedUs(phaseStart), static_cast<uint64_t>(cycle), kItemCount, S_OK);
        if (haveOriginalWindowRect)
        {
            const int originalWidth  = originalWindowRect.right - originalWindowRect.left;
            const int originalHeight = originalWindowRect.bottom - originalWindowRect.top;
            const int deltaWidth     = (cycle % 2u) == 0u ? 120 : -80;
            phaseStart               = std::chrono::steady_clock::now();
            SetWindowPos(mainWindow,
                         nullptr,
                         originalWindowRect.left,
                         originalWindowRect.top,
                         std::max(640, originalWidth + deltaWidth),
                         std::max(420, originalHeight + static_cast<int>(cycle % 3u) * 20),
                         SWP_NOZORDER | SWP_NOACTIVATE);
            Debug::Perf::Emit(
                L"folder.relayout.set_window_pos_us", cycleDetail, Debug::Perf::ElapsedUs(phaseStart), static_cast<uint64_t>(cycle), kItemCount, S_OK);
        }
        phaseStart = std::chrono::steady_clock::now();
        PumpPendingMessages();
        Debug::Perf::Emit(L"folder.relayout.pump_us", cycleDetail, Debug::Perf::ElapsedUs(phaseStart), static_cast<uint64_t>(cycle), kItemCount, S_OK);
        phaseStart = std::chrono::steady_clock::now();
        RedrawWindow(folderView, nullptr, nullptr, RDW_INVALIDATE | RDW_UPDATENOW | RDW_ALLCHILDREN);
        Debug::Perf::Emit(L"folder.relayout.redraw_us", cycleDetail, Debug::Perf::ElapsedUs(phaseStart), static_cast<uint64_t>(cycle), kItemCount, S_OK);
        phaseStart = std::chrono::steady_clock::now();
        state.Require(g_folderWindow.DebugWarmPaneRendering(FolderWindow::Pane::Left),
                      std::format(L"FolderView relayout churn warm render failed for cycle {}.", cycle));
        Debug::Perf::Emit(L"folder.relayout.warm_render_us", cycleDetail, Debug::Perf::ElapsedUs(phaseStart), static_cast<uint64_t>(cycle), kItemCount, S_OK);
        const uint64_t elapsedUs = Debug::Perf::ElapsedUs(relayoutStart);
        FolderView::DebugColumnLayoutSnapshot snapshot{};
        state.Require(g_folderWindow.DebugGetPaneColumnLayoutSnapshot(FolderWindow::Pane::Left, snapshot),
                      std::format(L"FolderView relayout churn snapshot failed for cycle {}.", cycle));
        state.Require(snapshot.firstVisibleIndex > 0u,
                      std::format(L"FolderView relayout churn cycle {} lost scrolled position; firstVisibleIndex={}.", cycle, snapshot.firstVisibleIndex));
        Debug::Perf::Emit(L"folder.relayout_to_paint_us", cycleDetail, elapsedUs, static_cast<uint64_t>(snapshot.visibleItems.size()), kItemCount, S_OK);
        relayoutUs.push_back(elapsedUs);
        if (! state.failure.empty())
        {
            return false;
        }
        state.Require(WaitForFolderViewWarmPerfQuiescence(FolderWindow::Pane::Left, SelfTest::Scale(80ms), SelfTest::Scale(5000ms)),
                      std::format(L"FolderView relayout churn did not settle after cycle {}.", cycle));
        if (! state.failure.empty())
        {
            return false;
        }
    }

    const uint64_t totalFrameCount   = FolderViewPerfMetricCountInRun(L"folder.frame.total_us", relayoutMetricScanOffset);
    const uint64_t presentFrameCount = FolderViewPerfMetricCountInRun(L"folder.frame.present_us", relayoutMetricScanOffset);
    std::wstring json;
    json.append(L"{\n");
    json.append(L"  \"case\": \"folderView_perf_relayout_churn_while_scrolled\",\n");
    json.append(L"  \"provider\": \"builtin/file-system-dummy\",\n");
    json.append(L"  \"root\": ");
    AppendFolderViewColumnJsonString(json, dummyRoot.generic_wstring());
    json.append(L",\n");
    json.append(std::format(L"  \"itemCount\": {},\n", kItemCount));
    json.append(L"  \"dpiRelayoutCovered\": true,\n");
    json.append(L"  \"themeRelayoutCovered\": true,\n");
    json.append(L"  \"highContrastRelayoutCovered\": true,\n");
    json.append(L"  \"fontRelayoutCovered\": false,\n");
    json.append(L"  \"fontRelayoutOmission\": \"No public selftest font setter exists in this file\",\n");
    json.append(std::format(L"  \"baselineFirstVisibleIndex\": {},\n", scrolledBefore.firstVisibleIndex));
    json.append(std::format(L"  \"baselineLastVisibleIndex\": {},\n", scrolledBefore.lastVisibleIndex));
    json.append(L"  \"relayoutToPaintUs\": [");
    for (size_t i = 0; i < relayoutUs.size(); ++i)
    {
        json.append(std::format(L"{}", relayoutUs[i]));
        json.append(i + 1u < relayoutUs.size() ? L", " : L"");
    }
    json.append(L"],\n");
    json.append(L"  \"metricQuality\": {\n");
    AppendFolderViewMetricQualityJson(json, totalFrameCount, presentFrameCount, L"relayout-burst", L"    ");
    json.append(L"\n");
    json.append(L"  },\n");
    AppendFolderViewEnvironmentMatrixJson(json, CaptureFolderViewEnvironmentMatrix(mainWindow), L"  ");
    json.append(L"\n");
    json.append(L"}\n");

    const std::filesystem::path artifactPath = SelfTest::GetPerfArtifactPath(L"folderView_perf_relayout_churn_while_scrolled_metrics.json");
    const bool artifactWriteOk               = ! artifactPath.empty() && SelfTest::WriteTextFile(artifactPath, json);
    state.Require(artifactWriteOk && SelfTest::PathExists(artifactPath), L"Failed to write FolderView relayout churn perf artifact.");

    if (! state.failure.empty())
    {
        return false;
    }
    return CheckFolderViewPerfBudgets(L"folderView_perf_relayout_churn_while_scrolled", relayoutMetricScanOffset, state);
}

[[nodiscard]] bool TestFolderViewPerfDirectoryChangeStorm(HWND mainWindow, CaseState& state) noexcept
{
    using namespace std::chrono_literals;

    if (! mainWindow || ! IsWindow(mainWindow))
    {
        state.Require(false, L"Main window handle invalid for directory-change storm.");
        return false;
    }

    const std::filesystem::path suiteRoot = SelfTest::GetTempRoot(SelfTest::SelfTestSuite::Commands);
    state.Require(! suiteRoot.empty(), L"SelfTest temp root unavailable for directory-change storm.");
    if (suiteRoot.empty())
    {
        return false;
    }

    const std::filesystem::path root = suiteRoot / L"work" / (L"folder_directory_change_storm_" + NewGuidText());
    std::error_code ec;
    std::filesystem::remove_all(root, ec);
    state.Require(SelfTest::EnsureDirectory(root), L"Failed to create directory-change storm root.");
    state.Require(SelfTest::WriteTextFile(root / L"focus_anchor.txt", "anchor"), L"Failed to create directory-change storm focus anchor.");
    if (! state.failure.empty())
    {
        return false;
    }

    const std::wstring leftPluginBefore                   = std::wstring(g_folderWindow.GetFileSystemPluginId(FolderWindow::Pane::Left));
    const std::optional<std::filesystem::path> leftBefore = g_folderWindow.GetCurrentPath(FolderWindow::Pane::Left);
    const FolderView::DisplayMode displayBefore           = g_folderWindow.GetDisplayMode(FolderWindow::Pane::Left);
    const FolderView::SortBy sortBefore                   = g_folderWindow.GetSortBy(FolderWindow::Pane::Left);
    const FolderView::SortDirection directionBefore       = g_folderWindow.GetSortDirection(FolderWindow::Pane::Left);
    const auto restoreState                               = wil::scope_exit([&]
    {
        static_cast<void>(g_folderWindow.SetFileSystemPluginForPane(FolderWindow::Pane::Left, leftPluginBefore));
        g_folderWindow.SetDisplayMode(FolderWindow::Pane::Left, displayBefore);
        g_folderWindow.SetSort(FolderWindow::Pane::Left, sortBefore, directionBefore);
        if (leftBefore.has_value())
        {
            g_folderWindow.SetFolderPath(FolderWindow::Pane::Left, leftBefore.value());
        }
    });

    state.Require(SUCCEEDED(g_folderWindow.SetFileSystemPluginForPane(FolderWindow::Pane::Left, L"builtin/file-system")),
                  L"Failed to switch left pane to local file system for directory-change storm.");
    g_folderWindow.SetDisplayMode(FolderWindow::Pane::Left, FolderView::DisplayMode::Detailed);
    g_folderWindow.SetSort(FolderWindow::Pane::Left, FolderView::SortBy::Name, FolderView::SortDirection::Ascending);
    g_folderWindow.DebugResetPaneVisibilityState(FolderWindow::Pane::Left);

    std::atomic<uint32_t> enumerationCount{0};
    g_folderWindow.SetPaneEnumerationCompletedCallback(FolderWindow::Pane::Left,
                                                       [&](const std::filesystem::path& folder) noexcept
    {
        if (OrdinalString::EqualsNoCasePath(folder, root))
        {
            enumerationCount.fetch_add(1u, std::memory_order_release);
        }
    });
    const auto clearEnumCallback = wil::scope_exit([&] { g_folderWindow.SetPaneEnumerationCompletedCallback(FolderWindow::Pane::Left, {}); });

    g_folderWindow.SetFolderPath(FolderWindow::Pane::Left, root);
    state.Require(WaitForPanePath(FolderWindow::Pane::Left, root, SelfTest::Scale(5000ms)), L"Directory-change storm path did not load.");
    state.Require(WaitForAtomicAtLeast(enumerationCount, 1u, SelfTest::Scale(5000ms)), L"Initial directory-change storm enumeration did not complete.");
    state.Require(WaitForPaneItems(FolderWindow::Pane::Left, {L"focus_anchor.txt"}, SelfTest::Scale(5000ms)), L"Directory-change storm anchor did not load.");
    state.Require(g_folderWindow.DebugFocusItemByDisplayName(FolderWindow::Pane::Left, L"focus_anchor.txt"), L"Failed to focus directory-change storm anchor.");
    state.Require(WaitForFolderViewFocusedItem(FolderWindow::Pane::Left, L"focus_anchor.txt", SelfTest::Scale(2000ms)),
                  L"Directory-change storm anchor focus did not settle.");
    if (! state.failure.empty())
    {
        return false;
    }

    const std::uintmax_t metricScanOffset = FolderViewPerfMetricScanOffset();
    const uint64_t refreshBefore          = g_folderWindow.DebugGetForceRefreshCount(FolderWindow::Pane::Left);
    const auto mutationStart              = std::chrono::steady_clock::now();

    for (size_t i = 0; i < 200u; ++i)
    {
        const std::wstring name = std::format(L"storm_create_{:03}.txt", i);
        state.Require(SelfTest::WriteTextFile(root / name, "storm create"), std::format(L"Failed to create {}.", name));
    }

    for (size_t i = 0; i < 100u; ++i)
    {
        const std::filesystem::path source = root / std::format(L"storm_create_{:03}.txt", i);
        const std::filesystem::path target = root / std::format(L"storm_renamed_{:03}.txt", i);
        std::error_code renameError;
        std::filesystem::rename(source, target, renameError);
        state.Require(! renameError, std::format(L"Failed to rename storm file {} (ec={}).", i, renameError.value()));
    }

    for (size_t i = 100u; i < 200u; ++i)
    {
        const std::filesystem::path file = root / std::format(L"storm_create_{:03}.txt", i);
        std::error_code removeError;
        const bool removed = std::filesystem::remove(file, removeError);
        state.Require(removed && ! removeError, std::format(L"Failed to delete storm file {} (removed={} ec={}).", i, removed, removeError.value()));
    }

    for (size_t i = 0; i < 20u; ++i)
    {
        const std::filesystem::path dir = root / std::format(L"storm_dir_{:03}", i);
        state.Require(SelfTest::EnsureDirectory(dir), std::format(L"Failed to create storm directory {}.", i));
        std::error_code removeDirError;
        const bool removed = std::filesystem::remove(dir, removeDirError);
        state.Require(removed && ! removeDirError, std::format(L"Failed to delete storm directory {} (removed={} ec={}).", i, removed, removeDirError.value()));
    }

    const auto mutationUs =
        static_cast<uint64_t>(std::chrono::duration_cast<std::chrono::microseconds>(std::chrono::steady_clock::now() - mutationStart).count());
    if (! state.failure.empty())
    {
        return false;
    }

    const auto settleStart = std::chrono::steady_clock::now();
    const bool settled =
        WaitForPaneItems(FolderWindow::Pane::Left, {L"focus_anchor.txt", L"storm_renamed_000.txt", L"storm_renamed_099.txt"}, SelfTest::Scale(15000ms)) &&
        WaitForFolderViewItemCount(FolderWindow::Pane::Left, 101u, SelfTest::Scale(15000ms)) &&
        WaitForFolderViewFocusedItem(FolderWindow::Pane::Left, L"focus_anchor.txt", SelfTest::Scale(5000ms));
    const auto settleUs = static_cast<uint64_t>(std::chrono::duration_cast<std::chrono::microseconds>(std::chrono::steady_clock::now() - settleStart).count());

    state.Require(settled,
                  std::format(L"Directory-change storm did not settle. itemCount={} focus='{}' refreshDelta={} enumCount={}.",
                              g_folderWindow.DebugGetItemCount(FolderWindow::Pane::Left),
                              g_folderWindow.DebugGetFocusedItemDisplayName(FolderWindow::Pane::Left),
                              g_folderWindow.DebugGetForceRefreshCount(FolderWindow::Pane::Left) - refreshBefore,
                              enumerationCount.load(std::memory_order_acquire)));
    state.Require(! g_folderWindow.DebugHasItemDisplayName(FolderWindow::Pane::Left, L"storm_create_100.txt"),
                  L"Directory-change storm should not show deleted file storm_create_100.txt.");
    state.Require(g_folderWindow.DebugWarmPaneRendering(FolderWindow::Pane::Left), L"Directory-change storm warm render failed after settle.");
    if (! state.failure.empty())
    {
        return false;
    }

    const uint64_t preserveMetricCount       = FolderViewPerfMetricCountInRun(L"folder.refresh.preserve_count", metricScanOffset);
    const uint64_t rebuildMetricCount        = FolderViewPerfMetricCountInRun(L"folder.refresh.rebuild_count", metricScanOffset);
    const uint64_t selectionMetricCount      = FolderViewPerfMetricCountInRun(L"folder.refresh.selection_preserve_count", metricScanOffset);
    const uint64_t renameTransferMetricCount = FolderViewPerfMetricCountInRun(L"folder.refresh.rename_transfer_count", metricScanOffset);
    const uint64_t requestToPaintMetricCount = FolderViewPerfMetricCountInRun(L"folder.refresh.request_to_paint_us", metricScanOffset);
    const uint64_t debounceDelayMetricCount  = FolderViewPerfMetricCountInRun(L"folder.refresh.debounce_delay_ms", metricScanOffset);
    const uint64_t enumerationMetricCount    = FolderViewPerfMetricCountInRun(L"folder.refresh.enumeration_count", metricScanOffset);
    state.Require(preserveMetricCount > 0u, L"Directory-change storm missing folder.refresh.preserve_count metric.");
    state.Require(rebuildMetricCount > 0u, L"Directory-change storm missing folder.refresh.rebuild_count metric.");
    state.Require(selectionMetricCount > 0u, L"Directory-change storm missing folder.refresh.selection_preserve_count metric.");
    state.Require(renameTransferMetricCount > 0u, L"Directory-change storm missing folder.refresh.rename_transfer_count metric.");
    state.Require(requestToPaintMetricCount > 0u, L"Directory-change storm missing folder.refresh.request_to_paint_us metric.");
    state.Require(debounceDelayMetricCount > 0u, L"Directory-change storm missing folder.refresh.debounce_delay_ms metric.");
    state.Require(enumerationMetricCount > 0u, L"Directory-change storm missing folder.refresh.enumeration_count metric.");
    if (! state.failure.empty())
    {
        return false;
    }

    const uint64_t refreshDelta = g_folderWindow.DebugGetForceRefreshCount(FolderWindow::Pane::Left) - refreshBefore;
    Debug::Perf::Emit(L"directorycache.post_refresh_count",
                      L"folderView_perf_directory_change_storm",
                      0,
                      refreshDelta,
                      enumerationCount.load(std::memory_order_acquire),
                      S_OK);
    Debug::Perf::Emit(L"folder.directory_change_storm_mutation_us", L"create=200 rename=100 delete=100 dirs=20", mutationUs, 200, 100, S_OK);
    Debug::Perf::Emit(
        L"folder.directory_change_storm_settle_us", L"final_items=101", settleUs, refreshDelta, enumerationCount.load(std::memory_order_acquire), S_OK);

    std::wstring json;
    json.append(L"{\n");
    json.append(L"  \"case\": \"folderView_perf_directory_change_storm\",\n");
    json.append(L"  \"root\": ");
    AppendFolderViewColumnJsonString(json, root.native());
    json.append(L",\n");
    json.append(L"  \"createdFiles\": 200,\n");
    json.append(L"  \"renamedFiles\": 100,\n");
    json.append(L"  \"deletedFiles\": 100,\n");
    json.append(L"  \"createdAndDeletedDirectories\": 20,\n");
    json.append(L"  \"finalItemCount\": 101,\n");
    json.append(std::format(L"  \"mutationUs\": {},\n", mutationUs));
    json.append(std::format(L"  \"settleUs\": {},\n", settleUs));
    json.append(std::format(L"  \"refreshDelta\": {},\n", refreshDelta));
    json.append(std::format(L"  \"enumerationCount\": {},\n", enumerationCount.load(std::memory_order_acquire)));
    json.append(L"  \"focusedItem\": ");
    AppendFolderViewColumnJsonString(json, g_folderWindow.DebugGetFocusedItemDisplayName(FolderWindow::Pane::Left));
    json.append(L",\n");
    json.append(L"  \"refreshMetricRows\": {\n");
    json.append(std::format(L"    \"preserve\": {},\n", preserveMetricCount));
    json.append(std::format(L"    \"rebuild\": {},\n", rebuildMetricCount));
    json.append(std::format(L"    \"selectionPreserve\": {},\n", selectionMetricCount));
    json.append(std::format(L"    \"renameTransfer\": {},\n", renameTransferMetricCount));
    json.append(std::format(L"    \"requestToPaint\": {},\n", requestToPaintMetricCount));
    json.append(std::format(L"    \"debounceDelay\": {},\n", debounceDelayMetricCount));
    json.append(std::format(L"    \"enumeration\": {}\n", enumerationMetricCount));
    json.append(L"  }\n");
    json.append(L"}\n");

    const std::filesystem::path artifactPath = SelfTest::GetPerfArtifactPath(L"folderView_perf_directory_change_storm_metrics.json");
    const bool artifactWriteOk               = ! artifactPath.empty() && SelfTest::WriteTextFile(artifactPath, json);
    state.Require(artifactWriteOk && SelfTest::PathExists(artifactPath), L"Failed to write directory-change storm perf artifact.");

    return state.failure.empty();
}

[[nodiscard]] bool TestFolderViewPerfRefreshPreservation(HWND mainWindow, CaseState& state) noexcept
{
    using namespace std::chrono_literals;

    if (! mainWindow || ! IsWindow(mainWindow))
    {
        state.Require(false, L"Main window handle invalid for refresh-preservation perf test.");
        return false;
    }

    if (! PrepareMainWindowForIsolatedUiCase(mainWindow, state, L"FolderView refresh-preservation performance validation"))
    {
        return false;
    }

    const std::filesystem::path suiteRoot = SelfTest::GetTempRoot(SelfTest::SelfTestSuite::Commands);
    state.Require(! suiteRoot.empty(), L"SelfTest temp root unavailable for refresh-preservation perf test.");
    if (suiteRoot.empty())
    {
        return false;
    }

    const std::filesystem::path root = suiteRoot / L"work" / (L"folder_refresh_preservation_" + NewGuidText());
    std::error_code ec;
    std::filesystem::remove_all(root, ec);
    state.Require(SelfTest::EnsureDirectory(root), L"Failed to create refresh-preservation root.");
    state.Require(SelfTest::WriteTextFile(root / L"focus_anchor.txt", "anchor"), L"Failed to create focus anchor.");
    state.Require(SelfTest::WriteTextFile(root / L"selected_keep.txt", "selected keep"), L"Failed to create selected keep file.");
    state.Require(SelfTest::WriteTextFile(root / L"rename_from.txt", "rename source"), L"Failed to create rename source.");
    state.Require(SelfTest::WriteTextFile(root / L"delete_me.txt", "delete me"), L"Failed to create delete target.");
    for (size_t i = 0; i < 8u; ++i)
    {
        state.Require(SelfTest::WriteTextFile(root / std::format(L"burst_seed_{:02}.txt", i), "burst seed"),
                      std::format(L"Failed to create burst seed {}.", i));
    }
    if (! state.failure.empty())
    {
        return false;
    }

    const std::wstring leftPluginBefore                   = std::wstring(g_folderWindow.GetFileSystemPluginId(FolderWindow::Pane::Left));
    const std::optional<std::filesystem::path> leftBefore = g_folderWindow.GetCurrentPath(FolderWindow::Pane::Left);
    const FolderView::DisplayMode displayBefore           = g_folderWindow.GetDisplayMode(FolderWindow::Pane::Left);
    const FolderView::SortBy sortBefore                   = g_folderWindow.GetSortBy(FolderWindow::Pane::Left);
    const FolderView::SortDirection directionBefore       = g_folderWindow.GetSortDirection(FolderWindow::Pane::Left);
    const auto restoreState                               = wil::scope_exit([&]
    {
        static_cast<void>(g_folderWindow.SetFileSystemPluginForPane(FolderWindow::Pane::Left, leftPluginBefore));
        g_folderWindow.SetDisplayMode(FolderWindow::Pane::Left, displayBefore);
        g_folderWindow.SetSort(FolderWindow::Pane::Left, sortBefore, directionBefore);
        if (leftBefore.has_value())
        {
            g_folderWindow.SetFolderPath(FolderWindow::Pane::Left, leftBefore.value());
        }
    });

    state.Require(SUCCEEDED(g_folderWindow.SetFileSystemPluginForPane(FolderWindow::Pane::Left, L"builtin/file-system")),
                  L"Failed to switch left pane to local file system for refresh-preservation perf test.");
    g_folderWindow.SetDisplayMode(FolderWindow::Pane::Left, FolderView::DisplayMode::Detailed);
    g_folderWindow.SetSort(FolderWindow::Pane::Left, FolderView::SortBy::Name, FolderView::SortDirection::Ascending);
    g_folderWindow.DebugResetPaneVisibilityState(FolderWindow::Pane::Left);

    std::atomic<uint32_t> enumerationCount{0};
    g_folderWindow.SetPaneEnumerationCompletedCallback(FolderWindow::Pane::Left,
                                                       [&](const std::filesystem::path& folder) noexcept
    {
        if (OrdinalString::EqualsNoCasePath(folder, root))
        {
            enumerationCount.fetch_add(1u, std::memory_order_release);
        }
    });
    const auto clearEnumCallback = wil::scope_exit([&] { g_folderWindow.SetPaneEnumerationCompletedCallback(FolderWindow::Pane::Left, {}); });

    g_folderWindow.SetFolderPath(FolderWindow::Pane::Left, root);
    state.Require(WaitForPanePath(FolderWindow::Pane::Left, root, SelfTest::Scale(5000ms)), L"Refresh-preservation path did not load.");
    state.Require(WaitForAtomicAtLeast(enumerationCount, 1u, SelfTest::Scale(5000ms)), L"Initial refresh-preservation enumeration did not complete.");
    state.Require(
        WaitForPaneItems(FolderWindow::Pane::Left, {L"focus_anchor.txt", L"selected_keep.txt", L"rename_from.txt", L"delete_me.txt"}, SelfTest::Scale(5000ms)),
        L"Refresh-preservation seed items did not load.");
    state.Require(g_folderWindow.DebugFocusItemByDisplayName(FolderWindow::Pane::Left, L"focus_anchor.txt"), L"Failed to focus refresh-preservation anchor.");
    state.Require(WaitForFolderViewFocusedItem(FolderWindow::Pane::Left, L"focus_anchor.txt", SelfTest::Scale(2000ms)),
                  L"Refresh-preservation focus did not settle before mutation.");
    g_folderWindow.SetPaneSelectionByDisplayNamePredicate(
        FolderWindow::Pane::Left, [](std::wstring_view name) noexcept { return name == L"selected_keep.txt" || name == L"rename_from.txt"; }, true);
    state.Require(g_folderWindow.DebugGetSelectedCount(FolderWindow::Pane::Left) == 2u, L"Expected two selected items before refresh.");

    HWND folderView = g_folderWindow.GetFolderViewHwnd(FolderWindow::Pane::Left);
    state.Require(folderView && IsWindow(folderView), L"Refresh-preservation FolderView hwnd unavailable.");
    FocusFolderViewPane(FolderWindow::Pane::Left);
    state.Require(WaitForFolderViewPaneFocus(FolderWindow::Pane::Left, folderView, SelfTest::Scale(1000ms)),
                  L"Refresh-preservation FolderView did not receive focus before quick search.");
    state.Require(ClearSyntheticTextInputModifiersForFolderViewPerf(), L"Refresh-preservation FolderView could not clear synthetic text-input modifiers.");
    if (! state.failure.empty())
    {
        return false;
    }
    g_folderWindow.CommandQuickSearch(FolderWindow::Pane::Left);
    FolderView::IncrementalSearchDebugSnapshot searchSnapshot{};
    state.Require(WaitForFolderViewQuickSearchSnapshot(FolderWindow::Pane::Left,
                                                       [](const FolderView::IncrementalSearchDebugSnapshot& value) noexcept
    { return value.active && value.query.empty(); },
                                                       SelfTest::Scale(1000ms),
                                                       &searchSnapshot),
                  std::format(L"Refresh-preservation quick search did not activate cleanly; active={} query='{}'.",
                              searchSnapshot.active ? L"yes" : L"no",
                              searchSnapshot.query));
    if (! state.failure.empty())
    {
        return false;
    }

    for (const wchar_t ch : std::wstring_view(L"focus"))
    {
        state.Require(SendFolderViewQuickSearchCharForPerf(folderView, ch),
                      L"Refresh-preservation FolderView could not clear synthetic modifiers before quick-search input.");
        if (! state.failure.empty())
        {
            return false;
        }
    }
    state.Require(WaitForFolderViewQuickSearchSnapshot(FolderWindow::Pane::Left,
                                                       [](const FolderView::IncrementalSearchDebugSnapshot& value) noexcept
    { return value.active && value.query == L"focus"; },
                                                       SelfTest::Scale(1500ms),
                                                       &searchSnapshot),
                  std::format(L"Expected active query 'focus' before mutation, got active={} query='{}'.", searchSnapshot.active, searchSnapshot.query));
    state.Require(g_folderWindow.DebugWarmPaneRendering(FolderWindow::Pane::Left), L"Refresh-preservation quick-search warm render failed before mutation.");
    if (! state.failure.empty())
    {
        return false;
    }

    const std::uintmax_t metricScanOffset = FolderViewPerfMetricScanOffset();
    const uint32_t enumBefore             = enumerationCount.load(std::memory_order_acquire);
    const uint64_t refreshBefore          = g_folderWindow.DebugGetForceRefreshCount(FolderWindow::Pane::Left);
    wil::com_ptr<IFileSystem> fileSystem  = g_folderWindow.GetFileSystem(FolderWindow::Pane::Left);
    state.Require(fileSystem != nullptr, L"Refresh-preservation file-system provider unavailable.");

    const std::filesystem::path createdPath    = root / L"created_one.txt";
    const std::filesystem::path deletedPath    = root / L"delete_me.txt";
    const std::filesystem::path renameFromPath = root / L"rename_from.txt";
    const std::filesystem::path renameToPath   = root / L"rename_to.txt";

    const auto mutationStart = std::chrono::steady_clock::now();
    state.Require(SelfTest::WriteTextFile(createdPath, "created"), L"Failed to create refresh-preservation file.");
    DirectoryInfoCache::GetInstance().NotifyPathCreated(fileSystem.get(), createdPath);

    std::error_code removeError;
    const bool removed = std::filesystem::remove(deletedPath, removeError);
    state.Require(removed && ! removeError, std::format(L"Failed to delete refresh-preservation file (removed={} ec={}).", removed, removeError.value()));
    DirectoryInfoCache::GetInstance().NotifyPathDeleted(fileSystem.get(), deletedPath);

    std::error_code renameError;
    std::filesystem::rename(renameFromPath, renameToPath, renameError);
    state.Require(! renameError, std::format(L"Failed to rename refresh-preservation file (ec={}).", renameError.value()));
    DirectoryInfoCache::GetInstance().NotifyPathMoved(fileSystem.get(), renameFromPath, renameToPath);

    for (size_t i = 0; i < 8u; ++i)
    {
        const std::filesystem::path burstCreate = root / std::format(L"burst_created_{:02}.txt", i);
        state.Require(SelfTest::WriteTextFile(burstCreate, "burst created"), std::format(L"Failed to create burst file {}.", i));
        DirectoryInfoCache::GetInstance().NotifyPathCreated(fileSystem.get(), burstCreate);

        const std::filesystem::path burstDelete = root / std::format(L"burst_seed_{:02}.txt", i);
        std::error_code burstRemoveError;
        const bool burstRemoved = std::filesystem::remove(burstDelete, burstRemoveError);
        state.Require(burstRemoved && ! burstRemoveError,
                      std::format(L"Failed to delete burst seed {} (removed={} ec={}).", i, burstRemoved, burstRemoveError.value()));
        DirectoryInfoCache::GetInstance().NotifyPathDeleted(fileSystem.get(), burstDelete);
    }
    const uint64_t mutationUs = Debug::Perf::ElapsedUs(mutationStart);
    if (! state.failure.empty())
    {
        return false;
    }

    const auto settleStart  = std::chrono::steady_clock::now();
    const bool settled      = WaitForAtomicAtLeast(enumerationCount, enumBefore + 1u, SelfTest::Scale(10000ms)) &&
                              WaitForPaneItems(FolderWindow::Pane::Left,
                                               {L"focus_anchor.txt", L"selected_keep.txt", L"rename_to.txt", L"created_one.txt"},
                                               SelfTest::Scale(10000ms)) &&
                              WaitForFolderViewItemCount(FolderWindow::Pane::Left, 12u, SelfTest::Scale(10000ms)) &&
                              WaitForFolderViewFocusedItem(FolderWindow::Pane::Left, L"focus_anchor.txt", SelfTest::Scale(5000ms));
    const uint64_t settleUs = Debug::Perf::ElapsedUs(settleStart);
    state.Require(settled,
                  std::format(L"Refresh-preservation mutation did not settle. itemCount={} focus='{}' refreshDelta={} enumCount={}.",
                              g_folderWindow.DebugGetItemCount(FolderWindow::Pane::Left),
                              g_folderWindow.DebugGetFocusedItemDisplayName(FolderWindow::Pane::Left),
                              g_folderWindow.DebugGetForceRefreshCount(FolderWindow::Pane::Left) - refreshBefore,
                              enumerationCount.load(std::memory_order_acquire)));
    state.Require(! g_folderWindow.DebugHasItemDisplayName(FolderWindow::Pane::Left, L"delete_me.txt"), L"Refresh-preservation should not show deleted file.");
    state.Require(! g_folderWindow.DebugHasItemDisplayName(FolderWindow::Pane::Left, L"rename_from.txt"),
                  L"Refresh-preservation should not show renamed source.");
    state.Require(g_folderWindow.DebugIsItemSelected(FolderWindow::Pane::Left, L"selected_keep.txt"),
                  L"Refresh-preservation should keep unchanged selected item selected.");
    state.Require(g_folderWindow.DebugIsItemSelected(FolderWindow::Pane::Left, L"rename_to.txt"),
                  L"Refresh-preservation should transfer selection to renamed item.");
    state.Require(g_folderWindow.DebugGetSelectedCount(FolderWindow::Pane::Left) == 2u,
                  std::format(L"Refresh-preservation expected two selected items, got {}.", g_folderWindow.DebugGetSelectedCount(FolderWindow::Pane::Left)));
    state.Require(g_folderWindow.DebugGetIncrementalSearchSnapshot(FolderWindow::Pane::Left, searchSnapshot),
                  L"Refresh-preservation search snapshot unavailable after mutation.");
    state.Require(searchSnapshot.active && searchSnapshot.query == L"focus",
                  std::format(L"Expected active query 'focus' after mutation, got active={} query='{}'.", searchSnapshot.active, searchSnapshot.query));
    state.Require(g_folderWindow.DebugWarmPaneRendering(FolderWindow::Pane::Left), L"Refresh-preservation warm render failed.");
    if (! state.failure.empty())
    {
        return false;
    }

    const uint64_t refreshDelta = g_folderWindow.DebugGetForceRefreshCount(FolderWindow::Pane::Left) - refreshBefore;
    Debug::Perf::Emit(L"folder.refresh_preservation_mutation_us", L"create=1 delete=1 rename=1 burst=16", mutationUs, 1, 16, S_OK);
    Debug::Perf::Emit(
        L"folder.refresh_preservation_settle_us", L"final_items=12", settleUs, refreshDelta, enumerationCount.load(std::memory_order_acquire), S_OK);

    const uint64_t preserveMetricCount       = FolderViewPerfMetricCountInRun(L"folder.refresh.preserve_count", metricScanOffset);
    const uint64_t rebuildMetricCount        = FolderViewPerfMetricCountInRun(L"folder.refresh.rebuild_count", metricScanOffset);
    const uint64_t selectionMetricCount      = FolderViewPerfMetricCountInRun(L"folder.refresh.selection_preserve_count", metricScanOffset);
    const uint64_t renameTransferMetricCount = FolderViewPerfMetricCountInRun(L"folder.refresh.rename_transfer_count", metricScanOffset);
    const uint64_t requestToPaintMetricCount = FolderViewPerfMetricCountInRun(L"folder.refresh.request_to_paint_us", metricScanOffset);
    const uint64_t debounceDelayMetricCount  = FolderViewPerfMetricCountInRun(L"folder.refresh.debounce_delay_ms", metricScanOffset);
    const uint64_t enumerationMetricCount    = FolderViewPerfMetricCountInRun(L"folder.refresh.enumeration_count", metricScanOffset);
    state.Require(preserveMetricCount > 0u, L"Missing folder.refresh.preserve_count metric.");
    state.Require(rebuildMetricCount > 0u, L"Missing folder.refresh.rebuild_count metric.");
    state.Require(selectionMetricCount > 0u, L"Missing folder.refresh.selection_preserve_count metric.");
    state.Require(renameTransferMetricCount > 0u, L"Missing folder.refresh.rename_transfer_count metric.");
    state.Require(requestToPaintMetricCount > 0u, L"Missing folder.refresh.request_to_paint_us metric.");
    state.Require(debounceDelayMetricCount > 0u, L"Missing folder.refresh.debounce_delay_ms metric.");
    state.Require(enumerationMetricCount > 0u, L"Missing folder.refresh.enumeration_count metric.");

    std::wstring json;
    json.append(L"{\n");
    json.append(L"  \"case\": \"folderView_perf_refresh_preservation\",\n");
    json.append(L"  \"root\": ");
    AppendFolderViewColumnJsonString(json, root.native());
    json.append(L",\n");
    json.append(L"  \"createdFiles\": 1,\n");
    json.append(L"  \"deletedFiles\": 1,\n");
    json.append(L"  \"renamedFiles\": 1,\n");
    json.append(L"  \"burstCreates\": 8,\n");
    json.append(L"  \"burstDeletes\": 8,\n");
    json.append(L"  \"finalItemCount\": 12,\n");
    json.append(std::format(L"  \"mutationUs\": {},\n", mutationUs));
    json.append(std::format(L"  \"settleUs\": {},\n", settleUs));
    json.append(std::format(L"  \"refreshDelta\": {},\n", refreshDelta));
    json.append(std::format(L"  \"enumerationCount\": {},\n", enumerationCount.load(std::memory_order_acquire)));
    json.append(std::format(L"  \"selectedCount\": {},\n", g_folderWindow.DebugGetSelectedCount(FolderWindow::Pane::Left)));
    json.append(L"  \"focusedItem\": ");
    AppendFolderViewColumnJsonString(json, g_folderWindow.DebugGetFocusedItemDisplayName(FolderWindow::Pane::Left));
    json.append(L",\n");
    json.append(L"  \"incrementalSearchQuery\": ");
    AppendFolderViewColumnJsonString(json, searchSnapshot.query);
    json.append(L",\n");
    json.append(L"  \"refreshMetricRows\": {\n");
    json.append(std::format(L"    \"preserve\": {},\n", preserveMetricCount));
    json.append(std::format(L"    \"rebuild\": {},\n", rebuildMetricCount));
    json.append(std::format(L"    \"selectionPreserve\": {},\n", selectionMetricCount));
    json.append(std::format(L"    \"renameTransfer\": {},\n", renameTransferMetricCount));
    json.append(std::format(L"    \"requestToPaint\": {},\n", requestToPaintMetricCount));
    json.append(std::format(L"    \"debounceDelay\": {},\n", debounceDelayMetricCount));
    json.append(std::format(L"    \"enumeration\": {}\n", enumerationMetricCount));
    json.append(L"  }\n");
    json.append(L"}\n");

    const std::filesystem::path artifactPath = SelfTest::GetPerfArtifactPath(L"folderView_perf_refresh_preservation_metrics.json");
    const bool artifactWriteOk               = ! artifactPath.empty() && SelfTest::WriteTextFile(artifactPath, json);
    state.Require(artifactWriteOk && SelfTest::PathExists(artifactPath), L"Failed to write refresh-preservation perf artifact.");

    return state.failure.empty();
}

[[nodiscard]] bool CreateFolderViewIconPipelineLocalFixture(CaseState& state, const std::filesystem::path& root, std::vector<std::wstring>& probeNames) noexcept
{
    state.Require(SelfTest::EnsureDirectory(root), L"Failed to create icon-pipeline local fixture root.");
    if (! state.failure.empty())
    {
        return false;
    }

    static constexpr std::array<std::wstring_view, 9> kPerFileExtensions{{
        L".exe",
        L".dll",
        L".ico",
        L".lnk",
        L".url",
        L".cpl",
        L".scr",
        L".msc",
        L".ocx",
    }};

    probeNames.clear();
    probeNames.reserve(kPerFileExtensions.size());
    for (size_t i = 0; i < kPerFileExtensions.size(); ++i)
    {
        const std::wstring name = std::format(L"visible_icon_pipeline_{:02}{}", i, kPerFileExtensions[i]);
        const std::string text  = std::format("icon pipeline fixture {}\r\n", i);
        state.Require(SelfTest::WriteTextFile(root / name, text), std::format(L"Failed to create icon-pipeline fixture item '{}'.", name));
        probeNames.push_back(name);
    }

    return state.failure.empty();
}

[[nodiscard]] bool TestFolderViewIconCacheLivePathFailureUsesBoundedBackoff(HWND /*mainWindow*/, CaseState& state) noexcept
{
    using namespace std::chrono_literals;

    const std::filesystem::path suiteRoot = SelfTest::GetTempRoot(SelfTest::SelfTestSuite::Commands);
    state.Require(! suiteRoot.empty(), L"SelfTest temp root unavailable for live icon lookup failure recovery.");
    if (suiteRoot.empty())
    {
        return false;
    }

    std::error_code ec;
    const std::filesystem::path root      = suiteRoot / L"work" / (L"iconcache_live_failure_retry_" + NewGuidText());
    const std::filesystem::path probePath = root / L"transient-live-icon.txt";
    std::filesystem::remove_all(root, ec);
    ec.clear();
    state.Require(SelfTest::EnsureDirectory(root), L"Failed to create live icon lookup failure recovery root.");
    state.Require(SelfTest::WriteTextFile(probePath, "transient live icon lookup"), L"Failed to write live icon lookup probe file.");
    state.Require(std::filesystem::exists(probePath, ec) && ! ec, L"Live icon lookup probe file should exist.");
    if (! state.failure.empty())
    {
        return false;
    }

    SelfTestLatency::ClearAll();
    auto cleanup                               = wil::scope_exit([] { SelfTestLatency::ClearAll(); });
    constexpr uint64_t kRefreshesInsideBackoff = 8u;
    for (uint64_t refreshIndex = 0u; refreshIndex < kRefreshesInsideBackoff; ++refreshIndex)
    {
        IconCache::GetInstance().Clear();
        SelfTestLatency::SetNextFailure(SelfTestLatency::Point::IconPathLiveLookup, E_ACCESSDENIED);
        const std::optional<int> baselineIcon = IconCache::GetInstance().QuerySysIconIndexForPath(probePath.c_str(), FILE_ATTRIBUTE_NORMAL, false);
        state.Require(! baselineIcon.has_value(), L"Uncached baseline live icon lookup should consume the forced shell failure.");
    }
    const uint64_t baselineShellLookups = SelfTestLatency::ConsumeCount(SelfTestLatency::Point::IconPathLiveLookup);
    state.Require(
        baselineShellLookups == kRefreshesInsideBackoff,
        std::format(L"Uncached baseline should issue one shell lookup per refresh; refreshes={} lookups={}.", kRefreshesInsideBackoff, baselineShellLookups));

    IconCache::GetInstance().Clear();
    SelfTestLatency::ClearAll();
    const std::uintmax_t metricScanOffset = FolderViewPerfMetricScanOffset();
    const auto firstBackoff               = std::chrono::milliseconds{DebugGetLivePathIconFailureBackoffMs(1u)};
    const auto secondBackoff              = std::chrono::milliseconds{DebugGetLivePathIconFailureBackoffMs(2u)};
    state.Require(
        firstBackoff >= 1ms && secondBackoff == firstBackoff * 2,
        std::format(L"Live icon failure backoff should double from the first retry; first={}ms second={}ms.", firstBackoff.count(), secondBackoff.count()));

    SelfTestLatency::SetNextFailure(SelfTestLatency::Point::IconPathLiveLookup, E_ACCESSDENIED);
    const std::optional<int> firstIcon = IconCache::GetInstance().QuerySysIconIndexForPath(probePath.c_str(), FILE_ATTRIBUTE_NORMAL, false);
    const uint64_t consumesAfterFirst  = SelfTestLatency::ConsumeCount(SelfTestLatency::Point::IconPathLiveLookup);

    std::optional<int> secondIcon;
    for (uint64_t refreshIndex = 0u; refreshIndex < kRefreshesInsideBackoff; ++refreshIndex)
    {
        secondIcon = IconCache::GetInstance().QuerySysIconIndexForPath(probePath.c_str(), FILE_ATTRIBUTE_NORMAL, false);
        state.Require(! secondIcon.has_value(), L"Repeated live icon lookup inside the first backoff should remain negatively cached.");
    }
    const uint64_t consumesAfterSecond = SelfTestLatency::ConsumeCount(SelfTestLatency::Point::IconPathLiveLookup);

    std::this_thread::sleep_for(firstBackoff + 100ms);
    SelfTestLatency::SetNextFailure(SelfTestLatency::Point::IconPathLiveLookup, E_ACCESSDENIED);
    const std::optional<int> thirdIcon = IconCache::GetInstance().QuerySysIconIndexForPath(probePath.c_str(), FILE_ATTRIBUTE_NORMAL, false);
    const uint64_t consumesAfterThird  = SelfTestLatency::ConsumeCount(SelfTestLatency::Point::IconPathLiveLookup);

    std::this_thread::sleep_for(100ms);
    const std::optional<int> fourthIcon = IconCache::GetInstance().QuerySysIconIndexForPath(probePath.c_str(), FILE_ATTRIBUTE_NORMAL, false);
    const uint64_t consumesAfterFourth  = SelfTestLatency::ConsumeCount(SelfTestLatency::Point::IconPathLiveLookup);

    std::this_thread::sleep_for(secondBackoff + 100ms);
    const std::optional<int> fifthIcon = IconCache::GetInstance().QuerySysIconIndexForPath(probePath.c_str(), FILE_ATTRIBUTE_NORMAL, false);
    const uint64_t consumesAfterFifth  = SelfTestLatency::ConsumeCount(SelfTestLatency::Point::IconPathLiveLookup);

    const std::optional<int> sixthIcon = IconCache::GetInstance().QuerySysIconIndexForPath(probePath.c_str(), FILE_ATTRIBUTE_NORMAL, false);
    const uint64_t consumesAfterSixth  = SelfTestLatency::ConsumeCount(SelfTestLatency::Point::IconPathLiveLookup);

    state.Require(! firstIcon.has_value(), L"Forced transient live icon lookup failure should report no icon index.");
    state.Require(consumesAfterFirst == 1u,
                  std::format(L"Forced transient live icon lookup should consume exactly one live hook; consumed={}.", consumesAfterFirst));
    state.Require(! secondIcon.has_value(), L"Immediate repeated live icon lookup should use the first negative-cache backoff window.");
    state.Require(
        consumesAfterSecond == consumesAfterFirst,
        std::format(L"Immediate repeated live icon lookup should not re-enter the shell; before={} after={}.", consumesAfterFirst, consumesAfterSecond));
    state.Require(! thirdIcon.has_value(), L"Retry after the first backoff should reach the forced second shell failure.");
    state.Require(
        consumesAfterThird == consumesAfterSecond + 1u,
        std::format(L"Retry after the first backoff should perform exactly one shell lookup; before={} after={}.", consumesAfterSecond, consumesAfterThird));
    state.Require(! fourthIcon.has_value(), L"Lookup inside the doubled backoff should remain negatively cached.");
    state.Require(
        consumesAfterFourth == consumesAfterThird,
        std::format(L"Lookup inside the doubled backoff should not re-enter the shell; before={} after={}.", consumesAfterThird, consumesAfterFourth));
    state.Require(fifthIcon.has_value(), L"Retry after the doubled backoff should re-enter the shell and recover.");
    state.Require(
        consumesAfterFifth == consumesAfterFourth + 1u,
        std::format(L"Retry after the doubled backoff should perform exactly one shell lookup; before={} after={}.", consumesAfterFourth, consumesAfterFifth));
    state.Require(sixthIcon.has_value() && fifthIcon.has_value() && sixthIcon.value() == fifthIcon.value(),
                  L"Successful live icon lookup should replace and clear the negative entry with a positive cache entry.");
    state.Require(consumesAfterSixth == consumesAfterFifth,
                  std::format(L"Recovered success should be served from the positive cache; before={} after={}.", consumesAfterFifth, consumesAfterSixth));

    const uint64_t uncachedFailureRows  = FolderViewPerfMetricCountInRun(L"iconcache.path_live_lookup_failed_uncached", metricScanOffset);
    const uint64_t cachedFailureHitRows = FolderViewPerfMetricCountInRun(L"iconcache.path_live_lookup_failure_cache_hit", metricScanOffset);
    state.Require(uncachedFailureRows == 2u,
                  std::format(L"Two actual failed shell lookups should preserve two uncached-failure rows; rows={}.", uncachedFailureRows));
    state.Require(cachedFailureHitRows == kRefreshesInsideBackoff + 1u,
                  std::format(L"The first and doubled backoff windows should emit one cached-hit row per suppressed refresh; expected={} rows={}.",
                              kRefreshesInsideBackoff + 1u,
                              cachedFailureHitRows));
    Debug::Perf::Emit(L"icons.live_path_negative_backoff_shell_lookups.baseline_no_cache",
                      L"forced-live-failure-refreshes",
                      0u,
                      baselineShellLookups,
                      kRefreshesInsideBackoff,
                      S_OK);
    Debug::Perf::Emit(L"icons.live_path_negative_backoff_shell_lookups.candidate",
                      L"forced-live-failure-refreshes",
                      0u,
                      consumesAfterSecond,
                      kRefreshesInsideBackoff,
                      consumesAfterSecond == 1u ? S_OK : E_FAIL);
    Debug::Perf::Emit(L"icons.live_path_negative_backoff_shell_lookup_count",
                      L"two-failures-then-success",
                      0u,
                      consumesAfterSixth,
                      cachedFailureHitRows,
                      state.failure.empty() ? S_OK : E_FAIL);

    return state.failure.empty();
}

[[nodiscard]] bool TestFolderViewPerfIconPipelineColdSlow(HWND mainWindow, CaseState& state) noexcept
{
    using namespace std::chrono_literals;

    if (! mainWindow || ! IsWindow(mainWindow))
    {
        state.Require(false, L"Main window handle invalid for icon-pipeline cold/slow perf.");
        return false;
    }

    const std::filesystem::path suiteRoot = SelfTest::GetTempRoot(SelfTest::SelfTestSuite::Commands);
    state.Require(! suiteRoot.empty(), L"SelfTest temp root unavailable for icon-pipeline cold/slow perf.");
    if (suiteRoot.empty())
    {
        return false;
    }

    const std::wstring leftPluginBefore                   = std::wstring(g_folderWindow.GetFileSystemPluginId(FolderWindow::Pane::Left));
    const std::optional<std::filesystem::path> leftBefore = g_folderWindow.GetCurrentPath(FolderWindow::Pane::Left);
    const FolderView::DisplayMode displayBefore           = g_folderWindow.GetDisplayMode(FolderWindow::Pane::Left);
    const FolderView::SortBy sortBefore                   = g_folderWindow.GetSortBy(FolderWindow::Pane::Left);
    const FolderView::SortDirection directionBefore       = g_folderWindow.GetSortDirection(FolderWindow::Pane::Left);
    const auto restorePaneState                           = wil::scope_exit([&]() noexcept
    {
        SelfTestLatency::ClearAll();
        g_folderWindow.DebugSetThumbnailProviderMode(FolderWindow::Pane::Left, FolderView::DebugThumbnailProviderMode::Shell);
        static_cast<void>(g_folderWindow.SetFileSystemPluginForPane(FolderWindow::Pane::Left, leftPluginBefore));
        g_folderWindow.SetDisplayMode(FolderWindow::Pane::Left, displayBefore);
        g_folderWindow.SetSort(FolderWindow::Pane::Left, sortBefore, directionBefore);
        if (leftBefore.has_value())
        {
            g_folderWindow.SetFolderPath(FolderWindow::Pane::Left, leftBefore.value());
        }
    });

    const std::filesystem::path localRoot = suiteRoot / L"work" / (L"folder_icon_pipeline_cold_slow_" + NewGuidText());
    std::error_code ec;
    std::filesystem::remove_all(localRoot, ec);
    std::vector<std::wstring> localProbeNames;
    state.Require(CreateFolderViewIconPipelineLocalFixture(state, localRoot, localProbeNames), L"Failed to create icon-pipeline local cold/slow fixture.");
    if (! state.failure.empty())
    {
        return false;
    }

    state.Require(SUCCEEDED(g_folderWindow.SetFileSystemPluginForPane(FolderWindow::Pane::Left, L"builtin/file-system")),
                  L"Failed to switch left pane to local file system for icon-pipeline cold/slow perf.");
    g_folderWindow.SetDisplayMode(FolderWindow::Pane::Left, FolderView::DisplayMode::Detailed);
    g_folderWindow.SetSort(FolderWindow::Pane::Left, FolderView::SortBy::Name, FolderView::SortDirection::Ascending);
    g_folderWindow.DebugResetPaneVisibilityState(FolderWindow::Pane::Left);
    state.Require(g_folderWindow.DebugWarmPaneRendering(FolderWindow::Pane::Left), L"Icon-pipeline prewarm render failed.");
    if (! state.failure.empty())
    {
        return false;
    }

    IconCache::GetInstance().Clear();
    SelfTestLatency::ClearAll();
    const std::uintmax_t metricScanOffset = FolderViewPerfMetricScanOffset();
    SelfTestLatency::SetNextDelay(SelfTestLatency::Point::IconExtractSystemIcon, SelfTest::Scale(1600ms));

    const auto navigationStart = std::chrono::steady_clock::now();
    g_folderWindow.SetFolderPath(FolderWindow::Pane::Left, localRoot);
    state.Require(WaitForPanePath(FolderWindow::Pane::Left, localRoot, SelfTest::Scale(10000ms)), L"Icon-pipeline local cold/slow path did not load.");
    state.Require(WaitForFolderViewItemCount(FolderWindow::Pane::Left, localProbeNames.size(), SelfTest::Scale(10000ms)),
                  std::format(L"Icon-pipeline local item count mismatch; expected={} actual={}.",
                              localProbeNames.size(),
                              g_folderWindow.DebugGetItemCount(FolderWindow::Pane::Left)));
    for (const std::wstring& probeName : localProbeNames)
    {
        state.Require(g_folderWindow.DebugHasItemDisplayName(FolderWindow::Pane::Left, probeName),
                      std::format(L"Icon-pipeline local probe item '{}' did not load.", probeName));
    }
    if (! state.failure.empty())
    {
        return false;
    }

    const auto earlyIconStart                    = std::chrono::steady_clock::now();
    const bool resolvedBeforeSlowExtractFinished = WaitForFolderViewBitmapIconCount(FolderWindow::Pane::Left, 1u, SelfTest::Scale(700ms));
    const uint64_t earlyIconUs                   = Debug::Perf::ElapsedUs(earlyIconStart);
    state.Require(resolvedBeforeSlowExtractFinished,
                  std::format(L"One slow icon extraction should not stall all visible icon bitmaps; first bitmap wait was {}us.", earlyIconUs));

    state.Require(WaitForLatencyConsume(SelfTestLatency::Point::IconExtractSystemIcon, 1u, SelfTest::Scale(5000ms)),
                  L"Icon-pipeline cold/slow fixture did not exercise the icon-extraction latency hook.");
    state.Require(WaitForFolderViewBitmapIconCount(FolderWindow::Pane::Left, 2u, SelfTest::Scale(5000ms)),
                  L"Icon-pipeline cold/slow fixture did not resolve multiple bitmap icons.");
    if (! state.failure.empty())
    {
        // Let the delayed worker drain before restoring the pane.
        static_cast<void>(WaitForFolderViewBitmapIconCount(FolderWindow::Pane::Left, 1u, SelfTest::Scale(5000ms)));
    }
    static_cast<void>(g_folderWindow.DebugWarmPaneRendering(FolderWindow::Pane::Left));

    const uint64_t iconExtractLatencyConsumeCount = SelfTestLatency::ConsumeCount(SelfTestLatency::Point::IconExtractSystemIcon);
    const uint64_t bitmapIconCount                = g_folderWindow.DebugGetPaneBitmapIconCount(FolderWindow::Pane::Left);

    FolderViewDummyPluginHandles dummy{};
    state.Require(LoadFolderViewDummyPlugin(state, dummy), L"Failed to load dummy file system for icon-pipeline recall fixture.");
    if (! state.failure.empty())
    {
        return false;
    }

    std::string previousDummyConfig;
    state.Require(BackupPluginConfigurationForFolderViewPerf(dummy.informations.get(), previousDummyConfig),
                  L"Failed to snapshot dummy configuration for icon-pipeline recall fixture.");
    if (! state.failure.empty())
    {
        return false;
    }
    const auto restoreDummyConfig =
        wil::scope_exit([&]() noexcept { static_cast<void>(SetPluginConfigurationForFolderViewPerf(dummy.informations.get(), previousDummyConfig)); });

    constexpr std::string_view kEmptyDummyConfig =
        R"json({"maxChildrenPerDirectory":0,"maxDepth":10,"seed":45,"latencyMs":0,"streamChunkLatencyMs":0,"virtualSpeedLimit":"0"})json";
    state.Require(SetPluginConfigurationForFolderViewPerf(dummy.informations.get(), kEmptyDummyConfig),
                  L"Failed to apply deterministic dummy configuration for icon-pipeline recall fixture.");
    const std::filesystem::path dummyRoot = std::filesystem::path(L"/folderview-icon-recall") / SanitizeFolderViewDummyPathSegment(NewGuidText());
    state.Require(EnsureFolderViewDummyFolderExists(dummy.fileSystem.get(), dummyRoot), L"Failed to create dummy recall fixture root.");
    if (! state.failure.empty())
    {
        return false;
    }

    struct RecallProbeItem
    {
        std::wstring name;
        unsigned long attributes = FILE_ATTRIBUTE_ARCHIVE;
    };

    const unsigned long recallAttributes =
        FILE_ATTRIBUTE_ARCHIVE | FILE_ATTRIBUTE_OFFLINE | FILE_ATTRIBUTE_RECALL_ON_DATA_ACCESS | FILE_ATTRIBUTE_RECALL_ON_OPEN;
    std::vector<RecallProbeItem> recallItems{
        {L"offline_link.lnk", recallAttributes},
        {L"recall_shortcut.url", recallAttributes},
        {L"cloud_tool.exe", recallAttributes},
    };

    std::vector<std::wstring> recallProbeNames;
    recallProbeNames.reserve(recallItems.size());
    for (const RecallProbeItem& item : recallItems)
    {
        const std::filesystem::path itemPath = dummyRoot / item.name;
        state.Require(WriteTextFileFsIoForFolderViewPerf(dummy.io, itemPath, "icon recall fixture"),
                      std::format(L"Failed to create dummy recall item '{}'.", item.name));
        state.Require(SetFolderViewDummyItemAttributes(state, dummy, itemPath, item.attributes),
                      std::format(L"Failed to set dummy recall attributes for '{}'.", item.name));
        recallProbeNames.push_back(item.name);
    }
    if (! state.failure.empty())
    {
        return false;
    }

    IconCache::GetInstance().Clear();
    SelfTestLatency::ClearAll();
    SelfTestLatency::SetNextDelay(SelfTestLatency::Point::IconPathLiveLookup, SelfTest::Scale(500ms));
    state.Require(SUCCEEDED(g_folderWindow.SetFileSystemPluginForPane(FolderWindow::Pane::Left, kBuiltinDummyFileSystemIdForFolderViewPerf.data())),
                  L"Failed to switch left pane to dummy file system for icon-pipeline recall fixture.");
    g_folderWindow.SetDisplayMode(FolderWindow::Pane::Left, FolderView::DisplayMode::Detailed);
    g_folderWindow.SetSort(FolderWindow::Pane::Left, FolderView::SortBy::Name, FolderView::SortDirection::Ascending);
    g_folderWindow.DebugResetPaneVisibilityState(FolderWindow::Pane::Left);
    g_folderWindow.SetFolderPath(FolderWindow::Pane::Left, dummyRoot);
    state.Require(WaitForPanePluginPathForFolderViewPerf(FolderWindow::Pane::Left, dummyRoot, SelfTest::Scale(10000ms)),
                  L"Icon-pipeline recall dummy path did not load.");
    state.Require(WaitForFolderViewItemCount(FolderWindow::Pane::Left, recallProbeNames.size(), SelfTest::Scale(10000ms)),
                  std::format(L"Icon-pipeline recall item count mismatch; expected={} actual={}.",
                              recallProbeNames.size(),
                              g_folderWindow.DebugGetItemCount(FolderWindow::Pane::Left)));
    for (const std::wstring& probeName : recallProbeNames)
    {
        state.Require(g_folderWindow.DebugHasItemDisplayName(FolderWindow::Pane::Left, probeName),
                      std::format(L"Icon-pipeline recall probe item '{}' did not load.", probeName));
    }

    const uint64_t liveIconPathLookups = SelfTestLatency::ConsumeCount(SelfTestLatency::Point::IconPathLiveLookup);
    state.Require(liveIconPathLookups == 0u,
                  std::format(L"Offline/recall per-file icon lookup should use attributes only; live path lookups={}.", liveIconPathLookups));
    const uint64_t recallAvoidedRows = FolderViewPerfMetricCountInRun(L"icons.recall_avoided_count", metricScanOffset);
    state.Require(recallAvoidedRows >= recallItems.size(),
                  std::format(L"Missing icons.recall_avoided_count rows for offline/recall icon-index avoidance; expected-at-least={} actual={}.",
                              recallItems.size(),
                              recallAvoidedRows));

    SelfTestLatency::ClearAll();
    SelfTestLatency::SetNextDelay(SelfTestLatency::Point::ShellThumbnailProviderAllowed, SelfTest::Scale(500ms));
    g_folderWindow.DebugSetThumbnailProviderMode(FolderWindow::Pane::Left, FolderView::DebugThumbnailProviderMode::ForceProviderAllowedProbe);
    g_folderWindow.SetDisplayMode(FolderWindow::Pane::Left, FolderView::DisplayMode::Thumbnails);
    FolderWindow::PaneViewOptionsDebugSnapshot thumbnailSnapshot{};
    state.Require(WaitForPaneThumbnailStats(FolderWindow::Pane::Left,
                                            [](const FolderWindow::PaneViewOptionsDebugSnapshot& snapshot) noexcept
    { return snapshot.thumbnailPendingCount == 0u && snapshot.thumbnailFallbackCount > 0u; },
                                            SelfTest::Scale(5000ms),
                                            &thumbnailSnapshot),
                  L"Icon-pipeline recall thumbnail fallback did not settle.");
    const uint64_t thumbnailProviderConsumes = SelfTestLatency::ConsumeCount(SelfTestLatency::Point::ShellThumbnailProviderAllowed);
    state.Require(thumbnailProviderConsumes == 0u,
                  std::format(L"Offline/recall synthetic provider thumbnails should not invoke provider shell I/O; consumed={}.", thumbnailProviderConsumes));

    Debug::Perf::Emit(L"folder.icon_pipeline.early_visible_icon_us",
                      L"one-delayed-extract",
                      earlyIconUs,
                      resolvedBeforeSlowExtractFinished ? 1u : 0u,
                      iconExtractLatencyConsumeCount,
                      resolvedBeforeSlowExtractFinished ? S_OK : S_FALSE);
    Debug::Perf::Emit(
        L"folder.icon_pipeline.bitmap_icon_count", L"one-delayed-extract", 0u, bitmapIconCount, localProbeNames.size(), bitmapIconCount >= 2u ? S_OK : S_FALSE);

    static constexpr std::array<std::wstring_view, 13> kMetricAuditNames{{
        L"FolderView.ExecuteEnumeration.IconIndex.QueryExtensions",
        L"FolderView.ExecuteEnumeration.IconIndex.QueryPerFileIcons",
        L"FolderView.ExecuteEnumeration.IconIndex.BuildPerFilePaths",
        L"FolderView.IconLoading.ProcessQueue",
        L"FolderView.IconLoading.BatchUpdate",
        L"FolderView.IconLoading.BitmapConversion",
        L"icons.queue_wait_to_dequeue_us",
        L"icons.extract_us",
        L"icons.batch_update_scan_us",
        L"iconcache.shgetfileinfo_us",
        L"iconcache.lock_wait_slow_us",
        L"iconcache.lock_hold_slow_us",
        L"icons.recall_avoided_count",
    }};

    std::wstring json;
    json.append(L"{\n");
    json.append(L"  \"case\": \"folderView_perf_icon_pipeline_cold_slow\",\n");
    json.append(L"  \"localRoot\": ");
    AppendFolderViewColumnJsonString(json, localRoot.native());
    json.append(L",\n");
    json.append(L"  \"dummyRoot\": ");
    AppendFolderViewColumnJsonString(json, dummyRoot.generic_wstring());
    json.append(L",\n");
    json.append(std::format(L"  \"localItemCount\": {},\n", localProbeNames.size()));
    json.append(std::format(L"  \"recallItemCount\": {},\n", recallProbeNames.size()));
    json.append(std::format(L"  \"earlyVisibleIconUs\": {},\n", earlyIconUs));
    json.append(std::format(L"  \"resolvedBeforeSlowExtractFinished\": {},\n", resolvedBeforeSlowExtractFinished ? L"true" : L"false"));
    json.append(std::format(L"  \"iconExtractLatencyConsumeCount\": {},\n", iconExtractLatencyConsumeCount));
    json.append(std::format(L"  \"bitmapIconCount\": {},\n", bitmapIconCount));
    json.append(std::format(L"  \"iconPathLiveLookupConsumeCount\": {},\n", liveIconPathLookups));
    json.append(std::format(L"  \"recallAvoidedMetricRows\": {},\n", recallAvoidedRows));
    json.append(std::format(L"  \"thumbnailProviderAllowedConsumeCount\": {},\n", thumbnailProviderConsumes));
    json.append(std::format(L"  \"thumbnailFallbackCount\": {},\n", thumbnailSnapshot.thumbnailFallbackCount));
    json.append(L"  \"metricRows\": {\n");
    for (size_t i = 0; i < kMetricAuditNames.size(); ++i)
    {
        const std::wstring_view metricName = kMetricAuditNames[i];
        const uint64_t rowCount            = FolderViewPerfMetricCountInRun(metricName, metricScanOffset);
        json.append(L"    ");
        AppendFolderViewColumnJsonString(json, metricName);
        json.append(std::format(L": {}{}\n", rowCount, i + 1u < kMetricAuditNames.size() ? L"," : L""));
    }
    json.append(L"  },\n");
    AppendFolderViewEnvironmentMatrixJson(json, CaptureFolderViewEnvironmentMatrix(mainWindow), L"  ");
    json.append(L"\n");
    json.append(L"}\n");

    const std::filesystem::path artifactPath = SelfTest::GetPerfArtifactPath(L"folderView_perf_icon_pipeline_cold_slow_metrics.json");
    const bool artifactWriteOk               = ! artifactPath.empty() && SelfTest::WriteTextFile(artifactPath, json);
    state.Require(artifactWriteOk && SelfTest::PathExists(artifactPath), L"Failed to write icon-pipeline cold/slow perf artifact.");

    return state.failure.empty();
}

[[nodiscard]] bool CreateFolderViewIconCacheContentionFixture(
    CaseState& state, const std::filesystem::path& root, std::wstring_view prefix, std::wstring& firstProbe, std::wstring& lastProbe) noexcept
{
    state.Require(SelfTest::EnsureDirectory(root), std::format(L"Failed to create IconCache contention root {}.", prefix));
    if (! state.failure.empty())
    {
        return false;
    }

    constexpr size_t kItemCount       = 480u;
    constexpr size_t kUniqueExtension = 160u;
    for (size_t i = 0; i < kItemCount; ++i)
    {
        const std::wstring fileName = std::format(L"{}_file_{:03}.u{:03}", prefix, i, i % kUniqueExtension);
        state.Require(SelfTest::WriteTextFile(root / fileName, "iconcache contention"),
                      std::format(L"Failed to create IconCache contention file {}.", fileName));
        if (i == 0u)
        {
            firstProbe = fileName;
        }
        else if (i + 1u == kItemCount)
        {
            lastProbe = fileName;
        }
    }

    return state.failure.empty();
}

[[nodiscard]] bool TestFolderViewPerfIconCacheContention(HWND mainWindow, CaseState& state) noexcept
{
    using namespace std::chrono_literals;

    if (! mainWindow || ! IsWindow(mainWindow))
    {
        state.Require(false, L"Main window handle invalid for IconCache contention.");
        return false;
    }

    const std::filesystem::path suiteRoot = SelfTest::GetTempRoot(SelfTest::SelfTestSuite::Commands);
    state.Require(! suiteRoot.empty(), L"SelfTest temp root unavailable for IconCache contention.");
    if (suiteRoot.empty())
    {
        return false;
    }

    const std::filesystem::path root = suiteRoot / L"work" / (L"folder_iconcache_contention_" + NewGuidText());
    std::error_code ec;
    std::filesystem::remove_all(root, ec);

    const std::filesystem::path leftRoot  = root / L"left";
    const std::filesystem::path rightRoot = root / L"right";
    std::wstring leftFirst;
    std::wstring leftLast;
    std::wstring rightFirst;
    std::wstring rightLast;
    state.Require(CreateFolderViewIconCacheContentionFixture(state, leftRoot, L"left", leftFirst, leftLast),
                  L"Failed to create left IconCache contention fixture.");
    state.Require(CreateFolderViewIconCacheContentionFixture(state, rightRoot, L"right", rightFirst, rightLast),
                  L"Failed to create right IconCache contention fixture.");
    if (! state.failure.empty())
    {
        return false;
    }

    const std::wstring leftPluginBefore                    = std::wstring(g_folderWindow.GetFileSystemPluginId(FolderWindow::Pane::Left));
    const std::wstring rightPluginBefore                   = std::wstring(g_folderWindow.GetFileSystemPluginId(FolderWindow::Pane::Right));
    const std::optional<std::filesystem::path> leftBefore  = g_folderWindow.GetCurrentPath(FolderWindow::Pane::Left);
    const std::optional<std::filesystem::path> rightBefore = g_folderWindow.GetCurrentPath(FolderWindow::Pane::Right);
    const FolderView::DisplayMode leftDisplayBefore        = g_folderWindow.GetDisplayMode(FolderWindow::Pane::Left);
    const FolderView::DisplayMode rightDisplayBefore       = g_folderWindow.GetDisplayMode(FolderWindow::Pane::Right);
    const FolderView::SortBy leftSortBefore                = g_folderWindow.GetSortBy(FolderWindow::Pane::Left);
    const FolderView::SortBy rightSortBefore               = g_folderWindow.GetSortBy(FolderWindow::Pane::Right);
    const FolderView::SortDirection leftDirectionBefore    = g_folderWindow.GetSortDirection(FolderWindow::Pane::Left);
    const FolderView::SortDirection rightDirectionBefore   = g_folderWindow.GetSortDirection(FolderWindow::Pane::Right);
    const auto restoreState                                = wil::scope_exit([&]
    {
        static_cast<void>(g_folderWindow.SetFileSystemPluginForPane(FolderWindow::Pane::Left, leftPluginBefore));
        static_cast<void>(g_folderWindow.SetFileSystemPluginForPane(FolderWindow::Pane::Right, rightPluginBefore));
        g_folderWindow.SetDisplayMode(FolderWindow::Pane::Left, leftDisplayBefore);
        g_folderWindow.SetDisplayMode(FolderWindow::Pane::Right, rightDisplayBefore);
        g_folderWindow.SetSort(FolderWindow::Pane::Left, leftSortBefore, leftDirectionBefore);
        g_folderWindow.SetSort(FolderWindow::Pane::Right, rightSortBefore, rightDirectionBefore);
        if (leftBefore.has_value())
        {
            g_folderWindow.SetFolderPath(FolderWindow::Pane::Left, leftBefore.value());
        }
        if (rightBefore.has_value())
        {
            g_folderWindow.SetFolderPath(FolderWindow::Pane::Right, rightBefore.value());
        }
    });

    state.Require(SUCCEEDED(g_folderWindow.SetFileSystemPluginForPane(FolderWindow::Pane::Left, L"builtin/file-system")),
                  L"Failed to switch left pane to local file system for IconCache contention.");
    state.Require(SUCCEEDED(g_folderWindow.SetFileSystemPluginForPane(FolderWindow::Pane::Right, L"builtin/file-system")),
                  L"Failed to switch right pane to local file system for IconCache contention.");
    g_folderWindow.SetDisplayMode(FolderWindow::Pane::Left, FolderView::DisplayMode::Detailed);
    g_folderWindow.SetDisplayMode(FolderWindow::Pane::Right, FolderView::DisplayMode::Detailed);
    g_folderWindow.SetSort(FolderWindow::Pane::Left, FolderView::SortBy::Extension, FolderView::SortDirection::Ascending);
    g_folderWindow.SetSort(FolderWindow::Pane::Right, FolderView::SortBy::Extension, FolderView::SortDirection::Ascending);
    g_folderWindow.DebugResetPaneVisibilityState(FolderWindow::Pane::Left);
    g_folderWindow.DebugResetPaneVisibilityState(FolderWindow::Pane::Right);

    struct IconCacheContentionCycle
    {
        uint32_t index              = 0;
        uint64_t durationUs         = 0;
        size_t leftBitmapIconCount  = 0;
        size_t rightBitmapIconCount = 0;
        uint64_t leftQueueCalls     = 0;
        uint64_t rightQueueCalls    = 0;
        uint64_t leftBatchCalls     = 0;
        uint64_t rightBatchCalls    = 0;
    };

    std::vector<IconCacheContentionCycle> cycles;
    cycles.reserve(3u);

    const auto waitForBitmapIcons = [&](FolderWindow::Pane pane, size_t minimumCount, std::chrono::milliseconds timeout) noexcept
    {
        const auto deadline = std::chrono::steady_clock::now() + timeout;
        while (std::chrono::steady_clock::now() < deadline)
        {
            PumpPendingMessages();
            if (g_folderWindow.DebugGetPaneBitmapIconCount(pane) >= minimumCount)
            {
                return true;
            }
            std::this_thread::sleep_for(20ms);
        }
        return g_folderWindow.DebugGetPaneBitmapIconCount(pane) >= minimumCount;
    };

    for (uint32_t cycle = 0; cycle < 3u; ++cycle)
    {
        const bool swapRoots                        = (cycle % 2u) != 0u;
        const std::filesystem::path& cycleLeftRoot  = swapRoots ? rightRoot : leftRoot;
        const std::filesystem::path& cycleRightRoot = swapRoots ? leftRoot : rightRoot;
        const std::wstring& cycleLeftFirst          = swapRoots ? rightFirst : leftFirst;
        const std::wstring& cycleLeftLast           = swapRoots ? rightLast : leftLast;
        const std::wstring& cycleRightFirst         = swapRoots ? leftFirst : rightFirst;
        const std::wstring& cycleRightLast          = swapRoots ? leftLast : rightLast;

        const auto leftPerfBefore  = g_folderWindow.DebugGetWarmPanePerfSnapshot(FolderWindow::Pane::Left);
        const auto rightPerfBefore = g_folderWindow.DebugGetWarmPanePerfSnapshot(FolderWindow::Pane::Right);
        const auto start           = std::chrono::steady_clock::now();

        g_folderWindow.SetFolderPath(FolderWindow::Pane::Left, cycleLeftRoot);
        g_folderWindow.SetFolderPath(FolderWindow::Pane::Right, cycleRightRoot);
        state.Require(WaitForPanePath(FolderWindow::Pane::Left, cycleLeftRoot, SelfTest::Scale(10000ms)),
                      std::format(L"IconCache contention left path did not load for cycle {}.", cycle));
        state.Require(WaitForPanePath(FolderWindow::Pane::Right, cycleRightRoot, SelfTest::Scale(10000ms)),
                      std::format(L"IconCache contention right path did not load for cycle {}.", cycle));
        state.Require(WaitForFolderViewItemCount(FolderWindow::Pane::Left, 480u, SelfTest::Scale(10000ms)),
                      std::format(L"IconCache contention left item count mismatch for cycle {}.", cycle));
        state.Require(WaitForFolderViewItemCount(FolderWindow::Pane::Right, 480u, SelfTest::Scale(10000ms)),
                      std::format(L"IconCache contention right item count mismatch for cycle {}.", cycle));
        state.Require(WaitForPaneItems(FolderWindow::Pane::Left, {cycleLeftFirst, cycleLeftLast}, SelfTest::Scale(10000ms)),
                      std::format(L"IconCache contention left probe items missing for cycle {}.", cycle));
        state.Require(WaitForPaneItems(FolderWindow::Pane::Right, {cycleRightFirst, cycleRightLast}, SelfTest::Scale(10000ms)),
                      std::format(L"IconCache contention right probe items missing for cycle {}.", cycle));
        state.Require(g_folderWindow.DebugWarmPaneRendering(FolderWindow::Pane::Left),
                      std::format(L"IconCache contention left warm render failed for cycle {}.", cycle));
        state.Require(g_folderWindow.DebugWarmPaneRendering(FolderWindow::Pane::Right),
                      std::format(L"IconCache contention right warm render failed for cycle {}.", cycle));
        PumpPendingMessages();

        if (cycle > 0u)
        {
            g_folderWindow.CommandRefresh(FolderWindow::Pane::Left);
            g_folderWindow.CommandRefresh(FolderWindow::Pane::Right);
            PumpPendingMessages();
            state.Require(g_folderWindow.DebugWarmPaneRendering(FolderWindow::Pane::Left),
                          std::format(L"IconCache contention left refresh warm render failed for cycle {}.", cycle));
            state.Require(g_folderWindow.DebugWarmPaneRendering(FolderWindow::Pane::Right),
                          std::format(L"IconCache contention right refresh warm render failed for cycle {}.", cycle));
        }

        state.Require(waitForBitmapIcons(FolderWindow::Pane::Left, 1u, SelfTest::Scale(5000ms)),
                      std::format(L"IconCache contention left bitmap icons did not resolve for cycle {}.", cycle));
        state.Require(waitForBitmapIcons(FolderWindow::Pane::Right, 1u, SelfTest::Scale(5000ms)),
                      std::format(L"IconCache contention right bitmap icons did not resolve for cycle {}.", cycle));
        if (! state.failure.empty())
        {
            return false;
        }

        const auto elapsedUs = static_cast<uint64_t>(std::chrono::duration_cast<std::chrono::microseconds>(std::chrono::steady_clock::now() - start).count());
        const auto leftPerfAfter  = g_folderWindow.DebugGetWarmPanePerfSnapshot(FolderWindow::Pane::Left);
        const auto rightPerfAfter = g_folderWindow.DebugGetWarmPanePerfSnapshot(FolderWindow::Pane::Right);

        const uint64_t leftQueueCalls  = leftPerfAfter.queueIconLoadingCalls - leftPerfBefore.queueIconLoadingCalls;
        const uint64_t rightQueueCalls = rightPerfAfter.queueIconLoadingCalls - rightPerfBefore.queueIconLoadingCalls;
        const uint64_t leftBatchCalls  = leftPerfAfter.batchIconUpdateCalls - leftPerfBefore.batchIconUpdateCalls;
        const uint64_t rightBatchCalls = rightPerfAfter.batchIconUpdateCalls - rightPerfBefore.batchIconUpdateCalls;
        Debug::Perf::Emit(L"folder.iconcache_contention_cycle_us",
                          std::format(L"cycle={}", cycle),
                          elapsedUs,
                          leftQueueCalls + rightQueueCalls,
                          leftBatchCalls + rightBatchCalls,
                          S_OK);

        cycles.push_back(IconCacheContentionCycle{
            .index                = cycle,
            .durationUs           = elapsedUs,
            .leftBitmapIconCount  = g_folderWindow.DebugGetPaneBitmapIconCount(FolderWindow::Pane::Left),
            .rightBitmapIconCount = g_folderWindow.DebugGetPaneBitmapIconCount(FolderWindow::Pane::Right),
            .leftQueueCalls       = leftQueueCalls,
            .rightQueueCalls      = rightQueueCalls,
            .leftBatchCalls       = leftBatchCalls,
            .rightBatchCalls      = rightBatchCalls,
        });
    }

    std::wstring json;
    json.append(L"{\n");
    json.append(L"  \"case\": \"folderView_perf_iconcache_contention\",\n");
    json.append(L"  \"leftRoot\": ");
    AppendFolderViewColumnJsonString(json, leftRoot.native());
    json.append(L",\n");
    json.append(L"  \"rightRoot\": ");
    AppendFolderViewColumnJsonString(json, rightRoot.native());
    json.append(L",\n");
    json.append(L"  \"itemsPerPane\": 480,\n");
    json.append(L"  \"uniqueExtensionsPerPane\": 160,\n");
    json.append(L"  \"cycles\": [\n");
    for (size_t i = 0; i < cycles.size(); ++i)
    {
        const auto& cycle = cycles[i];
        json.append(L"    {\n");
        json.append(std::format(L"      \"index\": {},\n", cycle.index));
        json.append(std::format(L"      \"durationUs\": {},\n", cycle.durationUs));
        json.append(std::format(L"      \"leftBitmapIconCount\": {},\n", cycle.leftBitmapIconCount));
        json.append(std::format(L"      \"rightBitmapIconCount\": {},\n", cycle.rightBitmapIconCount));
        json.append(std::format(L"      \"leftQueueCalls\": {},\n", cycle.leftQueueCalls));
        json.append(std::format(L"      \"rightQueueCalls\": {},\n", cycle.rightQueueCalls));
        json.append(std::format(L"      \"leftBatchCalls\": {},\n", cycle.leftBatchCalls));
        json.append(std::format(L"      \"rightBatchCalls\": {}\n", cycle.rightBatchCalls));
        json.append(i + 1u < cycles.size() ? L"    },\n" : L"    }\n");
    }
    json.append(L"  ]\n");
    json.append(L"}\n");

    const std::filesystem::path artifactPath = SelfTest::GetPerfArtifactPath(L"folderView_perf_iconcache_contention_metrics.json");
    const bool artifactWriteOk               = ! artifactPath.empty() && SelfTest::WriteTextFile(artifactPath, json);
    state.Require(artifactWriteOk && SelfTest::PathExists(artifactPath), L"Failed to write IconCache contention perf artifact.");

    return state.failure.empty();
}

[[nodiscard]] bool TestToggleHiddenAndSystemFiles(HWND mainWindow, CaseState& state) noexcept
{
    using namespace std::chrono_literals;

    if (! mainWindow || ! IsWindow(mainWindow))
    {
        state.Require(false, L"Main window handle invalid.");
        return false;
    }

    const std::filesystem::path suiteRoot = SelfTest::GetTempRoot(SelfTest::SelfTestSuite::Commands);
    state.Require(! suiteRoot.empty(), L"SelfTest temp root unavailable.");
    if (suiteRoot.empty())
    {
        return false;
    }

    const std::filesystem::path root = suiteRoot / L"work" / (L"hidden_system_" + NewGuidText());
    std::error_code ec;
    std::filesystem::remove_all(root, ec);
    state.Require(SelfTest::EnsureDirectory(root), L"Failed to create hidden/system test root.");

    const std::filesystem::path normal = root / L"normal.txt";
    const std::filesystem::path hidden = root / L"hidden.txt";
    const std::filesystem::path system = root / L"system.txt";
    state.Require(SelfTest::WriteTextFile(normal, "n"), L"Failed to create normal.txt.");
    state.Require(SelfTest::WriteTextFile(hidden, "h"), L"Failed to create hidden.txt.");
    state.Require(SelfTest::WriteTextFile(system, "s"), L"Failed to create system.txt.");

    const auto applyAttrs = [&](const std::filesystem::path& path, DWORD attrs, std::wstring_view label) noexcept
    {
        if (::SetFileAttributesW(path.c_str(), attrs) == FALSE)
        {
            const DWORD err = GetLastError();
            state.Require(false, std::format(L"Failed to SetFileAttributesW for {} (err={}).", label, err));
        }
    };

    applyAttrs(hidden, FILE_ATTRIBUTE_HIDDEN, L"hidden.txt");
    applyAttrs(system, FILE_ATTRIBUTE_SYSTEM, L"system.txt");

    const std::optional<std::filesystem::path> leftBefore = g_folderWindow.GetCurrentPath(FolderWindow::Pane::Left);
    const auto restorePath                                = wil::scope_exit([&]
    {
        if (leftBefore.has_value())
        {
            g_folderWindow.SetFolderPath(FolderWindow::Pane::Left, leftBefore.value());
        }
    });

    g_folderWindow.DebugResetPaneVisibilityState(FolderWindow::Pane::Left);

    const bool showHiddenBefore = g_folderWindow.GetShowHiddenFiles();
    const bool showSystemBefore = g_folderWindow.GetShowSystemFiles();
    const auto restoreFlags     = wil::scope_exit([&]
    {
        g_folderWindow.SetShowHiddenFiles(showHiddenBefore);
        g_folderWindow.SetShowSystemFiles(showSystemBefore);
    });

    g_folderWindow.SetShowHiddenFiles(true);
    g_folderWindow.SetShowSystemFiles(true);

    std::atomic<uint32_t> enumCount{0};
    g_folderWindow.SetPaneEnumerationCompletedCallback(FolderWindow::Pane::Left,
                                                       [&](const std::filesystem::path& folder) noexcept
    {
        if (OrdinalString::EqualsNoCasePath(folder, root))
        {
            enumCount.fetch_add(1u, std::memory_order_release);
        }
    });
    const auto clearEnumCallback = wil::scope_exit([&] { g_folderWindow.SetPaneEnumerationCompletedCallback(FolderWindow::Pane::Left, {}); });

    g_folderWindow.SetFolderPath(FolderWindow::Pane::Left, root);
    state.Require(WaitForPanePath(FolderWindow::Pane::Left, root, SelfTest::Scale(std::chrono::milliseconds{3000})),
                  L"Failed to set pane path for hidden/system test.");
    state.Require(WaitForPaneItems(FolderWindow::Pane::Left, {L"normal.txt", L"hidden.txt", L"system.txt"}, SelfTest::Scale(std::chrono::milliseconds{3000})),
                  L"Pane contents not ready for hidden/system test.");

    state.Require(g_folderWindow.DebugHasItemDisplayName(FolderWindow::Pane::Left, L"normal.txt"), L"Expected normal.txt visible.");
    state.Require(g_folderWindow.DebugHasItemDisplayName(FolderWindow::Pane::Left, L"hidden.txt"), L"Expected hidden.txt visible when enabled.");
    state.Require(g_folderWindow.DebugHasItemDisplayName(FolderWindow::Pane::Left, L"system.txt"), L"Expected system.txt visible when enabled.");

    const auto waitForExactPaneItems = [&](std::initializer_list<std::wstring_view> expectedDisplayNames, std::chrono::milliseconds timeout) noexcept
    {
        const auto deadline = std::chrono::steady_clock::now() + timeout;
        while (std::chrono::steady_clock::now() < deadline)
        {
            PumpPendingMessages();

            bool allFound = true;
            for (const std::wstring_view displayName : expectedDisplayNames)
            {
                if (! g_folderWindow.DebugHasItemDisplayName(FolderWindow::Pane::Left, displayName))
                {
                    allFound = false;
                    break;
                }
            }

            if (allFound && g_folderWindow.DebugGetItemCount(FolderWindow::Pane::Left) == expectedDisplayNames.size())
            {
                return true;
            }

            std::this_thread::sleep_for(20ms);
        }

        std::wstring expected;
        for (const std::wstring_view displayName : expectedDisplayNames)
        {
            if (! expected.empty())
            {
                expected.append(L", ");
            }
            expected.append(displayName);
        }
        Trace(std::format(L"Hidden/system exact pane wait timed out. expected='{}' actualCount={} normal={} hidden={} system={}",
                          expected,
                          g_folderWindow.DebugGetItemCount(FolderWindow::Pane::Left),
                          g_folderWindow.DebugHasItemDisplayName(FolderWindow::Pane::Left, L"normal.txt") ? 1 : 0,
                          g_folderWindow.DebugHasItemDisplayName(FolderWindow::Pane::Left, L"hidden.txt") ? 1 : 0,
                          g_folderWindow.DebugHasItemDisplayName(FolderWindow::Pane::Left, L"system.txt") ? 1 : 0));
        return false;
    };

    FocusFolderViewPane(FolderWindow::Pane::Left);
    SendMessageW(mainWindow, WM_COMMAND, MAKEWPARAM(IDM_VIEW_PANE_HIDDEN_FILES, 0), 0);
    state.Require(WaitForAtomicAtLeast(enumCount, 2u, SelfTest::Scale(std::chrono::milliseconds{3000})), L"Enumeration did not refresh after hidden toggle.");
    state.Require(waitForExactPaneItems({L"normal.txt", L"system.txt"}, SelfTest::Scale(3000ms)), L"Pane contents did not settle after hidden toggle.");
    state.Require(! g_folderWindow.DebugHasItemDisplayName(FolderWindow::Pane::Left, L"hidden.txt"), L"Expected hidden.txt to be hidden when disabled.");
    state.Require(g_folderWindow.DebugHasItemDisplayName(FolderWindow::Pane::Left, L"system.txt"),
                  L"system.txt should remain visible when only hidden is disabled.");

    SendMessageW(mainWindow, WM_COMMAND, MAKEWPARAM(IDM_VIEW_PANE_SYSTEM_FILES, 0), 0);
    state.Require(WaitForAtomicAtLeast(enumCount, 3u, SelfTest::Scale(std::chrono::milliseconds{3000})), L"Enumeration did not refresh after system toggle.");
    state.Require(waitForExactPaneItems({L"normal.txt"}, SelfTest::Scale(3000ms)), L"Pane contents did not settle after system toggle.");
    state.Require(! g_folderWindow.DebugHasItemDisplayName(FolderWindow::Pane::Left, L"system.txt"), L"Expected system.txt to be hidden when disabled.");

    SendMessageW(mainWindow, WM_COMMAND, MAKEWPARAM(IDM_VIEW_PANE_HIDDEN_FILES, 0), 0);
    state.Require(WaitForAtomicAtLeast(enumCount, 4u, SelfTest::Scale(std::chrono::milliseconds{3000})),
                  L"Enumeration did not refresh after re-enabling hidden.");
    state.Require(waitForExactPaneItems({L"normal.txt", L"hidden.txt"}, SelfTest::Scale(3000ms)), L"Pane contents did not settle after re-enabling hidden.");
    state.Require(g_folderWindow.DebugHasItemDisplayName(FolderWindow::Pane::Left, L"hidden.txt"), L"Expected hidden.txt visible after re-enabling hidden.");
    state.Require(! g_folderWindow.DebugHasItemDisplayName(FolderWindow::Pane::Left, L"system.txt"),
                  L"system.txt should remain hidden while system is disabled.");

    SendMessageW(mainWindow, WM_COMMAND, MAKEWPARAM(IDM_VIEW_PANE_SYSTEM_FILES, 0), 0);
    state.Require(WaitForAtomicAtLeast(enumCount, 5u, SelfTest::Scale(std::chrono::milliseconds{3000})),
                  L"Enumeration did not refresh after re-enabling system.");
    state.Require(waitForExactPaneItems({L"normal.txt", L"hidden.txt", L"system.txt"}, SelfTest::Scale(3000ms)),
                  L"Pane contents did not settle after re-enabling system.");
    state.Require(g_folderWindow.DebugHasItemDisplayName(FolderWindow::Pane::Left, L"system.txt"), L"Expected system.txt visible after re-enabling system.");

    return state.failure.empty();
}

[[nodiscard]] bool TestSelectSameExtensionCommands(HWND mainWindow, CaseState& state) noexcept
{
    using namespace std::chrono_literals;

    if (! mainWindow || ! IsWindow(mainWindow))
    {
        state.Require(false, L"Main window handle invalid.");
        return false;
    }

    const std::filesystem::path suiteRoot = SelfTest::GetTempRoot(SelfTest::SelfTestSuite::Commands);
    state.Require(! suiteRoot.empty(), L"SelfTest temp root unavailable.");
    if (suiteRoot.empty())
    {
        return false;
    }

    const std::filesystem::path root = suiteRoot / L"work" / (L"same_extension_" + NewGuidText());
    std::error_code ec;
    std::filesystem::remove_all(root, ec);
    state.Require(SelfTest::EnsureDirectory(root), L"Failed to create same-extension test root.");

    state.Require(SelfTest::WriteTextFile(root / L"a.txt", "a"), L"Failed to create a.txt.");
    state.Require(SelfTest::WriteTextFile(root / L"b.txt", "b"), L"Failed to create b.txt.");
    state.Require(SelfTest::WriteTextFile(root / L"c.log", "c"), L"Failed to create c.log.");

    const std::optional<std::filesystem::path> leftBefore = g_folderWindow.GetCurrentPath(FolderWindow::Pane::Left);
    const auto restorePath                                = wil::scope_exit([&]
    {
        if (leftBefore.has_value())
        {
            g_folderWindow.SetFolderPath(FolderWindow::Pane::Left, leftBefore.value());
        }
    });

    g_folderWindow.DebugResetPaneVisibilityState(FolderWindow::Pane::Left);

    std::atomic<uint32_t> enumCount{0};
    g_folderWindow.SetPaneEnumerationCompletedCallback(FolderWindow::Pane::Left,
                                                       [&](const std::filesystem::path& folder) noexcept
    {
        if (OrdinalString::EqualsNoCasePath(folder, root))
        {
            enumCount.fetch_add(1u, std::memory_order_release);
        }
    });
    const auto clearEnumCallback = wil::scope_exit([&] { g_folderWindow.SetPaneEnumerationCompletedCallback(FolderWindow::Pane::Left, {}); });

    g_folderWindow.SetFolderPath(FolderWindow::Pane::Left, root);
    state.Require(WaitForPanePath(FolderWindow::Pane::Left, root, SelfTest::Scale(std::chrono::milliseconds{3000})),
                  L"Failed to set pane path for same-extension test.");
    state.Require(WaitForPaneItems(FolderWindow::Pane::Left, {L"a.txt", L"b.txt", L"c.log"}, SelfTest::Scale(std::chrono::milliseconds{3000})),
                  L"Pane contents not ready for same-extension test.");

    state.Require(g_folderWindow.DebugFocusItemByDisplayName(FolderWindow::Pane::Left, L"a.txt"), L"Failed to focus a.txt.");
    g_folderWindow.SetPaneSelectionByDisplayNamePredicate(FolderWindow::Pane::Left, [](std::wstring_view name) noexcept { return name == L"c.log"; }, true);
    state.Require(g_folderWindow.DebugIsItemSelected(FolderWindow::Pane::Left, L"c.log"), L"Expected c.log selected before select-same-extension.");

    FocusFolderViewPane(FolderWindow::Pane::Left);
    SendMessageW(mainWindow, WM_COMMAND, MAKEWPARAM(IDM_PANE_SELECTION_SELECT_SAME_EXTENSION, 0), 0);

    state.Require(g_folderWindow.DebugIsItemSelected(FolderWindow::Pane::Left, L"a.txt"), L"Expected a.txt selected after select-same-extension.");
    state.Require(g_folderWindow.DebugIsItemSelected(FolderWindow::Pane::Left, L"b.txt"), L"Expected b.txt selected after select-same-extension.");
    state.Require(g_folderWindow.DebugIsItemSelected(FolderWindow::Pane::Left, L"c.log"), L"Expected c.log to remain selected after select-same-extension.");
    state.Require(g_folderWindow.DebugGetSelectedCount(FolderWindow::Pane::Left) == 3u, L"Expected 3 selected items after select-same-extension.");

    SendMessageW(mainWindow, WM_COMMAND, MAKEWPARAM(IDM_PANE_SELECTION_UNSELECT_SAME_EXTENSION, 0), 0);

    state.Require(! g_folderWindow.DebugIsItemSelected(FolderWindow::Pane::Left, L"a.txt"), L"Expected a.txt unselected after unselect-same-extension.");
    state.Require(! g_folderWindow.DebugIsItemSelected(FolderWindow::Pane::Left, L"b.txt"), L"Expected b.txt unselected after unselect-same-extension.");
    state.Require(g_folderWindow.DebugIsItemSelected(FolderWindow::Pane::Left, L"c.log"), L"Expected c.log to remain selected after unselect-same-extension.");
    state.Require(g_folderWindow.DebugGetSelectedCount(FolderWindow::Pane::Left) == 1u, L"Expected 1 selected item after unselect-same-extension.");

    return state.failure.empty();
}

